local output = {}

DEFAULT_CHAT_FRAME = {
    AddMessage = function(self, msg)
        msg = msg:gsub("|c%x%x%x%x%x%x%x%x", ""):gsub("|r", "")
        table.insert(output, msg)
        print("  " .. msg)
    end,
}

UIParent     = Frame()

-- THE SCREEN IS 768 UI UNITS TALL, NOT 300. 0.85.0.
--
-- The stub answered its generic default for the one frame whose height is a
-- hard limit on every other frame in the addon -- so "does the window fit on
-- the screen at the largest size the player can choose" was a question no
-- test could ask honestly. 768 is the height UIParent reports on every
-- resolution: the client scales the UI to it.
UIParent:SetHeight(768)
UIParent:SetWidth(1024)
SlashCmdList = {}

-- THE CLIENT'S FONT TEMPLATES, AND THE FUNCTION THAT DERIVES FROM THEM.
--
-- The addon reads a template's file, size and flags and builds a larger copy
-- for the text-size setting. None of that existed here, so the whole feature
-- short-circuited on `not CreateFont` and the suite would have passed with it
-- doing nothing at all -- which is the shape of half the defects in this
-- file's history. 0.66.0.
function CN_TEST_FontTemplate(size)
    local font = { file = "Fonts\\FRIZQT__.TTF", size = size, flags = "" }

    function font:GetFont() return font.file, font.size, font.flags end

    function font:SetFont(file, points, flags)
        font.file, font.size, font.flags = file, points, flags
    end

    function font:GetTextColor() return 1, 1, 1, 1 end
    function font:SetTextColor() end
    function font:GetJustifyH() return "LEFT" end
    function font:SetJustifyH() end

    return font
end

GameFontNormalLarge    = CN_TEST_FontTemplate(16)
GameFontNormal         = CN_TEST_FontTemplate(13)
GameFontHighlightLeft  = CN_TEST_FontTemplate(13)
GameFontHighlightSmall = CN_TEST_FontTemplate(11)
GameFontDisableSmall   = CN_TEST_FontTemplate(11)
GameFontNormalSmall    = CN_TEST_FontTemplate(11)
GameFontHighlightLarge = CN_TEST_FontTemplate(16)

CN_TEST_FONTS_CREATED = 0

function CreateFont(name)
    CN_TEST_FONTS_CREATED = CN_TEST_FONTS_CREATED + 1

    local font = CN_TEST_FontTemplate(13)

    font.name = name

    return font
end

-- WoW exposes these as globals.
--
-- `time` is offsettable, because several caches in the addon are throttled on
-- WALL-CLOCK seconds and a suite that cannot move the wall clock cannot test
-- a throttle at all. `CN_TEST_TIME_OFFSET` is added to every reading, so a
-- test can say "and now it is thirty-one seconds later" without sleeping.
CN_TEST_TIME_OFFSET = 0

time    = function(...)
    return os.time(...) + CN_TEST_TIME_OFFSET
end

date    = os.date

-- Millisecond profiler. Present in the client, absent in plain Lua, so the
-- provider-timing path would otherwise never execute offline.
function debugprofilestop() return os.clock() * 1000 end
strtrim = function(s) return (tostring(s):gsub("^%s+", ""):gsub("%s+$", "")) end

-- The world map, modelled with the shape MapPins actually reads.
--
-- Deliberately NOT a flat universal stub. The canvas has a real width and
-- height because the pin arithmetic multiplies by them, and a stub returning
-- a table there would turn a sign error into "attempt to perform arithmetic
-- on a table value" -- an error about the stub, not about the addon. The
-- displayed map is settable so the test can look at a map the player is not
-- standing in, which is the case the routing start point gets wrong.
local worldMapHooks = {}

WorldMapFrame = {
    displayedMapID = 2112,
    shown          = false,

    ScrollContainer = {
        Child = (function()
            local canvas = Frame()
            function canvas:GetWidth()  return 1000 end
            function canvas:GetHeight() return 666 end
            return canvas
        end)(),
    },
}

function WorldMapFrame:GetMapID() return self.displayedMapID end
function WorldMapFrame:IsShown()  return self.shown == true end
function WorldMapFrame:HookScript(script, handler)
    worldMapHooks[script] = worldMapHooks[script] or {}
    table.insert(worldMapHooks[script], handler)
end

CN_TEST_WORLD_MAP_HOOKS = worldMapHooks

-- Map topology. A player standing in a city is on a CHILD map; the zone's
-- quest starts are registered against the parent. Modelling every map as an
-- island is what let "0 available" ship while a quest giver was in view.
-- One table, not six locals: the main chunk is at Lua's 200-local ceiling,
-- and a fixture that cannot compile is not a fixture.
-- WoW runs Lua 5.1, where unpack is a global and table.unpack does not exist.
-- This suite normally runs 5.4, where the reverse is true. Running it under
-- BOTH is how the two-argument math.atan defect was finally caught, so the
-- harness itself has to work in both.
local UNPACK = rawget(table, "unpack") or unpack

local F = {}

F.mapTree = {
    [94]   = { name = "Eversong Woods", parentMapID = 1941, mapType = 3 },
    [2112] = { name = "Valdrakken",     parentMapID = 2022, mapType = 4 },
    [2022] = { name = "The Waking Shores", parentMapID = 1978, mapType = 3 },
    [1941] = { name = "Quel'Thalas",    parentMapID = 0,     mapType = 2 },
    [1978] = { name = "Dragon Isles",   parentMapID = 0,     mapType = 2 },
}

-- Zone names are read back by name-matching code, so a test needs to be able
-- to stand somewhere with a name it chose.
function CN_TEST_SetMapName(mapID, name)
    if not name then
        F.mapTree[mapID] = nil

        return
    end

    F.mapTree[mapID] = F.mapTree[mapID] or { mapType = 3 }
    F.mapTree[mapID].name = name
end

-- Stand the player somewhere. nil restores the default zone; `false` makes
-- the client refuse to answer at all, which is what a loading screen looks
-- like from inside this addon.
function CN_TEST_SetPlayerMap(mapID)
    if mapID == nil then
        CN_TEST_PLAYER_MAP  = nil
        CN_TEST_REFUSE_MAP  = true

        return
    end

    CN_TEST_PLAYER_MAP  = mapID
    CN_TEST_REFUSE_MAP  = nil
    CN_TEST_PLAYER_MAPS[mapID] = true
end

-- A test that is about the map GRAPH needs to be able to build one: a room
-- inside a zone, so `Blizzard.ZoneMapID` has something to walk up.
function CN_TEST_MapParent(mapID, parentMapID, mapType)
    F.mapTree[mapID] = F.mapTree[mapID] or { name = "Map" .. tostring(mapID) }
    F.mapTree[mapID].parentMapID = parentMapID
    F.mapTree[mapID].mapType     = mapType or 4
end

