CN_TEST_OBJECTIVES = {
    [9001] = {
        { text = "Sunscale Feathers", type = "item",
          numFulfilled = 11, numRequired = 12, finished = false },
    },
    [9002] = {
        { text = "Boars slain", type = "monster",
