CN_TEST_MAIL = {
    { sender = "Auction House", subject = "Sold", money = 100, items = 0, daysLeft = 1.5 },
    { sender = "A Friend",      subject = "Here", money = 0,   items = 2, daysLeft = 2.0 },
    { sender = "Nobody",        subject = "Old",  money = 0,   items = 0, daysLeft = 0.5 },
    { sender = "A Friend",      subject = "Later", money = 0,  items = 1, daysLeft = 25 },
}

-- RETAIL SCALE FOR THE NEWEST SUBSYSTEMS.
--
-- The fixtures for bags, sets and mail were written to be READ -- three
-- items, three sets, four messages -- which is right for a test that asserts
-- behaviour and completely wrong for a benchmark. At that size every one of
-- the 0.44.0 and 0.45.0 providers measured under a fiftieth of a millisecond,
-- which says nothing at all about what they cost a player with five full bags
-- and three thousand appearance sets.
--
-- That is the same trap this project has fallen into eight times: a fixture
-- simpler than reality, agreeing with the code. So the bench grows them to
-- the size the game actually produces, and the tests keep the small ones.
if CN_BENCH then
    -- Five bags of thirty-six, nearly full.
    for bag = 0, 4 do
        CN_TEST_BAGS[bag] = CN_TEST_BAGS[bag] or {}

        for slot = 1, 36 do
            CN_TEST_BAGS[bag][slot] = CN_TEST_BAGS[bag][slot] or {
                itemID     = 200000 + (bag * 100) + slot,
                stackCount = 1,
            }
        end
    end

    -- Three thousand appearance sets, which is roughly what the game holds.
    for index = 4, 3000 do
        CN_TEST_SETS[index] = {
            setID = index,
            name  = "Set " .. index,
            collected = false,
            pieces = { true, true, false, false, false },
        }
    end

    -- A mailbox somebody has not emptied in a while.
    for index = 5, 50 do
        CN_TEST_MAIL[index] = {
            sender = "Sender " .. index, subject = "Subject " .. index,
            money = 0, items = 1, daysLeft = 5 + (index % 20),
        }
    end

    -- A CONTINENT'S WORTH OF FLIGHT POINTS.
    --
    -- Three nodes, one of them undiscovered, is a fixture written to be read.
    -- A levelled character has upwards of sixty on a continent, and the route
    -- search deliberately tries EVERY PAIR of them -- so its cost grows as the
    -- square of a number this fixture had quietly set to two.
    for index = 4, 60 do
        CN_TEST_TAXI_NODES[1941][index] = {
            nodeID   = index,
            name     = "Node " .. index,
            state    = 1,
            -- CLUSTERED IN A FAR CORNER, DELIBERATELY.
            --
            -- These exist to make the pair search do sixty-squared work, not
            -- to change any answer. Spread across the map they start winning
            -- journeys the tests assert are quicker on foot -- which would
            -- mean weakening real assertions to accommodate a benchmark, and
            -- an assertion weakened for the tooling's convenience is an
            -- assertion that has stopped checking.
            --
            -- BUT A CORNER CLUSTER IS NOT A CONTINENT, and since the pair
            -- search gained a pruning bound that difference stopped being
            -- cosmetic: a cluster is precisely the geometry the bound rejects
            -- unexamined. One origin of fifty-nine survived here against
            -- seventeen of sixty on a real continent, so the benchmark was
            -- measuring a square the prune never walks -- and reported both
            -- travel budgets at a fifth of their ceiling while a real network
            -- was over both.
            --
            -- Resolved by doing it in two places rather than compromising in
            -- one: the assertions keep this layout, and `bench.lua` spreads
            -- the same nodes across the map after the suite has run and
            -- before it measures anything. See BENCH: A REAL FLIGHT NETWORK.
            position = {
                x = 0.94 + ((index % 10) * 0.006),
                y = 0.94 + ((index % 7) * 0.008),
            },
        }
    end

    -- A full quest log, every quest with counting objectives.
    for index = 1, 25 do
        local questID = 95000 + index

        CN_TEST_OBJECTIVES[questID] = {
            { text = "Thing " .. index, numFulfilled = index % 12,
              numRequired = 12, finished = false },
            { text = "Other " .. index, numFulfilled = 1,
              numRequired = 8, finished = false },
        }
    end
end

-- THE INBOX IS EMPTY UNTIL IT IS ASKED FOR.
-- CN_TEST_INBOX_UNREQUESTED, 1.4.0.
--
-- `GetInboxNumItems()` answers zero until the client has been handed the
-- inbox, and `CheckInbox()` is what asks the server for it. This stub answered
-- from the fixture from the first release, so the state every player is in at
-- login had never existed here -- and the addon's own `/cn waiting` carried a
-- sentence apologising for the limitation instead of removing it.
--
-- Twenty-second entry in this project's list of defects hidden by a stub that
-- skips a precondition the client enforces, and the fourth system in three
-- releases where the missing piece was a REQUEST rather than a read.
CN_TEST_INBOX_UNREQUESTED = false
CN_TEST_INBOX_REQUESTS    = 0

function CheckInbox()
    CN_TEST_INBOX_REQUESTS = CN_TEST_INBOX_REQUESTS + 1

    -- The server answering. In the client this is asynchronous and arrives as
    -- MAIL_INBOX_UPDATE; fired here so the addon's own flag moves the way it
    -- would in game rather than only when a count happens to be non-zero.
    CN_TEST_INBOX_UNREQUESTED = false

    if CN and CN.FireEvent then
        CN.FireEvent("MAIL_INBOX_UPDATE")
    end
end

function GetInboxNumItems()
    if CN_TEST_INBOX_UNREQUESTED then
        return 0
    end

    return #CN_TEST_MAIL
end

function GetInboxHeaderInfo(index)
    local mail = CN_TEST_MAIL[index]

    if not mail then
        return nil
    end

    -- packageIcon, stationeryIcon, sender, subject, money, CODAmount,
    -- daysLeft, itemCount
    return nil, nil, mail.sender, mail.subject, mail.money, 0,
        mail.daysLeft, mail.items
end

-- WHERE YOUR BODY IS.
--
-- The client will tell you, and the addon never asked -- it ranked everything
-- down for being dead and then pointed at nothing. Modelled here so the path
-- is exercised rather than assumed.
CN_TEST_CORPSE = { x = 0.31, y = 0.62 }

