local superTracked = nil

C_SuperTrack = {
    SetSuperTrackedUserWaypoint = function() end,
    SetSuperTrackedQuestID      = function(id) superTracked = id end,
    GetSuperTrackedQuestID      = function() return superTracked end,
}

-- Overrides for the completion answer, set by CN_TEST_TurnInQuest.
CN_TEST_COMPLETED = {}

-- THE CLIENT'S LOG HAS ZONE HEADERS IN IT. 0.91.0.
--
-- `C_QuestLog.GetNumQuestLogEntries` counts header rows as well as quests and
-- `GetInfo` returns `isHeader = true, questID = 0` for them.
-- `Blizzard.GetQuestLogEntries` filters on exactly that -- and with a fixture
-- containing no headers, the filter had never been exercised once.
--
-- Twenty-first entry in this project's list of defects a stub simpler than
-- the client made invisible.
local questLog = {
    { questID = 0,    title = "Khaz Algar",             isHeader = true },
    { questID = 8237, title = "Vanquish the Invaders!", isHeader = false },
    { questID = 9001, title = "Test Quest Alpha",       isHeader = false },
    { questID = 0,    title = "Dungeon",                isHeader = true },
    { questID = 9002, title = "Test Quest Beta",        isHeader = false },
}

-- Turning one in: out of the log, and completed from now on. Returns whether
-- it was actually in the log, so a test cannot silently assert about a quest
-- that was never there.
--
-- `CN_TEST_RestoreQuestLog()` puts the fixture back. A test that leaves the
-- world changed is a test that breaks a later one for a reason nobody can see
-- from either of them.
local originalQuestLog = {}

function CN_TEST_RestoreQuestLog()
    for index = #questLog, 1, -1 do
        questLog[index] = nil
    end

    for index, entry in ipairs(originalQuestLog) do
        questLog[index] = {
            questID  = entry.questID,
            title    = entry.title,
            isHeader = entry.isHeader,
        }
    end

    for key in pairs(CN_TEST_COMPLETED) do
        CN_TEST_COMPLETED[key] = nil
    end
end

function CN_TEST_TurnInQuest(questID)
    local removed = false

    for index = #questLog, 1, -1 do
        if questLog[index].questID == questID then
            table.remove(questLog, index)

            removed = true
        end
    end

    CN_TEST_COMPLETED[questID] = true

    return removed
end

for index, entry in ipairs(questLog) do
    originalQuestLog[index] = {
        questID  = entry.questID,
        title    = entry.title,
        isHeader = entry.isHeader,
    }
end

-- Titles the client knows about but which are NOT in the log: available
-- quests still have names.
local offeredTitles = {
    [9100] = "Pick Me Up",
    [9101] = "Already Done",
    [9102] = "Daily Offer",
}

local pendingLoad = {}

-- A REQUESTED TITLE ARRIVES. CN_TEST_LOADABLE_TITLES, 1.2.0.
--
-- `RequestLoadQuestByID` recorded the id and nothing else, so
-- `GetTitleForQuestID` answered nil before the request and nil after it --
-- and the whole point of the call in the client is that the second answer is
-- different. Every test of the load path was therefore testing the failure
-- branch, including the one that fires `QUEST_DATA_LOAD_RESULT` with
-- `success = true`.
--
-- These are the titles the server holds and the client has not cached. The
-- request moves one into `offeredTitles`, which is where the stub's cache
-- lives.
-- A GLOBAL, not a local: this chunk is at Lua's 200-local ceiling and adding
-- one more is a load error on 5.4 rather than a test failure.
CN_TEST_LOADABLE_TITLES = {
    [4242] = "The Quest The Client Had To Ask About",
}

CN_TEST_PLAYER_X, CN_TEST_PLAYER_Y = 0.42, 0.55

-- MOVING THE PLAYER IS A FRAME BOUNDARY, so the fixture crosses one.
--
-- `CN.GetPlayerPosition` memoises on `GetTime()`, because the player cannot
-- move inside a frame and the client is asked for the answer twenty-three
-- times in a cold rebuild. A fixture that teleports the player without
-- advancing the clock is modelling something the game cannot do -- and it
-- would make the memo look broken while actually testing the fixture.
function CN_TEST_MovePlayer(x, y)
    CN_TEST_PLAYER_X, CN_TEST_PLAYER_Y = x, y

    CN_TEST_CLOCK = CN_TEST_CLOCK + 0.05
end

-- Width and height of the stub map, in yards. Square by default so that the
-- distance figures elsewhere stay checkable by hand; tests that care about
-- angles set it to something the shape of a real zone.
CN_TEST_MAP_SPAN = { 1000, 1000 }

-- When true, GetWorldPosFromMapPos answers nothing, as it does during a
-- loading screen.
CN_TEST_REFUSE_WORLD_POS = false

-- The span is set through CN_TEST_SetMapSpan, which is defined once the addon
-- has loaded: changing the shape of the world has to invalidate everything the
-- addon measured from it.


-- Maps that can express where the player is standing.
CN_TEST_PLAYER_MAPS = { [94] = true }

C_QuestLog = {
    -- Whether a unit already in your group is on a quest. Answered from the
    -- client, about people the client can already see -- no comms, no
    -- protocol, and nil-safe for a unit that is not there.
    IsUnitOnQuest = function(unit, questID)
        local sharing = CN_TEST_QUEST_SHARED[questID]

        return (sharing and sharing[unit]) and true or false
    end,

    -- BUILDS A FRESH TABLE, because the client does.
    --
    -- The stub used to hand back the same table every call, which made
    -- reading it look free and hid the fact that a UI refresh was allocating
    -- a copy of the player's entire quest history. This is the fifth time in
    -- this project a stub has modelled the world too simply and hidden a real
    -- defect; the pattern is always a stub that is cheaper than the thing.
    GetAllCompletedQuestIDs = function()
        local copy = {}

        for index = 1, #F.completedQuestIDs do
            copy[index] = F.completedQuestIDs[index]
        end

        return copy
    end,
    -- A QUEST CAN BE TURNED IN NOW, WHICH IT COULD NOT BE BEFORE.
    --
    -- This was a pure function of the id -- `id % 2 == 1` -- so the single
    -- most ordinary thing that happens in this game, finishing a quest,
    -- could not be expressed by any test. A player reported that a quest
    -- stayed on the route after they handed it in; there was no way to write
    -- that down. Fifteenth entry in the running list of defects hidden by a
    -- stub that models the world more simply than the world.
    --
    -- `CN_TEST_TurnInQuest(id)` is the whole simulation: the client drops it
    -- from the log and starts answering "completed" for it, which is exactly
    -- what happens on a turn-in.
    IsQuestFlaggedCompleted          = function(id)
        if CN_TEST_COMPLETED[id] ~= nil then
            return CN_TEST_COMPLETED[id]
        end

        if id >= 70000 then return false end   -- world quests are fresh
        return id % 2 == 1
    end,
    IsQuestFlaggedCompletedOnAccount = function(id) return id % 3 == 0 end,
    GetTitleForQuestID               = function(id)
        for _, entry in ipairs(questLog) do
            if entry.questID == id then return entry.title end
        end
        return offeredTitles[id]
    end,
    RequestLoadQuestByID   = function(id)
        table.insert(pendingLoad, id)

        -- The server answering. In the client this is asynchronous and
        -- arrives as QUEST_DATA_LOAD_RESULT; the title is in the cache by the
        -- time that event's handler reads it, which is the shape modelled
        -- here.
        if CN_TEST_LOADABLE_TITLES[id] then
            offeredTitles[id] = CN_TEST_LOADABLE_TITLES[id]
        end
    end,
    GetNumQuestLogEntries  = function() return #questLog end,
    GetInfo                = function(i) return questLog[i] end,
    ReadyForTurnIn         = function(id) return id == 9001 end,
    IsComplete             = function(id) return id == 9001 end,
    GetNextWaypoint        = function(id)
        -- THE WAYPOINT MOVES TO THE HAND-IN ONCE THE QUEST IS READY.
        -- CN_TEST_WAYPOINT_MOVED, 1.0.0.
        --
        -- This is the whole reason `turnInMapID` exists as a curated field,
        -- and the stub answered with one fixed point for the life of a quest
        -- -- so the only state in which a turn-in location is observable had
        -- never existed in the suite, and the addon's failure to record one
        -- was unobservable with it.
        if id == 9001 then
            if CN_TEST_WAYPOINT_MOVED then
                return CN_TEST_WAYPOINT_MOVED[1], CN_TEST_WAYPOINT_MOVED[2],
                       CN_TEST_WAYPOINT_MOVED[3]
            end

            return 84, 0.20, 0.80
        end

        return nil
    end,
    GetNextWaypointForMap  = function(id, mapID) return nil end,
    GetLogIndexForQuestID  = function(id)
        for index, entry in ipairs(questLog) do
            if entry.questID == id then return index end
        end
        return nil
    end,
    -- The map POI list, which carries BOTH the quests you already have and
    -- the ones standing in the zone waiting to be picked up.
    --
    -- The old stub returned only an in-log quest, which is exactly why the
    -- addon shipped for twenty-two releases unable to see an available quest:
    -- the test data had none either.
    GetQuestsOnMap = function(mapID)
        if mapID ~= 94 then return {} end

        return {
            -- In the log already; findable only through this list.
            { questID = 9002, x = 0.61, y = 0.48,
              isQuestStart = false, inProgress = true },

            -- An exclamation mark: offered here, not accepted, not done.
            { questID = 9100, x = 0.33, y = 0.27,
              isQuestStart = true, inProgress = false, isDaily = false },

            -- A daily, also available.
            { questID = 9102, x = 0.44, y = 0.66,
              isQuestStart = true, inProgress = false, isDaily = true },

            -- A quest start for something already completed: must be ignored.
            { questID = 9101, x = 0.50, y = 0.50,
              isQuestStart = true, inProgress = false },
        }
    end,
    IsWorldQuest = function(id) return id >= 70000 end,
    GetQuestTagInfo = function(id)
        if id >= 70000 then
            return { tagID = 1, tagName = "Elite", worldQuestType = 1, isElite = true }
        end
        return nil
    end,
    GetQuestObjectives = function(id)
        -- COUNTING objectives where the fixture defines them, so the addon's
        -- "eleven of twelve" path is exercised rather than only its
        -- "finished or not" one.
        if CN_TEST_OBJECTIVES[id] then
            return CN_TEST_OBJECTIVES[id]
        end

        if id == 9002 then
            return { { finished = true }, { finished = false } }
        end

        return {}
    end,
}


