-- A HEADER WITH factionID = 0, WHICH IS WHAT THE CLIENT GIVES.
--
-- The addon captured collapsed headers under `data.factionID or index` and
-- restored on `data.factionID` alone, so every header collided on
-- `collapsed[0]`: one collapsed header made the restore collapse them all.
-- The fixture had exactly one header, never collapsed, so neither half of
-- that could show.
--
-- Two headers now, one of them collapsed, and both with id 0 -- which is the
-- shape that broke it.
local factions = {
    { factionID = 0,    name = "The War Within", isHeader = true,  isCollapsed = false },
    { factionID = 2600, name = "The Severed Threads", reaction = 5,
      currentStanding = 4200, currentReactionThreshold = 3000, nextReactionThreshold = 6000 },
    { factionID = 2590, name = "Council of Dornogal", reaction = 8,
      currentStanding = 42000, currentReactionThreshold = 42000, nextReactionThreshold = 43000 },
    { factionID = 1090, name = "Kirin Tor", reaction = 7,
      currentStanding = 15000, currentReactionThreshold = 12000, nextReactionThreshold = 21000 },
    { factionID = 2135, name = "Chromie", reaction = 5,
      currentStanding = 5000, currentReactionThreshold = 4000, nextReactionThreshold = 9000 },
    { factionID = 946,  name = "Honor Hold", reaction = 8, isHeader = true, isHeaderWithRep = true,
      currentStanding = 43000, currentReactionThreshold = 42000, nextReactionThreshold = 43000 },
    { factionID = 0,    name = "Legacy", isHeader = true, isCollapsed = true },
    -- BEHIND THE COLLAPSED HEADER. 0.93.0.
    --
    -- The collapsed header had no children, so the stub's willingness to
    -- report every row regardless of collapse state cost nothing and hid
    -- everything: `WithAllFactionsExpanded` could be deleted outright and
    -- this suite would still have passed. A faction only reachable by
    -- expanding is what makes that helper load-bearing here.
    { factionID = 69,   name = "Darnassus", reaction = 6,
      currentStanding = 9000, currentReactionThreshold = 9000,
      nextReactionThreshold = 21000 },
}

function CN_TEST_Factions()
    return factions
end

-- WHAT THE CLIENT WOULD ACTUALLY LIST, GIVEN THE HEADER STATES. 0.93.0.
--
-- `GetNumFactions` counted the whole fixture and `GetFactionDataByIndex`
-- indexed straight into it, so the stub was more forgiving than the real
-- client in the one way that matters: children of a collapsed header are not
-- in the list at all, and expanding SHIFTS every index after it. Mirrors
-- `CurrencyVisible`, which models the same client behaviour for the currency
-- list.
function CN_TEST_FactionVisible()
    local visible = {}
    local showing = true

    for _, row in ipairs(factions) do
        if row.isHeader then
            showing = not row.isCollapsed

            table.insert(visible, row)
        elseif showing then
            table.insert(visible, row)
        end
    end

    return visible
end

local accountWideFactions = { [2600] = true, [2590] = true }
local majorFactions       = { [2600] = true, [2590] = true }
local paragonFactions     = { [2590] = true }

local expandCalls, collapseCalls = 0, 0

-- Per-faction paragon overrides, so a test can express a player several
-- caches deep. Empty means the default single-cycle answer below.
CN_TEST_PARAGON = {}

function CN_TEST_SetParagon(factionID, value, threshold, pending)
    if not value then
        CN_TEST_PARAGON[factionID] = nil

        return
    end

    CN_TEST_PARAGON[factionID] = {
        value     = value,
        threshold = threshold,
        pending   = pending and true or false,
    }
end

C_Reputation = {
    GetNumFactions          = function() return #CN_TEST_FactionVisible() end,
    GetFactionDataByIndex   = function(i) return CN_TEST_FactionVisible()[i] end,
    GetFactionDataByID      = function(id)
        for _, f in ipairs(factions) do
            if f.factionID == id then return f end
        end
        return nil
    end,
    IsAccountWideReputation = function(id) return accountWideFactions[id] == true end,
    IsMajorFaction          = function(id) return majorFactions[id] == true end,
    IsFactionParagon        = function(id)
        if CN_TEST_PARAGON[id] then
            return true
        end

        return paragonFactions[id] == true
    end,
    -- PARAGON VALUE IS CUMULATIVE IN THE REAL CLIENT AND WAS A CONSTANT HERE.
    --
    -- 7,500 of 10,000 is a first cycle, which is the only case where storing
    -- the raw value and printing it against the threshold happens to be
    -- right. A player three caches in reads "34500/10000", and the stub could
    -- not express that, so the suite agreed with the bug.
    GetFactionParagonInfo   = function(id)
        local held = CN_TEST_PARAGON[id]

        if held then
            return held.value, held.threshold, held.questID or 80001,
                held.pending and true or false
        end

        return 7500, 10000, 80001, true
    end,
    -- NOT PURE COUNTERS. These used to increment and change nothing, so the
    -- round trip -- and the index shifting a real expand causes -- went
    -- untested. They now move the state the addon reads back.
    ExpandAllFactionHeaders = function()
        expandCalls = expandCalls + 1

        for _, faction in ipairs(factions) do
            if faction.isHeader then
                faction.isCollapsed = false
            end
        end
    end,
    CollapseFactionHeader   = function(index)
        collapseCalls = collapseCalls + 1

        -- A VISIBLE INDEX, not a fixture index. The client's collapse call
        -- takes the row number the player would see.
        local faction = CN_TEST_FactionVisible()[index]

        if faction and faction.isHeader then
            faction.isCollapsed = true
        end
    end,
}

