local petSpecies = {
    { speciesID = 100, name = "Test Whelpling", petType = 1, isWild = false, canBattle = true,  owned = true,  count = 3 },
    { speciesID = 101, name = "Wild Critter",   petType = 2, isWild = true,  canBattle = true,  owned = false, count = 0 },
