worldQuests = {   -- global on purpose: C_TaskQuest above closes over it
    { questID = 70001, mapID = 94, x = 0.30, y = 0.40, seconds = 45 * 60 },
    { questID = 70002, mapID = 94, x = 0.70, y = 0.20, seconds = 20 * 3600 },
