        os.exit(1)
    end

    local ok, runErr = pcall(chunk, ADDON_NAME, CN)

    if not ok then
        print("RUNTIME ERROR " .. relative .. ": " .. tostring(runErr))
        os.exit(1)
    end

    print("  ok  " .. relative)
end

