    records[rival] = nil

    -- AND IT WORKS IN A CITY, which is where campaign quests are handed in.
    --
    -- `GetBestMapForUnit` answers with the CITY's own map when the player is
    -- standing in one -- this addon says so in three other files -- so a
    -- lookup keyed on the map's name finds no achievement at all in
    -- Dornogal, Valdrakken or Orgrimmar. 0.70.0 keyed on exactly that, so the
    -- whole turn-in refresh was inert for every turn-in made indoors.
    do
        for _, record in pairs(records) do
            record.mapID = nil
        end

        local realMapName = CN.Blizzard.GetMapName

        CN.Blizzard.GetMapName = function(id)
            if id == CN.GetPlayerPosition() then
                return "Dornogal"
            end

            return realMapName(id)
        end

        CN.Blizzard.GetAchievementProgress = function()
            return 11, 20
        end

        CN.ForgetDebounces()
        CN.Dispatch("CRITERIA_UPDATE")

        CN.Blizzard.GetMapName          = realMapName
        CN.Blizzard.GetAchievementProgress = realProgress

        assert(lore.DoneFor(records[here.id]) == 11,
            "standing in a city, the zone around it is still the zone whose "
            .. "progress a turn-in moves: "
            .. tostring(lore.DoneFor(records[here.id])))
    end

    -- A SCAN AT A COLD MOMENT DOES NOT EMPTY THE JOURNEY.
    --
    -- `GetAchievementProgress` answers `0, 0` when the criteria API is
    -- unavailable, and `Closest` filters on `criteria > 0` -- so one scan at
    -- the wrong moment emptied the whole Journey tab and `/cn zones`, and
    -- stamped the Scans tab "just now" on the way out.
    local heldCriteria = records[here.id].criteria

    assert((heldCriteria or 0) > 0, "the row has a real criteria count")

    CN.Blizzard.GetAchievementProgress = function()
        return 0, 0
    end

    lore.Scan()

    CN.Blizzard.GetAchievementProgress = realProgress

    assert(records[here.id].criteria == heldCriteria,
        "a client that answers nothing does not empty the store: "
        .. tostring(records[here.id].criteria))

    -- A JOURNEY AT THE CEILING IS NOT SUBTRACTED FROM A MEASURED SPAN.
    local session = CN:GetModule("Session")

    local travelModule = CN:GetModule("Travel")

    session.Durations()[CN.objectiveTypes.TREASURE] = nil

    CN_TEST_CLOCK = 900000

    session.NoteOffered({
        type         = CN.objectiveTypes.TREASURE,
        id           = 975001,
        mapID        = 2248,
        x            = 0.5,
        y            = 0.5,
        travelCost   = travelModule.maximumCost,
        travelCosted = true,
    })

    CN_TEST_CLOCK = CN_TEST_CLOCK + 300

    assert(session.NoteCompleted(CN.objectiveTypes.TREASURE, 975001) == nil,
        "a span measured against a journey the model stopped counting is not "
        .. "a sample")

    -- BUT A ROW WITH NO PLACE IN IT IS STILL A SAMPLE. 0.72.0.
    --
    -- Instances, the vault and the waiting list all set a small hand-picked
    -- `travelCost` on a row that has no coordinates at all -- a ranking
    -- nudge, not a journey -- and 0.71.0's move onto `CN.SecondsNeeded`
    -- began throwing every one of those completions away. Silently and
    -- permanently: `/cn plan` could never learn how long an instance takes,
    -- for the life of the account.
    session.Durations()[CN.objectiveTypes.INSTANCE] = nil

    session.NoteOffered({
        type       = CN.objectiveTypes.INSTANCE,
        id         = 975002,
        travelCost = 3,
    })

    CN_TEST_CLOCK = CN_TEST_CLOCK + 600

    assert(session.NoteCompleted(CN.objectiveTypes.INSTANCE, 975002),
        "a placeless row's completion is a sample: there is no journey to "
        .. "subtract and none will be added back")

    for extra = 1, session.minDurationSamples do
        session.NoteOffered({
            type       = CN.objectiveTypes.INSTANCE,
            id         = 975100 + extra,
            travelCost = 3,
        })

        CN_TEST_CLOCK = CN_TEST_CLOCK + 600

        session.NoteCompleted(CN.objectiveTypes.INSTANCE, 975100 + extra)
    end

    assert(session.TypicalSeconds(CN.objectiveTypes.INSTANCE),
        "so the planner can learn how long one takes, instead of reporting "
        .. "\"not measured\" for the life of the account")

