    -- absent is the account-wide flag -- otherwise the other branch repairs
    -- it on the way past and this proves nothing.
    local ownKey = CN.characterKey or CN.GetCharacterKey()

    for _, record in pairs(records) do
        record.progress = record.progress or {}
        record.progress[ownKey] = record.progress[ownKey] or 0
    end

    records[anyID].completed = nil

    ScansAtLogin()

    assert(records[anyID].completed ~= nil,
        "a store with a row missing its flag is repaired at login; only "
        .. "'empty' was checked, and after the first character it never is")

    -- AND ON THIS CHARACTER'S OWN DIMENSION, which is the half that matters
    -- to an alt: `completed` is account-wide, so the first character to log
    -- in after an upgrade repairs it for everybody and locks every other
    -- character out of the rescan -- while the thing THEY are missing is
    -- their own progress.
    --
    -- ASKED OF A MARKER SINCE 0.70.0, because inferring it from the rows made
    -- the condition permanently true: `Scan` writes progress only for rows
    -- the category walk returns, so a row it cannot reach kept that entry nil
    -- for ever and every login walked the whole achievement tree to find out.
    loremaster.Scan()

    local key = CN.characterKey or CN.GetCharacterKey()

    CN.Account("loremasterScans")[key] = nil

    for _, record in pairs(records) do
        if type(record.progress) == "table" then
            record.progress[key] = nil
        end
    end

    -- ASSERTED ON THE STORE, NOT ON A CALL COUNT. Several login hooks scan
    -- something, so counting calls proves only that a login happened; what
    -- matters is whether THIS character's own figures came back.
    ScansAtLogin()

    local repaired = 0

    for _, record in pairs(records) do
        if type(record.progress) == "table" and record.progress[key] ~= nil then
            repaired = repaired + 1
        end
    end

    assert(CN.Account("loremasterScans")[key],
        "and the scan is recorded against the character that ran it, so the "
        .. "next login does not walk the whole achievement tree again")

    assert(repaired > 0,
        "a character with no progress of its own gets it back at login, even "
        .. "though the account-wide flag is intact -- otherwise the first "
        .. "character to log in repairs the flag and locks every other one "
        .. "out of the rescan they need")

    -- AND SAID IN THE SOURCE, because the two conditions are hard to tell
    -- apart from the outside: the account-wide one repairs the same rows on
    -- the way past, so a behavioural test can pass with only half of it.
    do
        local source = CN_TEST_ReadAddonFile("Modules/Loremaster.lua")

        assert(source, "Modules/Loremaster.lua must be readable")

        assert(source:find('CN.Account("loremasterScans")[key]', 1, true),
            "the login scan triggers on whether THIS character has ever "
            .. "scanned, not only on the account-wide flag -- which the first "
            .. "character to log in repairs for everybody")
    end

    -- A TEXT SEARCH DOES NOT TELL THE ADDON IT OFFERED YOU ANYTHING.
    CN.UI.Hide()

    local offerCount = 0

    CN.RegisterRecommendationHook("cn-test-search", function()
        offerCount = offerCount + 1
    end)

    SlashCmdList.COMPLETIONNAVIGATOR("find e")

    CN.recommendationHooks["cn-test-search"] = nil

    assert(offerCount == 0,
        "searching with the window closed offers nothing: " .. offerCount
        .. " hook call(s)")

    -- THE TAB CAPTIONS WEAR THE TEXT SIZE.
    CN.UI.Show()

    assert(CN.SetTextScale(1.5), "the size can be set")

    local captioned = 0

    local windowFrame = CN.UI.Frame()

    -- MEASURED, not merely "has a font object": the stub answers most calls
    -- with another stub, so anything short of a size is a question that
    -- answers yes whatever the addon does.
    local baseline = _G[CN.FONT.CAPTION] and select(2, _G[CN.FONT.CAPTION]:GetFont())

    for _, button in ipairs((windowFrame and windowFrame.tabButtons) or {}) do
        local caption = button.GetFontString and button:GetFontString()

        local faceObject = caption and caption.GetFontObject and caption:GetFontObject()

        if faceObject and faceObject.GetFont and baseline then
            local _, size = faceObject:GetFont()

            if type(size) == "number" and size > baseline then
                captioned = captioned + 1
            end
        end
    end

    assert(captioned > 0,
        "the tab captions grow with the setting, like the rows under them")

    CN.SetTextScale(1.0)

    -- A ZONE IS PRICED FROM A PIN THAT HAS A POSITION.
    local quests = CN:GetModule("Quests")

    local playerMap = CN.GetPlayerPosition()

    local far = playerMap + 700

    local remembered = quests.Remembered()

    -- The LOWER id has no coordinates, so the old code would have chosen it
    -- and priced the whole zone as unreachable.
    remembered[971001] = { mapID = far }
    remembered[971002] = { mapID = far, x = 0.5, y = 0.5 }

    quests.pinRevision = quests.pinRevision + 1

    local priced

    for _, map in ipairs(quests.NearbyRememberedMaps(playerMap)) do
        if map.mapID == far then
            priced = map
        end
    end

    assert(priced, "the zone is considered at all")

    assert(priced.cost < CN.fallbackZoneCost,
        "and it is priced from the pin that has a position, not written off "
        .. "as unreachable: " .. tostring(priced.cost))

    remembered[971001] = nil
    remembered[971002] = nil

    quests.pinRevision = quests.pinRevision + 1

