;(function()
    ------------------------------------------------------------
    -- THE HARVEST SORTED ITS WHOLE STORE ON EVERY CAPTURE AT THE CEILING.
    --
    -- "Count before allocating" fixed the case below the cap and did nothing
    -- at it: `held == cap + 1` on every capture, so each one built a 2001-row
    -- array and sorted it to drop one row -- inside a loop over the whole
    -- quest log at login. Hysteresis, the same way the offer memory has had
    -- it since 0.28.0.
    ------------------------------------------------------------
    local slackHarvest = CN:GetModule("Harvest")

    assert(slackHarvest.pruneSlack and slackHarvest.pruneSlack > 0,
        "the prune must be allowed to overshoot")

    local store = slackHarvest.Store()

    for questID in pairs(store) do
        store[questID] = nil
    end

    local savedCap   = slackHarvest.cap
    local savedSlack = slackHarvest.pruneSlack

    slackHarvest.cap        = 10
    slackHarvest.pruneSlack = 4

    for questID = 1, slackHarvest.cap + 2 do
        store[questID] = { questID = questID, lastSeen = questID }
    end

    assert(slackHarvest.Prune() == 0,
        "two rows over the cap is inside the slack and must not sort")

    for questID = 100, 103 do
        store[questID] = { questID = questID, lastSeen = questID }
    end

    assert(slackHarvest.Prune() > 0,
        "and past the slack it prunes back to the cap")

    assert(CN.CountKeys(store) == slackHarvest.cap,
        "all the way back to the cap, not just under the slack, got "
        .. CN.CountKeys(store))

    for questID in pairs(store) do
        store[questID] = nil
    end

    slackHarvest.cap        = savedCap
    slackHarvest.pruneSlack = savedSlack

    slackHarvest.NoteUnlocksChanged()

    print("  the slackHarvest sorts once per two hundred captures, not once each")
end)()

;(function()
    ------------------------------------------------------------
    -- A REPLACEMENT PROVIDER KEEPS ITS PLACE IN THE QUEUE.
    --
    -- Removing the row and minting a fresh sequence moved the provider to the
    -- back of its priority band -- the exact symptom the tiebreak was added
    -- to prevent, on the path 0.55.0 opened up.
    ------------------------------------------------------------
    local function Provider()
        return {
            GetQuestData = function() return {} end,
            IsAvailable  = function() return true end,
            priority     = 500,
        }
    end

    for _, name in ipairs({ "MutationA", "MutationB", "MutationC" }) do
        CN.RegisterQuestDataProvider(name, Provider())
    end

    local function PositionOf(name)
        for index, entry in ipairs(CN.questDataOrder) do
            if entry.name == name then
                return index
            end
        end
    end

    local was = PositionOf("MutationB")

    CN.RegisterQuestDataProvider("MutationB", Provider())

    assert(PositionOf("MutationB") == was,
        "re-registering must not hand over which addon answers first, "
        .. tostring(was) .. " became " .. tostring(PositionOf("MutationB")))

    for _, name in ipairs({ "MutationA", "MutationB", "MutationC" }) do
        CN.questDataProviders[name] = nil

        for index = #CN.questDataOrder, 1, -1 do
            if CN.questDataOrder[index].name == name then
                table.remove(CN.questDataOrder, index)
            end
        end
    end

    print("  a provider that re-registers keeps its priority position")
end)()

;(function()
    ------------------------------------------------------------
    -- A DECORATOR THAT ADDS TO ITSELF IS A DECORATOR THAT COMPOUNDS.
    --
    -- `Goals.Decorate` read `userPreference` and added eight to it. That was
    -- harmless only while every rebuild produced fresh tables; since 0.55.0
    -- reuses them, a pinned goal's preference climbed by eight per rebuild
    -- without bound -- 8, 16, 24, 32 -- until it outweighed everything else
    -- on the list by thirty to one and nothing could displace it, including
    -- something about to despawn. `/cn breakdown` showed the inflated figure
    -- as though it were deliberate, and only a reload cleared it.
    ------------------------------------------------------------
    local pinnedGoals = CN:GetModule("Goals")

    pinnedGoals.Add(CN.objectiveTypes.TOY, 56600)

    local objective = { type = CN.objectiveTypes.TOY, id = 56600,
        name = "Pinned", completionValue = 3, userPreference = 1 }

    for _ = 1, 6 do
        pinnedGoals.Decorate(objective)
    end

    assert(objective.userPreference == 1 + pinnedGoals.goalPreference,
        "six passes must weigh the same as one, got "
        .. tostring(objective.userPreference))

    local saidPinned = 0

    for _, reason in ipairs(CN.Reasons(objective)) do
        if reason == "this is one of your goals" then
            saidPinned = saidPinned + 1
        end
    end

    assert(saidPinned == 1, "and say so once, got " .. saidPinned)

    -- AND UNPINNING TAKES IT BACK.
    pinnedGoals.Remove(CN.objectiveTypes.TOY, 56600)

    pinnedGoals.Decorate(objective)

    assert(objective.userPreference == 1,
        "unpinning must give back the provider's own preference, got "
        .. tostring(objective.userPreference))

    for _, reason in ipairs(CN.Reasons(objective)) do
        assert(reason ~= "this is one of your goals",
            "and stop saying it is one")
    end

    print("  a pinned goal is worth the same on the sixth pass as the first")
end)()

;(function()
    ------------------------------------------------------------
    -- FOUR WRITERS, FOUR TABLES, ONE READ.
    --
    -- Every reason used to be appended to one array on the objective, and
    -- each of four writers with four different lifetimes had to know where
    -- its own entries began and ended in order to take them back. Three
    -- consecutive releases shipped a different symptom of that one cause.
    --
    -- Nothing writes into anything it does not own now, so there is no
    -- boundary to go stale, and running any writer twice is idempotent by
    -- construction rather than by bookkeeping.
    ------------------------------------------------------------
    local objective = { type = CN.objectiveTypes.QUEST, id = 56700,
        name = "Explained", reasons = { "the provider says so" } }

    CN.AddDecoratorReason(objective, "test", "a decorator says so")
    CN.AddAdjusterReason(objective, "test", "an adjuster says so")

    assert(#CN.Reasons(objective) == 3,
        "three sentences, got " .. #CN.Reasons(objective))

    assert(#objective.reasons == 1,
        "and the provider's own list is untouched by either of them, got "
        .. #objective.reasons)

    -- Every writer, run again, changes nothing.
    for _ = 1, 5 do
        CN.AddDecoratorReason(objective, "test", "a decorator says so")
        CN.AddAdjusterReason(objective, "test", "an adjuster says so")
    end

    assert(#CN.Reasons(objective) == 3,
        "six passes read the same as one, got " .. #CN.Reasons(objective)
        .. ": " .. table.concat(CN.Reasons(objective), " | "))

    -- WITHDRAWN, AND THEN SAYABLE AGAIN. The old shape could delete a
    -- sentence while leaving the key that says "I already said this", so it
    -- could never come back.
    CN.ClearAdjusterReason(objective, "test")

    assert(#CN.Reasons(objective) == 2, "withdrawing takes one away")

    CN.AddAdjusterReason(objective, "test", "an adjuster says so")

    assert(#CN.Reasons(objective) == 3,
        "and it can be said again afterwards, got "
        .. #CN.Reasons(objective))

    -- AND A SENTENCE THAT CARRIES A NUMBER UPDATES RATHER THAN FREEZING.
    CN.AddAdjusterReason(objective, "count", "3 others here are on this quest")
    CN.AddAdjusterReason(objective, "count", "1 other here is on this quest")

    local froze, held = false, 0

    for _, reason in ipairs(CN.Reasons(objective)) do
        if reason:find("others here", 1, true) then froze = true end
        if reason:find("here is on this quest", 1, true) then held = held + 1 end
    end

    assert(not froze,
        "a sentence with a number in it must not freeze at the first number")

    assert(held == 1, "and must not be said twice, got " .. held)

    -- The composed order is stable, which is what stops a list re-ordering
    -- itself under the player between two identical refreshes.
    local first  = table.concat(CN.Reasons(objective), " | ")
    local second = table.concat(CN.Reasons(objective), " | ")

    assert(first == second, "the same objective reads the same way twice")

    print("  four writers, four tables, and one composed answer")
end)()

;(function()
    ------------------------------------------------------------
    -- THE MERGE RATCHETED THE WINNER'S VALUE AND COULD NOT LET GO.
    --
    -- The dedup raises the winner's `completionValue` to the loser's, into
    -- the winner's LIVE CACHED TABLE, with no way back. Unpin a goal and the
    -- quest kept the pinned-era value for the rest of the session; the losing
    -- provider could stop emitting the row entirely and the number stayed.
    ------------------------------------------------------------
    local loserValue = 9

    CN.RegisterCandidateProvider("MutationHigh", function()
        return {
            { type = CN.objectiveTypes.QUEST, id = 56800, name = "Contested",
              completionValue = 2 },
        }
    end)

    CN.RegisterCandidateProvider("MutationLow", function()
        return {
            { type = CN.objectiveTypes.QUEST, id = 56800, name = "Contested",
              completionValue = loserValue },
        }
    end)

    -- Through `CN.CompletionValue`, which is what the scorer reads: the
    -- merge records another provider's higher figure beside the row rather
    -- than writing it into the row, so the provider's own value stays its
    -- own and the contribution can go away again.
    local function ValueOf()
        for _, objective in ipairs(CN.CollectCandidates()) do
            if objective.id == 56800 then
                return CN.CompletionValue(objective)
            end
        end
    end

    CN.CollectCandidates(true)

    assert(ValueOf() == 9,
        "the higher of the two wins, got " .. tostring(ValueOf()))

    -- The other provider changes its mind.
    loserValue = 1

    CN.InvalidateProvider("MutationLow", true)
    CN.CollectCandidates()

    assert(ValueOf() == 2,
        "and when it changes its mind the winner goes back to its own value, "
        .. "got " .. tostring(ValueOf()))

    -- AND THE PROVIDER'S OWN ROW WAS NEVER WRITTEN INTO, which is what lets
    -- that provider keep taking the unchanged-provider shortcut. One shipped
    -- provider was measured rebuilding on 31 of 31 passes while the player
    -- stood still, for a value it had not changed.
    for _, objective in ipairs(CN.CollectCandidates()) do
        if objective.id == 56800 then
            assert(objective.completionValue == 2,
                "the merge must not write into the provider's own row, got "
                .. tostring(objective.completionValue))
        end
    end

    CN.candidateProviders["MutationHigh"] = nil
    CN.candidateProviders["MutationLow"]  = nil

    CN.InvalidateCandidates()
    CN.CollectCandidates(true)

    print("  a value another provider contributed is given back when it goes")
end)()

;(function()
    ------------------------------------------------------------
    -- SAYING THE UNLOCK COUNT CHANGED MUST MAKE SOMETHING REDECORATE.
    --
    -- `NoteUnlocksChanged` bumped a counter, and the decorator only consults
    -- the counter if `Decorate` runs -- which the unchanged-provider shortcut
    -- skips, which is the normal case. So the guard was correct and
    -- unreachable, and the count stayed frozen exactly as before.
    ------------------------------------------------------------
    local unlockHarvest = CN:GetModule("Harvest")

    local store = unlockHarvest.Store()

    for questID in pairs(store) do
        store[questID] = nil
    end

    store[56900] = { questID = 56900, lastSeen = 1 }
    store[56901] = { questID = 56901, lastSeen = 1, observedRequires = { 56900 } }

    CN.RegisterCandidateProvider("MutationUnlocked", function()
        return {
            { type = CN.objectiveTypes.QUEST, id = 56900, name = "Hub",
              completionValue = 5 },
        }
    end)

    unlockHarvest.NoteUnlocksChanged()

    CN.CollectCandidates(true)

    local function UnlockOf()
        for _, objective in ipairs(CN.CollectCandidates()) do
            if objective.id == 56900 then
                return objective.unlockValue
            end
        end
    end

    local was = UnlockOf()

    assert(was and was > 0, "one observed follower is an unlock value")

    for questID = 56902, 56905 do
        store[questID] = {
            questID = questID, lastSeen = 1, observedRequires = { 56900 },
        }
    end

    unlockHarvest.NoteUnlocksChanged()

    CN.CollectCandidates()

    assert(UnlockOf() and UnlockOf() > was,
        "and harvesting four more behind it must reach the ranked list, "
        .. tostring(was) .. " stayed " .. tostring(UnlockOf()))

    CN.candidateProviders["MutationUnlocked"] = nil

    for questID in pairs(store) do
        store[questID] = nil
    end

    unlockHarvest.NoteUnlocksChanged()

    CN.CollectCandidates(true)

    print("  a harvested unlock reaches the ranking, not just the index")
end)()

;(function()
    ------------------------------------------------------------
    -- THE BANK STORE HELD WHICHEVER TAB WAS LOOKED AT LAST.
    --
    -- The client does not describe a bank tab until it has been switched to,
    -- and the scan rewrote the whole store from what it could see -- so the
    -- Warband bank ended up holding one tab, and moving a single item
    -- rewrote both stores from whatever happened to be described.
    ------------------------------------------------------------
    local inventory = CN:GetModule("Inventory")

    local first  = inventory.accountBankIDs[1]
    local second = inventory.accountBankIDs[2]

    CN_TEST_BAGS[first]  = { { itemID = 57000, stackCount = 2 } }
    CN_TEST_BAGS[second] = nil

    inventory.ScanBank()

    assert(inventory.WarbandStore()[57000] == 2,
        "the tab that was described is recorded")

    -- The player switches tabs. The first is no longer described; the second
    -- now is.
    CN_TEST_BAGS[first]  = nil
    CN_TEST_BAGS[second] = { { itemID = 57001, stackCount = 5 } }

    inventory.ScanBank()

    assert(inventory.WarbandStore()[57001] == 5,
        "the new tab is recorded")

    assert(inventory.WarbandStore()[57000] == 2,
        "and a tab the client has stopped describing is not the same thing "
        .. "as a tab that is empty")

    CN_TEST_BAGS[first]  = nil
    CN_TEST_BAGS[second] = nil

    print("  a bank tab the client stops describing is not emptied")
end)()

;(function()
    ------------------------------------------------------------
    -- THE JOURNEY IS RE-STAMPED AS IT SHORTENS.
    --
    -- `NoteOffered` returned early the moment the key existed, so the travel
    -- estimate was frozen at whatever it was the FIRST time the objective
    -- appeared -- from wherever the addon thought you were then. Fly to that
    -- zone, quest for eight minutes, hand it in, and the sample was compared
    -- against a cost from the continent you left, and rejected.
    ------------------------------------------------------------
    local session = CN:GetModule("Session")

    local durations = session.Durations()

    durations[CN.objectiveTypes.TREASURE] = nil

    local savedClock = CN_TEST_CLOCK

    -- Offered from a long way off.
    session.NoteOffered({
        type = CN.objectiveTypes.TREASURE, id = 57100, travelCost = 20,
        travelCosted = true,
    })

    -- The player flies there. It is offered again, from next door.
    CN_TEST_CLOCK = CN_TEST_CLOCK + 400

    session.NoteOffered({
        type = CN.objectiveTypes.TREASURE, id = 57100, travelCost = 1,
        travelCosted = true,
    })

    CN_TEST_CLOCK = CN_TEST_CLOCK + 200

    local elapsed = session.NoteCompleted(CN.objectiveTypes.TREASURE, 57100)

    assert(elapsed,
        "an objective reached and finished must produce a sample, not be "
        .. "compared against a journey from the continent you left")

    assert(math.abs(elapsed - (600 - 30)) < 0.01,
        "and the journey taken out is the closest the model got, got "
        .. tostring(elapsed))

    -- And the clock is NOT re-stamped: that is the measurement.
    durations[CN.objectiveTypes.TREASURE] = nil

    CN_TEST_CLOCK = savedClock

    print("  the journey is re-costed as you close on it; the clock is not")
end)()

print("\nWhat 0.55.0 changed, asserted through the paths the game takes:")

;(function()
    ------------------------------------------------------------
    -- THE FLOOR AND THE DISCARD CANCELLED EACH OTHER OUT.
    --
    -- `NoteCompleted` clamped a short sample up to `minimumWorkSeconds` and
    -- the very next line threw away anything at or below the same number. So
    -- every fast objective -- a quest handed in on arrival, a treasure picked
    -- up on the way past -- was measured, floored, and discarded, which is
    -- the exact bias the floor was written to remove. Every learned duration
    -- read long, and read long confidently.
    ------------------------------------------------------------
    local session = CN:GetModule("Session")

    assert(session and session.NoteCompleted, "Session must expose NoteCompleted")

    local durations = session.Durations()

    durations[CN.objectiveTypes.TREASURE] = nil

    local savedClock = CN_TEST_CLOCK

    -- Offered now, finished in the same instant, with a travel estimate that
    -- swallows the whole span. This is the shape the floor exists for.
    session.NoteOffered({
        type = CN.objectiveTypes.TREASURE, id = 55001, travelCost = 3,
        travelCosted = true,
    })

    local elapsed = session.NoteCompleted(CN.objectiveTypes.TREASURE, 55001)

    assert(elapsed ~= nil,
        "a sample floored to the minimum must be KEPT -- it was floored and "
        .. "then discarded by the test on the next line")

    assert(elapsed == session.minimumWorkSeconds,
        "and it must be the floor itself, got " .. tostring(elapsed))

    assert(#durations[CN.objectiveTypes.TREASURE] == 1,
        "and it must reach the store")

    -- The implausible sample is still rejected, and rejected on the RAW span.
    durations[CN.objectiveTypes.TREASURE] = nil

    session.NoteOffered({ type = CN.objectiveTypes.TREASURE, id = 55002 })

    CN_TEST_CLOCK = CN_TEST_CLOCK + 4000

    assert(session.NoteCompleted(CN.objectiveTypes.TREASURE, 55002) == nil,
        "over twenty minutes is not a measurement of doing the thing")

    -- A FORTY-MINUTE SPAN WITH A TWENTY-FIVE MINUTE JOURNEY IS STILL FORTY
    -- MINUTES OF NOT DOING IT. Judging plausibility on the travel-adjusted
    -- figure would let this through as a confident fifteen-minute sample.
    durations[CN.objectiveTypes.TREASURE] = nil

    session.NoteOffered({
        type = CN.objectiveTypes.TREASURE, id = 55003, travelCost = 50,
        travelCosted = true,
    })

    CN_TEST_CLOCK = CN_TEST_CLOCK + 2400

    assert(session.NoteCompleted(CN.objectiveTypes.TREASURE, 55003) == nil,
        "an implausible span is implausible however far away it was")

    -- And a clock that went backwards is not a negative duration.
    durations[CN.objectiveTypes.TREASURE] = nil

    session.NoteOffered({ type = CN.objectiveTypes.TREASURE, id = 55004 })

    CN_TEST_CLOCK = CN_TEST_CLOCK - 60

    assert(session.NoteCompleted(CN.objectiveTypes.TREASURE, 55004) == nil,
        "a clock that went backwards is not a measurement")

    CN_TEST_CLOCK = savedClock

    durations[CN.objectiveTypes.TREASURE] = nil

    print("  a fast objective is floored and KEPT, and a stale one is not")
end)()

;(function()
    ------------------------------------------------------------
    -- HALF THE SUBJECT MATTER WAS BEING DEMOTED FOR THE ADDON'S DEAFNESS.
    --
    -- `shown` was counted for every type; `acted` only for the five the
    -- client announces a completion for. The other thirteen crossed the
    -- observation threshold with a numerator nailed to zero, settled on the
    -- 0.80 floor permanently, and `/cn learned` said "you rarely act on
    -- these" -- a statement about the player that the addon had no way to
    -- make.
    ------------------------------------------------------------
    local preference = CN:GetModule("Preference")

    assert(preference and preference.IsCreditable,
        "Preference must publish what it can credit")

    assert(preference.IsCreditable(CN.objectiveTypes.QUEST),
        "quests are announced by the client and must stay creditable")

    for _, objectiveType in ipairs({
        CN.objectiveTypes.REPUTATION, CN.objectiveTypes.APPEARANCE,
        CN.objectiveTypes.RARE, CN.objectiveTypes.TREASURE,
        CN.objectiveTypes.CURRENCY, CN.objectiveTypes.EXPLORATION,
        CN.objectiveTypes.RENOWN, CN.objectiveTypes.TITLE,
        CN.objectiveTypes.RECIPE, CN.objectiveTypes.PROFESSION,
        CN.objectiveTypes.VENDOR, CN.objectiveTypes.COLLECTIBLE,
        CN.objectiveTypes.INSTANCE,
    }) do
        assert(not preference.IsCreditable(objectiveType),
            objectiveType .. " has no completion event, so it must not be "
            .. "credited or punished")
    end

    -- EVERY TYPE WITH A COMPLETION EVENT MUST BE CREDITABLE, which is the
    -- half of the contract that rots: add an event, forget the set, and the
    -- type is punished for being watched.
    for _, entry in ipairs(preference.completionEvents) do
        assert(preference.IsCreditable(entry.type),
            entry.type .. " is announced by " .. entry.event
            .. " but is not in creditableTypes")
    end

    -- And the multiplier itself, through the path scoring takes: an
    -- uncreditable type sat at three hundred sightings and no completions
    -- must still be 1.00.
    local store = preference.Store()

    store[CN.objectiveTypes.APPEARANCE] = { shown = 300, acted = 0 }

    preference.NoteStoreChanged()

    local multiplier, reason = preference.Multiplier(CN.objectiveTypes.APPEARANCE)

    assert(multiplier == 1,
        "an uncreditable type must not be demoted, got " .. tostring(multiplier))

    assert(reason == nil,
        "and must not claim the player rarely acts on them, got "
        .. tostring(reason))

    store[CN.objectiveTypes.APPEARANCE] = nil

    preference.NoteStoreChanged()

    -- AND THE SENTENCE IS WITHDRAWN WHEN IT STOPS BEING TRUE.
    --
    -- The reason is stamped onto objectives that live in the per-provider
    -- cache, and the cache outlives the opinion. `/cn learned reset` says
    -- "Forgotten. The ranking is back to its defaults." -- and `/cn why` went
    -- on printing the old verdict until some unrelated rebuild happened.
    store[CN.objectiveTypes.TOY] = { shown = 300, acted = 0 }

    preference.NoteStoreChanged()

    local toy = { type = CN.objectiveTypes.TOY, id = 55200, name = "Judged" }

    CN.scoreAdjusters["Preference"](toy, 10)

    assert(toy.adjusterReasons and toy.adjusterReasons.preference,
        "a demoted type must say why")

    local stamped = #CN.Reasons(toy)

    assert(stamped > 0, "and the sentence must reach what the player reads")

    -- Now the evidence goes away, exactly as `/cn learned reset` makes it.
    store[CN.objectiveTypes.TOY] = nil

    preference.NoteStoreChanged()

    CN.scoreAdjusters["Preference"](toy, 10)

    assert(not (toy.adjusterReasons and toy.adjusterReasons.preference),
        "and it must be WITHDRAWN when it stops being true, not left on a "
        .. "cached objective for the rest of the session")

    assert(#CN.Reasons(toy) == stamped - 1,
        "and taken back out of what the player reads")

    print("  only what the client announces earns an opinion; the other "
        .. "thirteen are left alone")
end)()

;(function()
    ------------------------------------------------------------
    -- CLUSTERING ON THE FALLBACK PATH MADE THE WHOLE ZONE ONE STOP.
    --
    -- The 0.54.0 grid compares a squared distance against the hub radius in
    -- yards squared -- 4,900. With the old scale fallback of 1, the largest
    -- possible squared distance across the entire map is 2. So when the
    -- client would not give a scale, every objective in the zone joined the
    -- first hub: one stop, containing everything, with a batch bonus to
    -- match. Before 0.54.0 this path went through ObjectiveDistanceYards,
    -- which has always had a 2000-yard fallback -- so this was a regression
    -- introduced by making the clustering fast.
    ------------------------------------------------------------
    local saved = CN_TEST_MAP_SPAN

    -- The client refusing to answer is what the fallback is for.
    CN_TEST_SetMapSpan(nil)

    CN.UseRouteMapScale(nil)

    local far = {}

    for index = 1, 6 do
        table.insert(far, {
            name  = "Far " .. index,
            mapID = nil,
            x     = 0.05 + (index * 0.15),
            y     = 0.5,
        })
    end

    local hubs = CN.ClusterByProximity(far)

    assert(#hubs == 6,
        "six things spread across a zone are six stops even when the client "
        .. "will not say how big the zone is, got " .. #hubs)

    -- And two things genuinely on top of each other are still one stop.
    local together = CN.ClusterByProximity({
        { name = "A", x = 0.500, y = 0.500 },
        { name = "B", x = 0.505, y = 0.500 },
    })

    assert(#together == 1,
        "two things ten yards apart are one stop, got " .. #together)

    CN_TEST_SetMapSpan(saved)

    CN.UseRouteMapScale(nil)

    -- AND THE SENTINEL MUST NOT PASS FOR AN ANSWER.
    --
    -- `Navigation.MapScale` returns `1, 1` when the client will not convert,
    -- which is the right shrug for a bearing (it only uses the ratio) and a
    -- disaster for routing (it wants absolute yards). `UseMapScale` validated
    -- with `scaleX > 0`, which `1` satisfies -- so the fallback above could
    -- never fire for a REAL map during a loading screen, which is the only
    -- situation it exists for. Asserted through a real mapID.
    CN_TEST_REFUSE_WORLD_POS = true

    local navigation = CN:GetModule("Navigation")

    navigation.ForgetMapScales()

    local shrugX, shrugY, measured = navigation.MapScale(94)

    assert(shrugX == 1 and shrugY == 1,
        "the bearing maths still wants 1,1 when the client will not convert")

    assert(measured == false,
        "and it must SAY that is a shrug rather than a measurement")

    local routedX = select(1, CN.UseRouteMapScale(94))

    assert(routedX == CN.fallbackZoneYards,
        "routing must reject the shrug and use the yard fallback, got "
        .. tostring(routedX))

    local realFar = {}

    for index = 1, 6 do
        table.insert(realFar, {
            name = "RealFar " .. index, mapID = 94,
            x = 0.05 + (index * 0.15), y = 0.5,
        })
    end

    assert(#CN.ClusterByProximity(realFar) == 6,
        "and a real zone the client will not measure is still six stops, got "
        .. #CN.ClusterByProximity(realFar))

    CN_TEST_REFUSE_WORLD_POS = false

    CN_TEST_SetMapSpan(saved)

    CN.UseRouteMapScale(nil)

    print("  the hub radius means yards on the fallback path too")
end)()

;(function()
    ------------------------------------------------------------
    -- EXPLAINING A SCORE MUST NOT CHANGE IT.
    --
    -- `ExplainScore` re-invokes every adjuster, because an adjuster's
    -- contribution is recorded nowhere else. That is safe only while every
    -- adjuster is idempotent and never accumulates. Asserted rather than
    -- assumed: explain the same objective twice and the reason list must not
    -- grow.
    ------------------------------------------------------------
    local objective = {
        type = CN.objectiveTypes.QUEST, id = 55010, name = "Explained",
        completionValue = 5, travelCost = 0.2,
    }

    CN.ExplainScore(objective)

    local first = #(objective.reasons or {})

    CN.ExplainScore(objective)
    CN.ExplainScore(objective)

    assert(#(objective.reasons or {}) == first,
        "explaining a score three times must not stamp three reasons, "
        .. first .. " became " .. #(objective.reasons or {}))

    -- And an adjuster that throws must not take the explanation with it.
    CN.RegisterScoreAdjuster("MutationExplodes", function()
        error("adjuster failure")
    end)

    local ok = pcall(CN.ExplainScore, objective)

    CN.scoreAdjusters["MutationExplodes"] = nil

    assert(ok, "/cn why must survive an adjuster that throws")

    print("  explaining is idempotent, and survives an adjuster that throws")
end)()

;(function()
    ------------------------------------------------------------
    -- A REGISTRY THAT ACCEPTS HALF A CONTRACT.
    ------------------------------------------------------------
    local accepted = CN.RegisterQuestDataProvider("MutationHalf", {
        GetQuestData = function() return {} end,
    })

    assert(not accepted,
        "a quest data provider with no IsAvailable must be refused -- every "
        .. "read calls it")

    assert(CN.questDataProviders["MutationHalf"] == nil,
        "and must not be stored")

    -- Registering twice must replace, not duplicate the priority row.
    local function Whole()
        return {
            GetQuestData = function() return {} end,
            IsAvailable  = function() return true end,
            priority     = 5,
        }
    end

    CN.RegisterQuestDataProvider("MutationTwice", Whole())
    CN.RegisterQuestDataProvider("MutationTwice", Whole())

    local rows = 0

    for _, entry in ipairs(CN.questDataOrder) do
        if entry.name == "MutationTwice" then
            rows = rows + 1
        end
    end

    assert(rows == 1,
        "registering twice is a replacement, not a second row, got " .. rows)

    -- A capture with no name would be filed under nil, which throws inside
    -- the capture run and takes every later capture with it.
    assert(not CN.RegisterCapture{ run = function() return {} end },
        "a capture with no name must be refused")

    for index = #CN.questDataOrder, 1, -1 do
        if CN.questDataOrder[index].name == "MutationTwice" then
            table.remove(CN.questDataOrder, index)
        end
    end

    CN.questDataProviders["MutationTwice"] = nil

    -- A packed route key must read back as the pair that went in, and
    -- anything that is not one of our keys must read back as nothing rather
    -- than as an invented pair.
    local travel = CN:GetModule("Travel")

    local packed = travel.RouteKey(1450, 88)

    local fromID, toID = travel.UnpackRouteKey(packed)

    assert(fromID == 88 and toID == 1450,
        "a packed key must unpack to the pair it holds, got "
        .. tostring(fromID) .. ", " .. tostring(toID))

    assert(travel.UnpackRouteKey("88:1450") == nil,
        "and a string is not one of our keys")

    assert(travel.UnpackRouteKey(0) == nil,
        "and neither is zero")

    print("  a registry checks the whole contract, and twice is once")
end)()

;(function()
    ------------------------------------------------------------
    -- THE REMEMBERED TAB WAS AN ARRAY INDEX.
    --
    -- `UI.tabs` is sorted by order then name and rebuilt whenever a tab
    -- registers. Index 7 is "Collections" only until the tab list changes --
    -- so adding a tab silently reopens the window on somebody else's panel.
    ------------------------------------------------------------
    local tabSettings = CN.Settings()

    local UI = CN.UI or CN:GetModule("UI")

    local target = UI.tabs[#UI.tabs]

    assert(target and target.name, "there must be tabs to remember")

    -- THROUGH THE PATH A CLICK TAKES, not by writing the setting by hand:
    -- the defect is that `SelectTab` recorded only the index, so a test that
    -- writes the name itself passes with the fix removed.
    UI.SelectTab(#UI.tabs)

    assert(tabSettings.selectedTabName == target.name,
        "selecting a tab must record its NAME, got "
        .. tostring(tabSettings.selectedTabName))

    -- Now the tab list changes shape underneath it, which is what actually
    -- happens when a release adds a tab.
    tabSettings.selectedTab = 1

    assert(UI.RememberedTabIndex() == #UI.tabs,
        "the NAME decides, not the stale index")

    -- A database written before 0.55.0 has only the index, and must still
    -- open somewhere sensible.
    tabSettings.selectedTabName = nil
    tabSettings.selectedTab     = 2

    assert(UI.RememberedTabIndex() == 2,
        "an older database still opens on its remembered index")

    -- AND REBUILDING THE STRIP MUST NOT MOVE THE PLAYER.
    --
    -- `RebuildTabs` runs whenever a tab registers, which can happen after the
    -- window exists. Re-selecting unconditionally yanks the player off the tab
    -- they are reading and throws away what they had typed in the search box.
    -- What it must do is follow them across the re-sort, by name.
    UI.SelectTab(1)

    tabSettings.selectedTab     = #UI.tabs
    tabSettings.selectedTabName = target.name

    local standingOn = UI.tabs[1].name

    -- The list re-sorts underneath them, which is exactly what registering a
    -- tab does.
    local moved = table.remove(UI.tabs, 1)

    table.insert(UI.tabs, moved)

    UI.RebuildTabs()

    assert(UI.tabs[UI.selectedTab] and UI.tabs[UI.selectedTab].name
        == standingOn,
        "a rebuild must leave the player on the tab they were reading, got "
        .. tostring(UI.tabs[UI.selectedTab] and UI.tabs[UI.selectedTab].name))

    table.insert(UI.tabs, 1, table.remove(UI.tabs))

    -- With nothing selected -- the first time the window is built -- the
    -- remembered NAME decides.
    UI.selectedTab     = nil
    UI.selectedTabName = nil

    UI.RebuildTabs()

    assert(UI.tabs[UI.selectedTab] and UI.tabs[UI.selectedTab].name
        == target.name,
        "a first build must open on the remembered name, got "
        .. tostring(UI.tabs[UI.selectedTab] and UI.tabs[UI.selectedTab].name))

    -- A tab that no longer exists is not an error.
    tabSettings.selectedTabName = "AGoneTab"
    tabSettings.selectedTab     = nil

    assert(UI.RememberedTabIndex() == nil,
        "a removed tab falls back to the default rather than throwing")

    tabSettings.selectedTabName = nil
    tabSettings.selectedTab     = nil

    print("  the window reopens on the tab you left, by name")
end)()

;(function()
    ------------------------------------------------------------
    -- A SCORING TERM WITH ONE PRODUCER OUT OF TWENTY-TWO.
    --
    -- `unlockValue` carries the second-heaviest weight in the scorer and was
    -- set by exactly one provider. It now reads the inverted prerequisite
    -- graph the addon already harvests -- and only that, so a quest nothing
    -- has been observed behind still scores zero.
    ------------------------------------------------------------
    local unlockHarvest = CN:GetModule("Harvest")

    assert(unlockHarvest and unlockHarvest.UnlockCount, "Harvest must publish UnlockCount")

    local store = unlockHarvest.Store()

    store[55100] = { questID = 55100, lastSeen = 1 }
    store[55101] = { questID = 55101, lastSeen = 1, observedRequires = { 55100 } }
    store[55102] = { questID = 55102, lastSeen = 1, observedRequires = { 55100 } }

    -- Named twice by one record is one unlock, not two.
    store[55103] = {
        questID = 55103, lastSeen = 1,
        requires = { 55100 }, observedRequires = { 55100 },
    }

    unlockHarvest.NoteUnlocksChanged()

    assert(unlockHarvest.UnlockCount(55100) == 3,
        "three quests were observed behind it, got "
        .. unlockHarvest.UnlockCount(55100))

    assert(unlockHarvest.UnlockCount(55101) == 0,
        "and nothing was observed behind a leaf")

    -- Through the decorator, which is the path scoring actually takes.
    local objective = { type = CN.objectiveTypes.QUEST, id = 55100 }

    CN.candidateDecorators["Unlocks"](objective)

    assert(objective.unlockValue
        and objective.unlockValue > 0 and objective.unlockValue <= 1,
        "the decorator must stamp a 0..1 unlock value, got "
        .. tostring(objective.unlockValue))

    local leaf = { type = CN.objectiveTypes.QUEST, id = 55101 }

    CN.candidateDecorators["Unlocks"](leaf)

    assert(leaf.unlockValue == nil,
        "and must invent nothing for a quest with no observed followers")

    -- A provider with its own opinion keeps it.
    local owned = { type = CN.objectiveTypes.QUEST, id = 55100, unlockValue = 0.25 }

    CN.candidateDecorators["Unlocks"](owned)

    assert(owned.unlockValue == 0.25,
        "the decorator fills a gap; it does not overrule a provider")

    for id = 55100, 55103 do
        store[id] = nil
    end

    unlockHarvest.NoteUnlocksChanged()

    print("  what a quest unlocks is measured from this account's own play")
end)()

;(function()
    ------------------------------------------------------------
    -- EVICTION BY QUEST ID DELETED EXACTLY WHAT A LEVELLING ALT NEEDS.
    --
    -- The pruneHarvest store dropped its lowest ids on the reasoning that a low id
    -- is old content. That describes a max-level character; it describes the
    -- opposite of an alt levelling through classic zones, whose entire log is
    -- low ids.
    ------------------------------------------------------------
    local pruneHarvest = CN:GetModule("Harvest")

    local store = pruneHarvest.Store()

    local savedCap = pruneHarvest.cap

    for questID in pairs(store) do
        store[questID] = nil
    end

    local savedSlack = pruneHarvest.pruneSlack

    pruneHarvest.cap        = 3
    pruneHarvest.pruneSlack = 1

    -- A low id seen just now, and high ids not seen in a long time.
    store[100]   = { questID = 100,   lastSeen = 9000 }
    store[90001] = { questID = 90001, lastSeen = 10 }
    store[90002] = { questID = 90002, lastSeen = 20 }
    store[90003] = { questID = 90003, lastSeen = 30 }
    store[90004] = { questID = 90004, lastSeen = 40 }

    pruneHarvest.Prune()

    assert(store[100] ~= nil,
        "the quest the player is standing next to must survive eviction")

    assert(store[90001] == nil and store[90002] == nil,
        "and the least recently seen must be the ones that go")

    for questID in pairs(store) do
        store[questID] = nil
    end

    pruneHarvest.cap        = savedCap
    pruneHarvest.pruneSlack = savedSlack

    pruneHarvest.NoteUnlocksChanged()

    print("  the pruneHarvest evicts what has not been seen, not what is oldest")
end)()

;(function()
    ------------------------------------------------------------
    -- A REGISTRY WITH A CLOSED SELECTOR IS NOT A REGISTRY.
    --
    -- `RegisterWaypointProvider` is published, but the only way to CHOOSE a
    -- provider matched three names hardcoded in `SetPreference`. A fourth
    -- provider could be used automatically and never chosen deliberately.
    ------------------------------------------------------------
    local navigation = CN:GetModule("Navigation")

    CN.RegisterWaypointProvider("MutationPin", {
        priority    = 500,
        IsAvailable = function() return true end,
        SetWaypoint = function() return true end,
    })

    local ok, resolved = navigation.SetPreference("mutationpin")

    assert(ok and resolved == "MutationPin",
        "a registered provider must be selectable by name, case-insensitively")

    assert(navigation.Preference() == "MutationPin",
        "and stored under the name the registry uses")

    local offeredHere = false

    for _, name in ipairs(navigation.PreferenceNames()) do
        if name == "MutationPin" then
            offeredHere = true
        end
    end

    assert(offeredHere, "and named in what the command offers")

    assert(not (navigation.SetPreference("nothingatall")),
        "something nobody registered is still refused")

    navigation.SetPreference("auto")

    CN.waypointProviders["MutationPin"] = nil

    for index = #CN.waypointOrder, 1, -1 do
        if CN.waypointOrder[index].name == "MutationPin" then
            table.remove(CN.waypointOrder, index)
        end
    end

    print("  any registered waypoint provider can be chosen, not three names")
end)()

;(function()
    ------------------------------------------------------------
    -- ADDON_LOADED WAS REGISTRABLE AND UNDISPATCHABLE.
    --
    -- It is in the registered-events list and `RegisterEvent` accepts a
    -- handler for it, but the handler returned before `Dispatch`. Anything
    -- registered that way was accepted and silently never called.
    ------------------------------------------------------------
    local loadedFired = 0

    CN:RegisterEvent("ADDON_LOADED", function()
        loadedFired = loadedFired + 1
    end)

    local eventFrame = CN.eventFrame

    eventFrame.scripts.OnEvent(eventFrame, "ADDON_LOADED", "CompletionNavigator")

    assert(loadedFired == 1,
        "a handler registered for ADDON_LOADED must be called, loadedFired "
        .. loadedFired .. " time(s)")

    -- AND FOR SOMEBODY ELSE'S ADDON, WHICH IS THE ONLY REASON TO WANT IT.
    -- 0.68.0.
    --
    -- This used to assert the opposite. The client loads `Blizzard_TokenUI`,
    -- `Blizzard_Collections` and the rest on demand, and there is no other
    -- announcement that one of those frames now exists -- so a handler that
    -- fires only on OUR load fires at the one moment the frame it is waiting
    -- for is guaranteed absent. 0.67.0 registered exactly such a handler for
    -- the currency panel and it was inert.
    eventFrame.scripts.OnEvent(eventFrame, "ADDON_LOADED", "Blizzard_TokenUI")

    assert(loadedFired == 2,
        "another addon loading reaches the handler too, loadedFired "
        .. loadedFired .. " time(s)")

    -- The database initialization stays ours alone: running it on somebody
    -- else's load is the opposite mistake.
    local initialised = 0

    local realInit = CN.InitializeDatabase

    CN.InitializeDatabase = function(...)
        initialised = initialised + 1

        return realInit(...)
    end

    eventFrame.scripts.OnEvent(eventFrame, "ADDON_LOADED", "SomeOtherAddon")

    CN.InitializeDatabase = realInit

    assert(initialised == 0,
        "another addon loading must not re-initialize this addon's database")

    print("  ADDON_LOADED reaches the handlers the registry accepted")
end)()

;(function()
    ------------------------------------------------------------
    -- A MIGRATION THAT FAILED PART-WAY SAID SO ONCE AND CARRIED ON.
    ------------------------------------------------------------
    local saved = CN.migrations[3]

    CN.migrations[3] = function()
        error("deliberate migration failure")
    end

    local migrationDb = { version = 3, account = {}, characters = {} }

    CN.RunMigrations(migrationDb)

    assert(migrationDb.version == 3,
        "a failed migration must not advance the version, got "
        .. tostring(migrationDb.version))

    assert(type(migrationDb.migrationFailure) == "table"
        and migrationDb.migrationFailure.version == 3,
        "and must record WHICH migration failed")

    CN.migrations[3] = saved

    CN.migrationFailure = nil

    -- AND MIGRATION 9 ITSELF, which drops the preference rows the addon could
    -- never have credited.
    local ninth = {
        version = 9,
        account = {},
        characters = {
            ["Main-Realm"] = {
                preference = {
                    QUEST      = { shown = 40, acted = 12 },
                    APPEARANCE = { shown = 300, acted = 0 },
                    RARE       = { shown = 120, acted = 0 },
                },
            },

            -- A row that is not a table at all must not throw.
            ["Broken-Realm"] = true,
        },
    }

    CN.RunMigrations(ninth)

    local kept = ninth.characters["Main-Realm"].preference

    assert(kept.QUEST, "a type the client announces keeps its record")

    assert(not kept.APPEARANCE and not kept.RARE,
        "and rows that could only ever read 0 of N are dropped")

    assert(ninth.version == CN.dbVersion,
        "and the ladder runs to the top, got " .. tostring(ninth.version))

    -- A CORRUPT CHARACTERS TABLE IS A FAULT, NOT A THING TO PAPER OVER.
    --
    -- 0.55.0 replaced it with an empty table, which destroys every character
    -- profile, advances the version, and reports a clean bill of health. The
    -- migration refuses now, and refusing is recorded -- which is recoverable,
    -- because the data is still there.
    local corrupt = { version = 9, account = {}, characters = "not a table" }

    CN.RunMigrations(corrupt)

    assert(corrupt.characters == "not a table",
        "a migration must not silently destroy what it cannot read")

    assert(corrupt.version == 9,
        "and must not claim to have upgraded it, got "
        .. tostring(corrupt.version))

    assert(type(corrupt.migrationFailure) == "table",
        "and must record the refusal where /cn navdiag can find it")

    CN.migrationFailure = nil

    print("  a failed migration is recorded, not just printed once")
end)()

print("\nWhat 0.54.0 changed, asserted through the paths the game takes:")

;(function()
    ------------------------------------------------------------
    -- ONE PALETTE, AND NOTHING OUTSIDE IT.
    --
    -- Before this release there were sixteen distinct colours across five
    -- hundred and forty-three inline hex codes -- five greys doing one job,
    -- three reds, two greens, two golds, and the brand blue in two casings --
    -- plus three separate palettes, none of which was the source of truth.
    --
    -- A palette with an exception is a palette that is sixteen colours again
    -- in three releases, so the rule is checked rather than written down.
    ------------------------------------------------------------
    assert(CN.C and CN.C.BRAND, "the palette must exist")

    assert(CN.Brand("x") == "|cff" .. CN.C.BRAND .. "x|r",
        "the wrappers must produce the palette's own codes")

    -- The RGB form and the hex form must be the same colour. They were two
    -- hand-written sets that had drifted: Tooltips.lua's "green" was
    -- #66FF66 and everything else's was #73B873.
    local brand = CN.RGB.BRAND

    assert(math.abs(brand[1] - (tonumber(CN.C.BRAND:sub(1, 2), 16) / 255)) < 0.001,
        "CN.RGB and CN.C must be the same colour in two shapes")

    local goodR, goodG, goodB = CN.Rgb("GOOD")

    assert(goodR and goodG and goodB, "and the three-float form answers as well")

    -- Every role a wrapper exists for must have a colour behind it.
    for _, role in ipairs({ "BRAND", "ACCENT", "PRIMARY", "BODY", "MUTED",
                            "GOOD", "WARN", "BAD", "DISABLED" }) do
        assert(CN.C[role] and #CN.C[role] == 6,
            role .. " must be a six-digit hex colour")
    end

    print("  " .. 9 .. " colour roles, one definition each")
end)()

;(function()
    ------------------------------------------------------------
    -- THE 2-OPT REWRITE MUST FIND THE SAME ROUTES.
    --
    -- It used to build a whole new route table per pair and measure both
    -- routes end to end -- 33 ms and megabytes of garbage at forty stops,
    -- every two seconds while the Zone tab is open. Reversing a segment
    -- changes exactly two edges, so the comparison is four distances and the
    -- swap is done in place.
    --
    -- A forty-times-cheaper search that returns a slightly different answer
    -- is not the same search, so this asserts the ANSWER, not the speed.
    ------------------------------------------------------------
    CN.UseRouteMapScale(94)

    local worst, checked = 0, 0

    for seed = 1, 12 do
        local stops = {}

        for index = 1, 9 + (seed % 5) do
            table.insert(stops, {
                name = "Stop " .. index,
                mapID = 94,
                x = 0.05 + (((index * (7 + seed)) % 19) * 0.047),
                y = 0.05 + (((index * (11 + seed)) % 17) * 0.052),
            })
        end

        local routeBefore = CN.RouteLength(stops, 0.5, 0.5)

        local improved = CN.ImproveRoute(stops, 0.5, 0.5)

        local after = CN.RouteLength(improved, 0.5, 0.5)

        assert(after <= routeBefore + 0.001,
            "2-opt must never lengthen a route: " .. after .. " vs " .. routeBefore)

        assert(#improved == #stops,
            "and it must not lose or duplicate a stop")

        -- Every stop still present exactly once. An in-place reversal that
        -- gets its indices wrong loses one silently.
        local seen = {}

        for _, stop in ipairs(improved) do
            assert(not seen[stop.name], "a stop appears twice: " .. stop.name)

            seen[stop.name] = true
        end

        if routeBefore > 0 then
            worst = math.max(worst, (routeBefore - after) / routeBefore)
        end

        checked = checked + 1
    end

    assert(worst > 0.01,
        "the sweep must actually improve some route, or it is only checking "
        .. "that nothing changed")

    -- THE REVERSAL ITSELF, ORDER BY ORDER.
    --
    -- "The route did not get longer" and "no stop was lost" both hold for a
    -- reversal that skips the middle of the segment, because a partial
    -- reversal is still a permutation. The order is what the two-pointer swap
    -- can get wrong.
    do
        local straight = {}

        for index = 1, 6 do
            table.insert(straight, {
                name = "S" .. index, mapID = 94,
                x = 0.1 + (index * 0.1), y = 0.5,
            })
        end

        -- Six stops on a line, walked from beyond the far end: the whole
        -- route is one crossing, and the only shortest answer is the exact
        -- reverse.
        local reversed = CN.ImproveRoute(straight, 0.95, 0.5)

        local order = {}

        for _, stop in ipairs(reversed) do
            table.insert(order, stop.name)
        end

        assert(table.concat(order, "") == "S6S5S4S3S2S1",
            "a line walked from the far end must come back exactly reversed, "
            .. "got " .. table.concat(order, ""))
    end

    -- AND NO CROSSING SURVIVES, which is the property 2-opt exists for.
    local crossed = {
        { name = "A", mapID = 94, x = 0.10, y = 0.10 },
        { name = "B", mapID = 94, x = 0.90, y = 0.90 },
        { name = "C", mapID = 94, x = 0.90, y = 0.10 },
        { name = "D", mapID = 94, x = 0.10, y = 0.90 },
    }

    local uncrossed = CN.ImproveRoute(crossed, 0.05, 0.05)

    local order = {}

    for _, stop in ipairs(uncrossed) do
        table.insert(order, stop.name)
    end

    local joined = table.concat(order, "")

    assert(joined ~= "ABCD",
        "the diagonal crossing must be removed, got " .. joined)

    print("  " .. checked .. " routes improved in place, best "
        .. string.format("%.0f%%", worst * 100) .. " shorter, none lengthened")
end)()

;(function()
    ------------------------------------------------------------
    -- CLUSTERING MUST GROUP THE SAME THINGS, BUCKETED OR NOT.
    --
    -- It compared every objective against every member of every hub and
    -- asked the Navigation module for the map scale on each comparison: 10.7
    -- ms at a hundred and ten located objectives, growing as the square.
    -- Bucketed into a grid of the hub radius, only the nine cells around a
    -- candidate can decide the answer.
    ------------------------------------------------------------
    CN.UseRouteMapScale(94)

    -- Three tight clumps far apart. Any correct clustering finds three hubs.
    local objectives = {}

    for clump = 1, 3 do
        for member = 1, 5 do
            table.insert(objectives, {
                name  = "Clump " .. clump .. " member " .. member,
                mapID = 94,
                x     = (clump * 0.3) + (member * 0.0004),
                y     = (clump * 0.25) + (member * 0.0004),
            })
        end
    end

    local hubs = CN.ClusterByProximity(objectives)

    assert(#hubs == 3,
        "three clumps must produce three hubs, got " .. #hubs)

    local total = 0

    for _, hub in ipairs(hubs) do
        total = total + #hub.objectives

        assert(hub.x and hub.y, "a hub must have a position")
    end

    assert(total == #objectives,
        "and no objective may be lost or duplicated: " .. total
        .. " of " .. #objectives)

    -- ACROSS A CELL BOUNDARY.
    --
    -- The grid is the optimisation, and the way a grid gets clustering wrong
    -- is at its own edges: two objectives a few yards apart but in different
    -- cells are one stop, and looking only in a candidate's own cell would
    -- split them. Placed deliberately either side of a boundary.
    do
        local scaleX = select(1, CN.UseRouteMapScale(94))

        local cell = CN.hubRadiusYards / math.max(1, scaleX)

        -- Just under and just over the same boundary line.
        local boundary = cell * 4

        local straddling = {
            { name = "Before", mapID = 94, x = boundary - (cell * 0.02), y = 0.5 },
            { name = "After",  mapID = 94, x = boundary + (cell * 0.02), y = 0.5 },
        }

        assert(#CN.ClusterByProximity(straddling) == 1,
            "two objectives a few yards apart are one stop even when the "
            .. "grid puts them in different cells")
    end

    -- Everything in one place is one hub, which is the case the grid could
    -- get wrong by only looking at neighbouring cells.
    local together = {}

    for index = 1, 12 do
        table.insert(together, {
            name = "Together " .. index, mapID = 94,
            x = 0.5 + (index * 0.0002), y = 0.5,
        })
    end

    assert(#CN.ClusterByProximity(together) == 1,
        "twelve things in one spot are one stop")

    -- And things spread far apart are never merged.
    local apart = {}

    for index = 1, 8 do
        table.insert(apart, {
            name = "Apart " .. index, mapID = 94,
            x = 0.05 + (index * 0.11), y = 0.5,
        })
    end

    assert(#CN.ClusterByProximity(apart) == 8,
        "and eight things far apart are eight stops, got "
        .. #CN.ClusterByProximity(apart))

    print("  clustering groups by place, and the grid does not merge or lose")
end)()

;(function()
    ------------------------------------------------------------
    -- A REBUILD THAT CHANGED NOTHING MUST NOT RE-RANK EVERYTHING.
    --
    -- Seven providers are volatile and expire on a five-second clock, and
    -- most of the time they return exactly the rows they returned before.
    -- Every one of those bumped the aggregate generation, which forces a full
    -- re-score and re-sort: measured, 0.007 ms became 0.221 ms, every five
    -- seconds, for no change in what the player sees.
    ------------------------------------------------------------
    local builds = 0

    CN.RegisterCandidateProvider("MutationSteady", function()
        builds = builds + 1

        return {
            { type = CN.objectiveTypes.TOY, id = 90001,
              name = "Steady", completionValue = 3 },
        }
    end)

    CN.CollectCandidates(true)

    local generation = CN.GetCandidateCacheState().generation

    CN.InvalidateProvider("MutationSteady", true)
    CN.CollectCandidates()

    assert(builds >= 2, "the provider must actually have been asked again")

    assert(CN.GetCandidateCacheState().generation == generation,
        "a rebuild that produced the same list must not move the generation")

    -- But a rebuild that DOES change something must.
    local changed = false

    CN.candidateProviders["MutationSteady"].fn = function()
        changed = true

        return {
            { type = CN.objectiveTypes.TOY, id = 90002,
              name = "Different", completionValue = 4 },
        }
    end

    CN.InvalidateProvider("MutationSteady", true)
    CN.CollectCandidates()

    assert(changed, "the replacement provider must have run")

    assert(CN.GetCandidateCacheState().generation ~= generation,
        "a rebuild that produced a different list MUST move it")

    -- And a provider going away must not leave its rows behind, which is the
    -- hole the shortcut opened: with nothing rebuilding, the aggregate was
    -- reused and the departed provider's candidates survived the session.
    CN.candidateProviders["MutationSteady"] = nil

    -- DELIBERATELY WITHOUT AN INVALIDATION.
    --
    -- Marking the survivors dirty would let some OTHER provider's rebuild
    -- report a change and force a full pass, which would rebuild the
    -- aggregate for a reason that has nothing to do with the departure -- and
    -- the test would pass with the departure check deleted. Nothing is dirty
    -- here, so `rebuilt` is zero and the provider COUNT is the only thing
    -- that can notice.
    local survived = false

    for _, objective in ipairs(CN.CollectCandidates()) do
        if objective.id == 90002 then
            survived = true
        end
    end

    assert(not survived,
        "a provider that has gone away must take its rows with it")

    -- AND A DECORATOR'S OWN REASON MUST NOT DEFEAT IT.
    --
    -- `Identical` compares a freshly built, UNDECORATED list against the
    -- previous, DECORATED one. Anything a decorator appends is therefore
    -- present on one side and absent on the other, so the comparison always
    -- failed and the shortcut silently stopped working for that provider --
    -- the class of defect this project keeps finding: written, measured, and
    -- off.
    local decorated = 0

    CN.RegisterCandidateProvider("MutationDecorated", function()
        return {
            { type = CN.objectiveTypes.TOY, id = 90003, name = "Decorated",
              completionValue = 3 },
        }
    end)

    CN.RegisterCandidateDecorator("MutationStamp", function(objective)
        if objective.id ~= 90003 then
            return
        end

        decorated = decorated + 1

        CN.AddDecoratorReason(objective, "mutationStamp",
            "stamped by a decorator")
    end)

    CN.CollectCandidates(true)

    local decoratedGeneration = CN.GetCandidateCacheState().generation

    CN.InvalidateProvider("MutationDecorated", true)
    CN.CollectCandidates()

    assert(CN.GetCandidateCacheState().generation == decoratedGeneration,
        "a provider whose rows a decorator stamps must still short-circuit "
        .. "when it returns the same rows")

    CN.candidateDecorators["MutationStamp"] = nil
    CN.candidateProviders["MutationDecorated"] = nil

    CN.InvalidateCandidates()
    CN.CollectCandidates(true)

    print("  an unchanged rebuild is not a change, and a departed provider "
        .. "leaves")
end)()

;(function()
    ------------------------------------------------------------
    -- HIDING SOMETHING IS TWO HASH LOOKUPS, NOT A STRING.
    --
    -- The stores were keyed "TYPE:id" and the two readers are called twice
    -- per candidate -- so one click of Ignore cost eight thousand string
    -- allocations per rebuild, +53%, for exactly the players the feature is
    -- for. Nested by type, and migration 8 converts the old shape.
    ------------------------------------------------------------
    local PET = CN.objectiveTypes.PET

    CN.SetIgnored(PET, 4242, true)

    local store = CN.Account("ignoredObjectives")

    assert(store[PET] and store[PET][4242],
        "the store is nested by type")

    assert(CN.IsIgnored(PET, 4242), "and reads back")
    assert(not CN.IsIgnored(PET, 4243), "and only for what was hidden")
    assert(not CN.IsIgnored(CN.objectiveTypes.TOY, 4242),
        "and not across types -- the flat key could not have told these apart "
        .. "if a type name ever contained a colon")

    -- Restoring the last row must leave the store genuinely empty, because
    -- `next(store) == nil` is the fast path both readers take.
    CN.SetIgnored(PET, 4242, false)

    assert(next(store) == nil,
        "an empty type bucket must go, or the empty fast path stops firing")

    -- The migration, driven through the ladder rather than called directly.
    local legacy = {
        version = 8,
        account = {
            ignoredObjectives  = { ["PET:77"] = { since = 1 } },
            deferredObjectives = { ["QUEST:88"] = { until_ = 2 } },
            flightRoutes       = { ["10:20"] = 3 },
        },
    }

    CN.migrations[8](legacy)

    assert(legacy.account.ignoredObjectives.PET
        and legacy.account.ignoredObjectives.PET[77],
        "migration 8 must renest the ignore store")

    assert(legacy.account.deferredObjectives.QUEST
        and legacy.account.deferredObjectives.QUEST[88],
        "and the defer store")

    assert(legacy.account.flightRoutes[(10 * 1000000) + 20] == 3,
        "and repack the flight route keys, which were read a thousand times "
        .. "per journey estimate")

    print("  ignore and defer are nested by type, and the old shape migrates")
end)()

;(function()
    ------------------------------------------------------------
    -- SETUP KNOWS WHICH SCANS HAVE RUN, NOT JUST WHETHER ONE DID.
    --
    -- A single account-wide flag meant the login reminder told players
    -- nothing had been scanned while four subsystems had scanned themselves
    -- eight seconds earlier, the window's own scan button did not satisfy it,
    -- and the reminder could not name what was missing because it did not
    -- know.
    ------------------------------------------------------------
    local setupModule = CN:GetModule("Setup")

    local record = CN.Account("setup")

    record.steps = {}
    record.completedAt = nil

    -- AND THE PER-CHARACTER STAMPS, which since 0.76.0 are what the two
    -- steps whose readings belong to a character are judged by.
    local loreScans = CN.Account("loremasterScans")
    local achieveScans = CN.Account("achievementScans")

    local heldLore, heldAchieve = {}, {}

    for key, value in pairs(loreScans) do heldLore[key] = value end
    for key, value in pairs(achieveScans) do heldAchieve[key] = value end

    for key in pairs(loreScans) do loreScans[key] = nil end
    for key in pairs(achieveScans) do achieveScans[key] = nil end

    local missing = setupModule.NeverScanned()

    assert(#missing == #setupModule.steps,
        "with nothing stamped, everything is outstanding: " .. #missing)

    assert(not setupModule.HasRun(), "and setup has not run")

    -- Every scan in the addon routes through CN.MarkScanned, which is where
    -- the stamp is written -- so a scan run from anywhere counts.
    for _, step in ipairs(setupModule.steps) do
        CN.MarkScanned(step.key)
    end

    -- A PER-CHARACTER STEP IS NOT CLEARED BY AN ACCOUNT-WIDE STAMP. 0.76.0.
    --
    -- `Setup.StepDone` reads account-wide stamps, so once ANY character had
    -- run a step every other character was treated as having run it -- and
    -- for the two stores whose readings belong to the character that made
    -- them, that is exactly wrong. An alt was never listed and silently read
    -- whatever the main's scan had left.
    local stillMissing = setupModule.NeverScanned()

    assert(#stillMissing == 2,
        "the two per-character scans are still outstanding on a character "
        .. "that has not run them: " .. table.concat(stillMissing, ", "))

    assert(not setupModule.HasRun(),
        "and setup has not run for this character")

    for key, value in pairs(heldLore) do loreScans[key] = value end
    for key, value in pairs(heldAchieve) do achieveScans[key] = value end

    loreScans[CN.GetCharacterKey()] = time()
    achieveScans[CN.GetCharacterKey()] = time()

    assert(#setupModule.NeverScanned() == 0, "and stamping them all clears it")
    assert(setupModule.HasRun(), "so setup has run, however it was run")

    -- THE QUEST SCAN IS THE ONE STEP THAT DOES NOT GO THROUGH MarkScanned,
    -- because it scans nothing collectible -- so it has to stamp itself, and
    -- if it does not, the reminder asks for it forever.
    record.steps = {}

    CN:GetModule("Quests").ScanKnown()

    assert(setupModule.StepDone("quests"),
        "scanning quests must record that quests were scanned")

    for _, step in ipairs(setupModule.steps) do
        CN.MarkScanned(step.key)
    end

    -- One missing is named, rather than "your collections".
    record.steps["appearances"] = nil

    local named = setupModule.NeverScanned()

    assert(#named == 1 and named[1] == "Appearances",
        "the reminder must be able to name exactly what is missing")

    CN.MarkScanned("appearances")

    print("  " .. #setupModule.steps .. " scans stamped individually")
end)()

;(function()
    ------------------------------------------------------------
    -- COSTED JOURNEYS ARE ABOUT WHERE THE PLAYER IS STANDING.
    --
    -- Every located candidate asks for one, and against a real flight network
    -- that is most of a rebuild -- so they are remembered. But a remembered
    -- travel cost is a statement about a starting point, and the moment the
    -- player walks away it is a statement about somewhere else. A memo that
    -- outlives its premise is worse than no memo.
    ------------------------------------------------------------
    local travel = CN:GetModule("Travel")

    travel.ForgetCosts()

    local realPosition = CN.GetPlayerPosition

    CN.GetPlayerPosition = function() return 94, 0.10, 0.10 end

    local near = travel.CostFor(94, 0.90, 0.90)

    assert(near, "a journey must be costable")

    assert(travel.CostCacheSize() > 0, "and remembered")

    -- Asking again from the same place must not recompute.
    local held = travel.CostCacheSize()

    travel.CostFor(94, 0.90, 0.90)

    assert(travel.CostCacheSize() == held,
        "the same question from the same place is answered from the memo")

    -- Move to the far side of the zone. The costs are now about somewhere
    -- else and must go.
    CN.GetPlayerPosition = function() return 94, 0.85, 0.85 end

    local far = travel.CostFor(94, 0.90, 0.90)

    assert(far and far < near,
        "standing next to the destination must cost less than standing "
        .. "across the zone from it: " .. tostring(far) .. " vs "
        .. tostring(near))

    CN.GetPlayerPosition = realPosition

    travel.ForgetCosts()

    assert(travel.CostCacheSize() == 0, "and it can all be thrown away")

    print("  costed journeys are memoised, and forgotten when you move")
end)()

;(function()
    ------------------------------------------------------------
    -- A PROGRESS BAR THAT IS A TEXTURE, AND THE RIGHT WIDTH.
    --
    -- The window drew bars out of "=" and "-" characters in a proportional
    -- font, so a twenty-four cell bar's PIXEL width changed as it filled --
    -- a progress bar that got shorter as you made progress.
    ------------------------------------------------------------
    local panel = CN.UI.tabs[1] and CN.UI.tabs[1].panel

    local list = CN.UI.CreateList(CN.UI.window or UIParent)

    list:SetEntries({
        { text = "Empty",  fraction = 0 },
        { text = "Half",   fraction = 0.5 },
        { text = "Full",   fraction = 1 },
        { text = "No bar" },
    })

    -- `IsShown` on the stub reads `f.shown == true`, and Show/Hide set it,
    -- so a texture that has never been shown or hidden reads false.
    local empty = list:GetRow(1)
    local half  = list:GetRow(2)
    local full  = list:GetRow(3)
    local none  = list:GetRow(4)

    assert(half.bar:GetWidth() > empty.bar:GetWidth(),
        "half full must be wider than empty")

    assert(full.bar:GetWidth() > half.bar:GetWidth(),
        "and full wider than half -- a bar that is always full is not a bar")

    assert(not none.bar:IsShown(),
        "and a row with no fraction has no bar at all")

    -- The value column and the selection texture, which replaced padded
    -- columns and a ">" glyph.
    list:SetEntries({
        { text = "Row", value = "12 / 30", selected = true },
    })

    local row = list:GetRow(1)

    assert(row.value:GetText() == "12 / 30",
        "the value column carries the number")

    assert(row.selected:IsShown(),
        "and selection is a texture, not two characters of punctuation")

    if panel then
        CN.UI.Refresh()
    end

    print("  bars, value columns and selection are drawn, not spelled")
end)()

;(function()
    ------------------------------------------------------------
    -- A GOAL CAN BE NAMED, NOT ONLY NUMBERED.
    --
    -- The store page leads with `/cn chase rep 2600`. Nobody knows that 2600
    -- is the Severed Threads. Six modules had a name resolver and the two
    -- commands most likely to be handed a name called `CN.ToID` and refused
    -- anything that was not already a number.
    ------------------------------------------------------------
    -- The toy store has to have been read for a name to mean anything.
    CN:GetModule("Toys").Scan()

    assert(CN.ResolveObjective(CN.objectiveTypes.TOY, "500") == 500,
        "a number still resolves to itself")

    assert(CN.ResolveObjective(CN.objectiveTypes.TOY, "Test Toy") == 500,
        "and so does the name of a toy")

    -- Same for the faction name store, which is what the reputation
    -- resolver searches.
    CN:GetModule("Reputations").Scan()

    local resolved = CN.ResolveObjective(CN.objectiveTypes.REPUTATION,
        "Kirin Tor")

    assert(resolved == 1090,
        "and a faction by name, which is what the store page asks for: "
        .. tostring(resolved))

    -- A type with no resolver says so, rather than reporting the thing does
    -- not exist.
    local none, why = CN.ResolveObjective(CN.objectiveTypes.RECIPE, "Flask")

    assert(none == nil and why and why:find("by id"),
        "a type with no resolver must say it wants an id, not that the thing "
        .. "does not exist: " .. tostring(why))

    -- And a name nothing matches says THAT.
    local missing, reason = CN.ResolveObjective(CN.objectiveTypes.TOY,
        "no such toy at all")

    assert(missing == nil and reason and reason:find("matches"),
        "and a name nothing matches says so: " .. tostring(reason))

    -- Through the command, which is what a player actually types.
    CN.HandleSlashCommand("goal toy Test Toy")

    local goalsModule = CN:GetModule("Goals")

    local pinned = false

    for _, goal in ipairs(goalsModule.List()) do
        if goal.type == CN.objectiveTypes.TOY and goal.id == 500 then
            pinned = true
        end
    end

    assert(pinned, "/cn goal must accept a name")

    goalsModule.Remove(CN.objectiveTypes.TOY, 500)

    print("  goalsModule and chases accept a name wherever a resolver exists")
end)()

;(function()
    ------------------------------------------------------------
    -- ARRIVING SOMEWHERE IS A MOMENT WORTH ONE LINE.
    --
    -- The addon computed how many unpicked quests a zone holds on arrival and
    -- kept it to itself until somebody typed `/cn zone`. It is a prompt: a
    -- number and a command, no waypoint moved and nothing accepted.
    ------------------------------------------------------------
    local quests = CN:GetModule("Quests")

    local realMinimum = quests.arrivalMinimum

    -- The fixture zone offers two, so the bound is moved rather than the
    -- fixture: what is under test is the prompt, and the bound is tested
    -- separately below.
    quests.arrivalMinimum = 2

    quests.ForgetArrivals()

    local arrivalBefore = #output

    quests.AnnounceArrival(94)

    local announced = false

    for index = arrivalBefore + 1, #output do
        if output[index]:find("not picked up") then announced = true end
    end

    assert(announced, "arriving in a zone with quests in it must say so")

    -- Once per zone per session. A line that repeats is a line people turn
    -- off.
    local again = #output

    quests.AnnounceArrival(94)

    for index = again + 1, #output do
        assert(not output[index]:find("not picked up"),
            "and it must not say it twice")
    end

    -- BUT NOT NEVER AGAIN.
    --
    -- The latch was a permanent per-session flag, so a player who cleared the
    -- zone, flew to another continent and came back four hours later to the
    -- quests they left behind was never told -- which is the moment the
    -- prompt is most useful and the one moment it could not fire. A timestamp
    -- and a long window instead.
    local savedOffset = CN_TEST_TIME_OFFSET

    CN_TEST_TIME_OFFSET = CN_TEST_TIME_OFFSET
        + quests.arrivalMemorySeconds + 60

    local returned = #output

    quests.AnnounceArrival(94)

    local returnedAnnounced = false

    for index = returned + 1, #output do
        if output[index]:find("not picked up") then
            returnedAnnounced = true
        end
    end

    assert(returnedAnnounced,
        "coming back to a zone hours later must prompt again")

    CN_TEST_TIME_OFFSET = savedOffset

    -- Never in combat.
    quests.ForgetArrivals()

    CN_TEST_IN_COMBAT = true

    local fighting = #output

    quests.AnnounceArrival(94)

    for index = fighting + 1, #output do
        assert(not output[index]:find("not picked up"),
            "and never in the middle of a fight")
    end

    CN_TEST_IN_COMBAT = false

    -- AND A ZONE WITH ONE STRAY QUEST IN IT IS NOT WORTH A LINE.
    quests.arrivalMinimum = 99

    quests.ForgetArrivals()

    local quiet = #output

    quests.AnnounceArrival(94)

    for index = quiet + 1, #output do
        assert(not output[index]:find("not picked up"),
            "below the threshold there is nothing worth saying")
    end

    quests.arrivalMinimum = realMinimum

    quests.ForgetArrivals()

    print("  arriving in a zone prompts once, above a threshold, never "
        .. "mid-fight")
end)()

print("\nWhat 0.53.0 changed, asserted through the paths the game takes:")

;(function()
    local travel = CN:GetModule("Travel")

    ------------------------------------------------------------
    -- THE PARTS OF THE TRAVEL MODEL THAT ONLY RUN WHEN SOMETHING IS WRONG.
    --
    -- Every one of these is a refusal path -- no map, no continent, no
    -- nodes, a client that will not convert coordinates -- and a refusal path
    -- that has never run is a refusal path nobody knows the shape of. This is
    -- also the module where a wrong refusal is most expensive: it silently
    -- degrades every recommendation's travel cost.
    ------------------------------------------------------------
    assert(travel.WorldPoint(nil, 0.5, 0.5) == nil, "no map, no point")
    assert(travel.WorldPoint(94, nil, 0.5) == nil, "no coordinates, no point")

    assert(travel.YardsBetweenPoints(nil, nil) == nil,
        "two points that do not exist are not a distance")

    assert(travel.YardsBetweenPoints({ continent = 1, x = 0, y = 0 },
        { continent = 2, x = 0, y = 0 }) == nil,
        "and two continents apart is not a distance either -- a straight "
        .. "line across an ocean is meaningless, not merely imprecise")

    -- A map with no continent above it.
    assert(travel.ContinentFor(nil) == nil, "no map, no continent")

    local orphan = 987654

    assert(travel.ContinentFor(orphan) == nil,
        "a map the client does not know has no continent")

    assert(#(travel.KnownNodes(orphan)) == 0,
        "and therefore no flight points")

    -- The nearest-node search, which is the one piece of the model that runs
    -- on every single travel estimate.
    assert(travel.NearestNode(nil, {}) == nil, "no point, no nearest node")

    local nodes = travel.KnownNodes(94)

    assert(#nodes > 0, "the fixture continent must have nodes")

    local here = travel.WorldPoint(94, 0.5, 0.5)

    local nearest, nodeYards = travel.NearestNode(here, nodes)

    assert(nearest and nodeYards and nodeYards >= 0,
        "and a real point finds one, with a distance")

    assert(travel.NearestNode(here, nil) == nil,
        "an empty node list has no nearest member, which is not an error")

    -- A client that refuses every coordinate conversion, which is what a
    -- loading screen looks like from in here.
    local realConvert = C_Map.GetWorldPosFromMapPos

    C_Map.GetWorldPosFromMapPos = function() return nil, nil end

    travel.ForgetWorldPoints()
    travel.ForgetNodes()

    assert(travel.WorldPoint(94, 0.11, 0.11) == nil,
        "during a loading screen no point converts")

    assert(select(1, travel.EstimateSeconds(94, 0.1, 0.1, 94, 0.9, 0.9)) == nil,
        "so no journey can be costed, and the answer is nil rather than a "
        .. "fabricated number")

    C_Map.GetWorldPosFromMapPos = realConvert

    travel.ForgetWorldPoints()
    travel.ForgetNodes()

    assert(travel.WorldPoint(94, 0.11, 0.11) ~= nil,
        "and the refusal must NOT have been cached")

    -- The world-point cache is bounded, and the bound is reachable.
    local cap = travel.worldPointCap

    travel.ForgetWorldPoints()

    for index = 1, cap + 10 do
        travel.WorldPoint(94, (index % 1000) / 1000, ((index * 7) % 997) / 1000)
    end

    assert(travel.WorldPoint(94, 0.5, 0.5) ~= nil,
        "the cache empties itself at the ceiling and keeps working")

    travel.ForgetWorldPoints()
    travel.ForgetNodes()

    print("  the travel model's refusal paths all refuse, and none is cached")
end)()

;(function()
    local travel = CN:GetModule("Travel")

    ------------------------------------------------------------
    -- AN EMPTY FLIGHT-POINT LIST IS NOT AN ANSWER.
    --
    -- `GetAllTaxiNodes` answers usefully only while the client has the taxi
    -- map's data, and every node also needs a world position, which the
    -- client refuses during a loading screen -- which is when the cache is
    -- cleared. Remembering the resulting nothing degraded every flight
    -- estimate on the continent to "run there" for the rest of the session.
    ------------------------------------------------------------
    do
        local saved = CN_TEST_TAXI_NODES[1941]

        travel.ForgetNodes()

        CN_TEST_TAXI_NODES[1941] = {}

        assert(#travel.KnownNodes(94) == 0,
            "with no nodes the client can offer, the list is empty")

        CN_TEST_TAXI_NODES[1941] = saved

        assert(#travel.KnownNodes(94) > 0,
            "and the emptiness must NOT have been cached: the next query, "
            .. "once the client will answer, has to see the nodes")

        travel.ForgetNodes()

        print("  an empty flight-point list is not remembered")
    end

    ------------------------------------------------------------
    -- AND NO FLIGHT POINT IS REACHED ONLY OUTWARD.
    --
    -- Built one node at a time, the neighbour rule is about who each node
    -- reaches OUT to. A lone outpost picked its nearest four and every one of
    -- them filled its own four from the crowd nearby -- so the outpost had a
    -- way out and no way in, Dijkstra from the mainland never reached it, and
    -- it vanished from every route silently.
    ------------------------------------------------------------
    do
        local saved     = CN_TEST_TAXI_NODES[1941]
        local savedSpan = CN_TEST_MAP_SPAN

        CN_TEST_SetMapSpan({ 90000, 90000 })

        local scattered = {}

        for index = 1, 12 do
            table.insert(scattered, {
                nodeID = 800 + index,
                name   = "Cluster " .. index,
                state  = 1,
                position = {
                    x = 0.02 + ((index % 4) * 0.012),
                    y = 0.02 + ((index % 3) * 0.014),
                },
            })
        end

        table.insert(scattered, {
            nodeID = 899, name = "Lone Outpost", state = 1,
            position = { x = 0.97, y = 0.97 },
        })

        CN_TEST_TAXI_NODES[1941] = scattered

        travel.ForgetNodes()

        travel.FlightMemory()[94] = false

        -- Standing in the cluster, going to the outpost. The only sensible
        -- answer is a flight that ARRIVES at the outpost.
        local _, _, detail =
            travel.EstimateSeconds(94, 0.021, 0.021, 94, 0.971, 0.971)

        assert(detail and detail.mode == "fly",
            "a flight point at the far end of a continent must still be "
            .. "reachable; got " .. tostring(detail and detail.mode))

        assert(detail.arrival == "Lone Outpost",
            "and the route must land there, not somewhere near it; got "
            .. tostring(detail.arrival))

        travel.FlightMemory()[94] = nil

        CN_TEST_SetMapSpan(savedSpan)

        CN_TEST_TAXI_NODES[1941] = saved

        travel.ForgetNodes()

        print("  an isolated flight point is reachable, not merely reaching")
    end
end)()

;(function()
    ------------------------------------------------------------
    -- HIDING SOMETHING TAKES EFFECT NOW.
    --
    -- `CN.IsIgnored` is consulted inside candidate providers, at build time,
    -- so the ignore list is baked into the cached list. Without an explicit
    -- invalidation, clicking Ignore changed nothing until some unrelated
    -- event happened to make that provider dirty -- which for `Mounts` or
    -- `Sets` can be the rest of the session.
    ------------------------------------------------------------
    local errorsBefore = CN.Recommend(1)

    assert(errorsBefore and errorsBefore[1], "something must be recommended to ignore")

    local target = errorsBefore[1]

    CN.SetIgnored(target.type, target.id, true)

    local after = CN.Recommend(1)

    local stillThere = after and after[1]
        and after[1].type == target.type
        and after[1].id == target.id

    assert(not stillThere,
        "ignoring the top recommendation must remove it from the very next "
        .. "call, with nothing else happening in between")

    -- And putting it back must be just as immediate.
    local filterModule = CN:GetModule("Filters")

    filterModule.Restore(CN.ObjectiveKey(target.type, target.id))

    local restored, found = CN.Recommend(25), false

    for _, objective in ipairs(restored) do
        if objective.type == target.type and objective.id == target.id then
            found = true
        end
    end

    assert(found, "and un-hiding it must bring it back just as immediately")

    print("  ignoring and un-hiding take effect on the next call")
end)()

;(function()
    ------------------------------------------------------------
    -- `volatile` DOES NOT DEFEAT `cooldown`.
    --
    -- The volatile clause was a peer of the dirty clause rather than
    -- subordinate to `cooled`, so a provider declaring both rebuilt every
    -- five seconds whatever cooldown it asked for. `Waiting` and `Instances`
    -- each asked for thirty and got five -- six times more often than
    -- declared, for as long as the window stayed open.
    ------------------------------------------------------------
    local builds = 0

    CN.RegisterCandidateProvider("MutationVolatile", function()
        builds = builds + 1
        return {}
    end, { volatile = true, cooldown = 30 })

    CN.CollectCandidates(true)

    local baseline = builds

    -- Ten seconds later: past `candidateCacheSeconds`, well inside the
    -- cooldown the provider asked for.
    CN_TEST_TIME_OFFSET = CN_TEST_TIME_OFFSET + 10

    CN.CollectCandidates()

    assert(builds == baseline,
        "a provider that asked for a thirty-second cooldown must not rebuild "
        .. "after ten, however volatile it is")

    -- Past the cooldown, it must rebuild -- volatile still means volatile.
    CN_TEST_TIME_OFFSET = CN_TEST_TIME_OFFSET + 25

    CN.CollectCandidates()

    assert(builds > baseline,
        "but once the cooldown has passed, a volatile provider must go stale "
        .. "on its own")

    CN.candidateProviders["MutationVolatile"] = nil

    CN_TEST_TIME_OFFSET = 0

    CN.CollectCandidates(true)

    print("  a volatile provider still honours the cooldown it declared")
end)()

;(function()
    ------------------------------------------------------------
    -- A CLEAN SESSION DOES NOT ERASE A BAD ONE.
    --
    -- `Persist` ran unconditionally on logout, so the sequence the feature
    -- exists for destroyed its own evidence: something breaks, the player
    -- reloads before thinking to look, and the reload's empty ring overwrites
    -- the record. Players reload several times an hour.
    ------------------------------------------------------------
    local errors = CN:GetModule("Errors")

    errors.Clear()
    errors.ForgetPrevious()

    errors.Record("MutationContext", "something went wrong")

    errors.Persist()

    assert(#errors.Previous() == 1, "a real error must be persisted")

    -- A fresh, clean session, then a reload.
    errors.Clear()

    errors.Persist()

    assert(#errors.Previous() == 1,
        "a session in which nothing went wrong must leave the previous "
        .. "session's record alone")

    errors.ForgetPrevious()

    print("  a quiet session does not overwrite the last loud one")
end)()

;(function()
    ------------------------------------------------------------
    -- AN EARNED ACHIEVEMENT LEAVES THE SHORTLIST.
    --
    -- `CN.Shortlist` returns its held list whenever the revision matches, and
    -- the revision moved only on a full scan. Deleting the store row without
    -- moving it left the shortlist holding an orphaned record -- so the same
    -- event that invalidated the provider caused it to re-emit the
    -- achievement the player had just earned.
    ------------------------------------------------------------
    local achievements = CN:GetModule("Achievements")

    local store = achievements.Store()

    local id, record = next(store)

    assert(id, "the fixture must have an achievement in progress")

    local revisionBefore = achievements.revision

    for _, dispatch in ipairs(CN.eventTable["ACHIEVEMENT_EARNED"] or {}) do
        dispatch("ACHIEVEMENT_EARNED", id)
    end

    assert(store[id] == nil, "the store row goes")

    assert(achievements.revision ~= revisionBefore,
        "and the shortlist revision must move with it, or the shortlist "
        .. "keeps serving the record the store just released")

    store[id] = record

    print("  earning an achievement moves the shortlist revision")
end)()

;(function()
    ------------------------------------------------------------
    -- RIDING PAST A RARE IS NOT KILLING IT.
    --
    -- `GetVignettes` returns what is IN RANGE, and a vignette leaves that
    -- list for two different reasons: somebody killed it, or you rode away.
    -- The old code assumed the first, permanently, with no expiry and no
    -- undo -- so riding past a rare meant this character was never offered it
    -- again.
    ------------------------------------------------------------
    local raresModule = CN:GetModule("Rares")

    raresModule.ForgetCleared()

    raresModule.NoteDisappearances({})

    -- Seen at four hundred yards, then gone: that is the edge of vignette
    -- range, not a kill.
    raresModule.NoteDisappearances({})

    local far = { guid = "far-1", vignetteID = 777001, name = "Far Rare",
                  wasDead = false, yards = 400 }

    local near = { guid = "near-1", vignetteID = 777002, name = "Near Rare",
                   wasDead = false, yards = 20 }

    -- Drive it through the module's own state rather than around it.
    raresModule.SetLastSeen({ [far.guid] = far, [near.guid] = near })

    raresModule.NoteDisappearances({})

    assert(not raresModule.IsClearedByCharacter(777001),
        "a rare that vanished from four hundred yards away went out of "
        .. "range; it was not killed")

    assert(raresModule.IsClearedByCharacter(777002),
        "one that vanished from twenty yards away almost certainly was")

    raresModule.ForgetCleared()

    assert(not raresModule.IsClearedByCharacter(777002),
        "and the player can take it back, because inference that cannot be "
        .. "corrected is a wrong answer with a longer life")

    print("  a rare is cleared by proximity, not by disappearance")
end)()

;(function()
    ------------------------------------------------------------
    -- THE HANDYNOTES ITERATOR IS A TRIPLET.
    --
    -- `IteratePlugins` returns `next, self.plugins, nil`. Capturing only the
    -- first and writing `for name in iterator` calls `next(nil, nil)`, which
    -- throws -- so this integration could not work for any player who has
    -- HandyNotes installed. The old stub was a self-contained closure, the
    -- one shape under which the broken form works.
    ------------------------------------------------------------
    local handynotes = CN.HandyNotes

    assert(handynotes, "the HandyNotes provider must be reachable")

    local plugins = handynotes.GetPlugins()

    assert(#plugins == 1 and plugins[1] == "HandyNotes_Treasures",
        "the plugin list must come back from a pairs-style iterator; got "
        .. #plugins)

    local nodes = handynotes.GetNodesOnMap(94)

    assert(#nodes == 1 and nodes[1].label == "Hidden Cache",
        "and so must a plugin's nodes -- seventy lines that had no caller "
        .. "and could not have worked if they had; got " .. #nodes)

    print("  HandyNotes plugins and their nodes are actually readable")
end)()

;(function()
    ------------------------------------------------------------
    -- CLEARING DOES NOT DELETE THE PLAYER'S OWN PIN.
    --
    -- There is exactly one user waypoint and it belongs to the player unless
    -- this addon put it there. `/cn clearway`, stopping follow mode and every
    -- provider switch called ClearUserWaypoint unconditionally.
    ------------------------------------------------------------
    CN.ClearWaypoints()

    CN_TEST_USER_WAYPOINT = UiMapPoint.CreateFromCoordinates(94, 0.77, 0.77)

    assert(CN.ClearWaypoints() == false,
        "a pin this addon did not set must not be cleared")

    assert(CN_TEST_USER_WAYPOINT ~= nil, "and must still be there")

    CN_TEST_USER_WAYPOINT = nil

    print("  and a hand-placed pin survives /cn clearway")

    ------------------------------------------------------------
    -- AND A PIN THIS ADDON SET, THAT THE PLAYER THEN MOVED.
    --
    -- The ownership guard compared only `uiMapID`, and dragging a pin leaves
    -- it on the same map -- so the one case the guard exists for was the one
    -- case it could not see. Asserted through the provider the way the game
    -- reaches it: set, then have the client report a different position.
    ------------------------------------------------------------
    local blizzardPins = CN.waypointProviders["Blizzard"]

    assert(blizzardPins, "the Blizzard pin provider must be registered")

    assert(blizzardPins.SetWaypoint(94, 0.42, 0.42, "Ours"),
        "the addon sets its own pin")

    -- The player drags it. Same map, different place.
    CN_TEST_USER_WAYPOINT = UiMapPoint.CreateFromCoordinates(94, 0.61, 0.19)

    assert(blizzardPins.ClearAll() == false,
        "a pin the player has MOVED is theirs again and must not be cleared")

    assert(CN_TEST_USER_WAYPOINT ~= nil, "and must still be there")

    -- Unmoved, it is still ours to remove. The client round-trips
    -- coordinates, so a hair of drift must not read as a drag.
    assert(blizzardPins.SetWaypoint(94, 0.42, 0.42, "Ours"),
        "set again")

    CN_TEST_USER_WAYPOINT =
        UiMapPoint.CreateFromCoordinates(94, 0.42 + 1e-7, 0.42 - 1e-7)

    assert(blizzardPins.ClearAll() == true,
        "a pin still where the addon put it is still the addon's to clear")

    assert(CN_TEST_USER_WAYPOINT == nil, "and is gone")

    CN_TEST_USER_WAYPOINT = nil

    print("  and a pin the player dragged is theirs again")
end)()

;(function()
    ------------------------------------------------------------
    -- BOTH WAYPOINT PROVIDERS, ON THEIR FAILURE PATHS.
    --
    -- The Blizzard map-pin provider is the fallback every player without
    -- TomTom lands on, and its refusal paths -- absent API, a map point the
    -- client will not build, a map that forbids waypoints -- were the least
    -- covered lines in the addon. They are also the ones that used to return
    -- silently and let the caller announce a success.
    ------------------------------------------------------------
    local blizzard = CN.waypointProviders["Blizzard"]
    local tomtom   = CN.waypointProviders["TomTom"]

    assert(blizzard and tomtom, "both providers must be registered")

    assert(blizzard.IsAvailable(), "the map API is present in the harness")

    -- A client that will not build a map point.
    local realCreate = UiMapPoint.CreateFromCoordinates

    UiMapPoint.CreateFromCoordinates = function() return nil end

    local legsBuilt, why = blizzard.SetWaypoint(94, 0.3, 0.3, "No Point")

    assert(legsBuilt == false and why and why:find("map point"),
        "a client that will not build a map point must be reported, not "
        .. "swallowed: " .. tostring(why))

    UiMapPoint.CreateFromCoordinates = realCreate

    -- The whole API gone -- an older client, or a broken one.
    local realSet = C_Map.SetUserWaypoint

    C_Map.SetUserWaypoint = nil

    assert(blizzard.IsAvailable() == false,
        "with no SetUserWaypoint the provider is not available")

    assert(blizzard.SetWaypoint(94, 0.3, 0.3, "Gone") == false,
        "and it refuses rather than erroring")

    C_Map.SetUserWaypoint = realSet

    -- Clearing with nothing of ours set.
    CN_TEST_USER_WAYPOINT = nil

    assert(blizzard.ClearAll() == false,
        "clearing when this addon owns nothing removes nothing")

    -- And the round trip.
    assert(blizzard.SetWaypoint(94, 0.3, 0.3, "Ours") == true,
        "an ordinary map still works")

    assert(blizzard.ClearAll() == true, "and its own pin is removed")

    -- TOMTOM, INCLUDING THE CASE WHERE IT REFUSES.
    local realTomTom = _G.TomTom

    _G.TomTom = nil

    assert(tomtom.IsAvailable() == false, "no TomTom, no TomTom provider")

    local asked, absent = tomtom.SetWaypoint(94, 0.3, 0.3, "Nowhere")

    assert(asked == false and absent and absent:find("TomTom"),
        "and it says which addon is missing rather than returning nil")

    assert(tomtom.ClearAll() == false, "clearing is a no-op, reported as one")

    _G.TomTom = realTomTom

    -- TomTom present but refusing the waypoint.
    local realAdd = _G.TomTom.AddWaypoint

    _G.TomTom.AddWaypoint = function() return nil end

    local refusedWaypoint, reason = tomtom.SetWaypoint(94, 0.3, 0.3, "Refused")

    assert(refusedWaypoint == false and reason and reason:find("refused"),
        "a TomTom that returns no uid has not set a waypoint")

    _G.TomTom.AddWaypoint = realAdd

    -- THE SECOND RETURN IS A SENTENCE FOR THE PLAYER, NEVER A HANDLE.
    -- 0.79.0.
    --
    -- This returned the waypoint uid on success -- a table -- while the
    -- native provider returns a caveat string there, and 0.78.0 began
    -- PRINTING that position on success. So every `/cn go` for a player who
    -- had chosen TomTom printed `table: 0x...` under the headline, which
    -- reads as a crash. The uid is tracked in the provider's own list, which
    -- is what `ClearAll` walks.
    local placed, second = tomtom.SetWaypoint(94, 0.3, 0.3, "Real")

    assert(placed == true, "and a real one is placed")

    assert(second == nil or type(second) == "string",
        "and hands back nothing the caller could print by accident: "
        .. type(second))

    assert(tomtom.ClearAll() == true, "which it then removes")

    assert(tomtom.ClearAll() == false,
        "and removing nothing twice is reported honestly")

    print("  both waypoint providers exercised on their refusal paths")
end)()

;(function()
    ------------------------------------------------------------
    -- HANDYNOTES WHEN IT IS NOT THERE, AND WHEN IT IS BROKEN.
    ------------------------------------------------------------
    local handynotes = CN.HandyNotes

    local real = _G.HandyNotes

    _G.HandyNotes = nil

    assert(handynotes.IsAvailable() == false, "absent means absent")
    assert(#handynotes.GetPlugins() == 0, "and no plugins")
    assert(#handynotes.GetNodesOnMap(94) == 0, "and no nodes")
    assert(handynotes.Describe() == "not installed", "and it says so")

    -- Present, but with no plugin registry at all -- an older HandyNotes, or
    -- one that has not finished loading.
    _G.HandyNotes = { IteratePlugins = nil, plugins = nil }

    assert(handynotes.Describe() == "loaded, no plugins registered",
        "a HandyNotes with nothing registered is described accurately")

    -- Present, with the registry as a plain table rather than an iterator.
    _G.HandyNotes = { plugins = { Alpha = {}, Beta = {} } }

    local fallback = handynotes.GetPlugins()

    assert(#fallback == 2 and fallback[1] == "Alpha",
        "the plain-table fallback still finds them, sorted")

    assert(handynotes.Describe():find("2 plugins"),
        "and the description names how many")

    -- A plugin whose node iterator throws must cost the plugin, not the call.
    _G.HandyNotes = {
        IteratePlugins = function()
            return next, {
                Broken = {
                    GetNodes2 = function() error("plugin exploded") end,
                },
            }, nil
        end,
    }

    assert(#handynotes.GetNodesOnMap(94) == 0,
        "a plugin that throws contributes nothing and does not take the "
        .. "addon down with it")

    _G.HandyNotes = real

    assert(handynotes.IsAvailable(), "and the real stub is back")

    print("  HandyNotes absent, empty, plain-table and broken all handled")
end)()

;(function()
    ------------------------------------------------------------
    -- RESOLVING A COLLECTIBLE BY NAME, WHICH IS HOW PEOPLE TYPE.
    --
    -- `/cn toy Test Toy` has to turn words into an item id, and the addon's
    -- rule -- shortest matching name wins, because a substring match against
    -- a long name is usually the wrong row -- had never been executed.
    ------------------------------------------------------------
    local toysModule = CN:GetModule("Toys")

    assert(toysModule, "the Toys module must load")

    toysModule.Scan()

    local counts = toysModule.Summary()

    assert(counts.known >= 2, "the fixture's toys are read, got " .. counts.known)
    assert(counts.collected + counts.missing == counts.known,
        "and every one is either collected or not")

    assert(toysModule.Resolve("500") == 500, "a bare id resolves to itself")

    assert(toysModule.Resolve("Test Toy") == 500,
        "and a full name resolves to its id")

    assert(toysModule.Resolve("toy") ~= nil,
        "a substring matches something")

    assert(toysModule.Resolve("") == nil, "an empty string resolves to nothing")
    assert(toysModule.Resolve(nil) == nil, "and so does nothing at all")

    assert(toysModule.Resolve("no such toy anywhere") == nil,
        "a name nothing matches resolves to nil rather than to whatever "
        .. "happened to be first")

    -- An id the player's client does not have is not a resolution either.
    assert(toysModule.Resolve("999999") == nil,
        "an id with no record behind it is not a match")

    -- THE ELIGIBILITY LINE, which is what `/cn why` prints for a toy.
    local checker = CN.eligibilityCheckers
        and CN.eligibilityCheckers[CN.objectiveTypes.TOY]

    if checker then
        local state, reason = checker(500)

        assert(state and reason,
            "a toy the addon knows about has a state and a sentence")

        local unknownState, unknownReason = checker(999999)

        assert(unknownState == CN.objectiveStates.UNKNOWN
            and unknownReason and unknownReason:find("toyscan"),
            "and one it does not know says which scan would tell it: "
            .. tostring(unknownReason))
    end

    -- With the toy box gone entirely, a scan is a no-op rather than an error.
    local realToyBox = C_ToyBox

    C_ToyBox = nil

    local seen, gotCollected, gotMissing = toysModule.Scan()

    assert(seen == 0 and gotCollected == 0 and gotMissing == 0,
        "no toy box, nothing scanned, and no error")

    C_ToyBox = realToyBox

    print("  toys resolve by id and by name, shortest match winning")
end)()

;(function()
    ------------------------------------------------------------
    -- THE CLIENT WRAPPER, WITH THE CLIENT TAKEN AWAY.
    --
    -- Providers/Blizzard.lua is the layer every other file asks its questions
    -- through, and every function in it is a guard around an API that may not
    -- exist on this client, may return nil, or may throw. Those guards are
    -- what stop a renamed API from becoming a Lua error popup -- and the
    -- failure branches had never been executed, because the harness defines
    -- everything the addon calls.
    ------------------------------------------------------------
    local Blizzard = CN.Blizzard

    local saved = {}

    local function Remove(name)
        saved[name] = _G[name]
        _G[name] = nil
    end

    local function Restore()
        for name, value in pairs(saved) do
            _G[name] = value
        end

        saved = {}
    end

    -- Quest completion, with both APIs gone.
    Remove("C_QuestLog")

    assert(Blizzard.IsQuestCompletedByCharacter(1234) == false,
        "no quest API means 'not completed', not an error")

    assert(Blizzard.IsQuestInLog(1234) == false, "and nothing is in the log")
    assert(Blizzard.IsQuestReadyForTurnIn(1234) == false,
        "and nothing is ready to hand in")
    assert(Blizzard.IsQuestComplete(1234) == false,
        "and nothing is complete")

    assert(Blizzard.GetQuestTitle(1234) == nil,
        "and no quest has a title")

    assert(#Blizzard.GetQuestLogEntries() == 0,
        "and the log is empty rather than nil")

    local doneCount, totalCount = Blizzard.GetQuestObjectiveProgress(1234)

    assert(doneCount == 0 and totalCount == 0,
        "and objective progress is zero of zero rather than nil arithmetic")

    assert(#Blizzard.GetCountingObjectives(1234) == 0,
        "and nothing counts")

    Restore()

    -- The account-wide completion API, which older clients do not have.
    local realAccount = C_QuestLog.IsQuestFlaggedCompletedOnAccount

    C_QuestLog.IsQuestFlaggedCompletedOnAccount = nil

    assert(Blizzard.HasAccountQuestAPI() == false,
        "a client without the Warband API says so")

    assert(Blizzard.IsQuestCompletedOnAccount(1234) == false,
        "and answers false rather than guessing from the character")

    C_QuestLog.IsQuestFlaggedCompletedOnAccount = realAccount

    -- Map POIs, with the POI API gone.
    Remove("C_QuestLog")
    Remove("C_TaskQuest")

    assert(Blizzard.GetQuestPOIOnMap(1234, 94) == nil,
        "no POI API, no POI")

    assert(#Blizzard.GetQuestPOIsOnMap(94) == 0,
        "and no pins on the map")

    -- The waypoint search falls back to "the map you are on, with no
    -- coordinates", which is a real and useful answer: it is how a zone gets
    -- named for a quest whose blip the client will not draw.
    local fallbackMap, fallbackX = Blizzard.GetQuestWaypoint(1234)

    assert(fallbackX == nil,
        "with no POI API there are no coordinates to invent")

    assert(fallbackMap == nil or type(fallbackMap) == "number",
        "and what comes back is a map or nothing, never a guess")

    assert(Blizzard.GetQuestWaypoint(nil) == nil,
        "and no quest is no waypoint")

    assert(Blizzard.GetQuestZone(1234) == nil,
        "and no zone for one either")

    Restore()

    -- Reputations, with the whole namespace gone.
    Remove("C_Reputation")
    Remove("C_MajorFactions")

    assert(Blizzard.GetNumFactions() == 0, "no reputation API, no factions")
    assert(Blizzard.GetFactionByIndex(1) == nil, "and none by index")
    assert(Blizzard.GetFactionByID(2600) == nil, "and none by id")
    assert(Blizzard.IsAccountWideReputation(2600) == false,
        "and nothing is account-wide")
    assert(Blizzard.IsMajorFaction(2600) == false,
        "and nothing is a major faction")
    assert(Blizzard.GetMajorFactionData(2600) == nil, "with no renown data")
    assert(Blizzard.HasMaximumRenown(2600) == false, "and no maximum")
    assert(Blizzard.IsFactionParagon(2600) == false, "and no paragon")
    assert(Blizzard.GetParagonInfo(2600) == nil, "and no paragon numbers")

    -- And the expand/restore wrapper must still run its inner work, because
    -- refusing to scan because the collapse API is missing would lose the
    -- whole reputation feature on a client that simply reads differently.
    local ran = false

    Blizzard.WithAllFactionsExpanded(function() ran = true end)

    assert(ran,
        "the scan still runs when the client cannot expand headers; the "
        .. "headers are a convenience, the standings are the point")

    Restore()

    -- Professions returns a fixed-slot tuple with holes in it, which is the
    -- shape `ipairs` silently truncates.
    local realProfessions = GetProfessions

    GetProfessions = function() return nil, 2, nil, nil, 5 end

    local professions = Blizzard.GetProfessions()

    assert(type(professions) == "table",
        "a tuple full of holes still produces a table")

    GetProfessions = nil

    assert(type(Blizzard.GetProfessions()) == "table",
        "and no API at all produces an empty one rather than nil")

    GetProfessions = realProfessions

    print("  the client wrapper degrades on every API it wraps")
end)()

;(function()
    ------------------------------------------------------------
    -- PREREQUISITES, AND THE ORDER OF AUTHORITY BETWEEN THEIR SOURCES.
    --
    -- `CN.GetPrerequisites` merges four sources -- a curated record, this
    -- account's own observations, the shipped community table, and chains
    -- imported by hand -- deduplicating as it goes and adding them in
    -- descending order of how much they should be believed. That ordering is
    -- the whole design of the function and nothing exercised it.
    ------------------------------------------------------------
    local quests = CN:GetModule("Quests")

    local realRecord = quests.GetRecord

    quests.GetRecord = function(questID)
        if questID == 999001 then
            return { requires = { 111, 222 } }, "curated"
        end

        return nil
    end

    CN.Account("questHarvest")[999001] = { observedRequires = { 222, 333 } }
    CN.Account("contributed")[999001]  = { 444 }

    local ordered = CN.GetPrerequisites(999001)

    assert(#ordered == 4,
        "four distinct prerequisites across three sources, got " .. #ordered)

    assert(ordered[1] == 111 and ordered[2] == 222,
        "curated data comes first")

    assert(ordered[3] == 333,
        "then what this account observed for itself")

    assert(ordered[4] == 444,
        "then what somebody else contributed -- the weakest source, added "
        .. "last, which is the order of authority")

    -- 222 appears in two sources and must appear once.
    local occurrences = 0

    for _, id in ipairs(ordered) do
        if id == 222 then occurrences = occurrences + 1 end
    end

    assert(occurrences == 1, "a prerequisite two sources agree on is one "
        .. "prerequisite, not two")

    -- A quest nothing knows about has no prerequisites, rather than an error.
    assert(#CN.GetPrerequisites(999002) == 0,
        "an unknown quest has no prerequisites")

    CN.Account("questHarvest")[999001] = nil
    CN.Account("contributed")[999001]  = nil

    quests.GetRecord = realRecord

    -- AND THE MODULE-ABSENT PATH, which is what every one of these guards is
    -- for: an addon that loads without one of its own modules must degrade,
    -- not throw.
    local realGet = CN.GetModule

    CN.GetModule = function(self, name)
        if name == "Quests" then
            return nil
        end

        return realGet(self, name)
    end

    assert(#CN.GetPrerequisites(999001) == 0,
        "with the Quests module gone, prerequisites are empty rather than an "
        .. "error")

    assert(CN.IsQuestComplete(999001) == false,
        "and completion is false rather than an error")

    CN.GetModule = realGet

    print("  prerequisites merge four sources in order of authority")
end)()

;(function()
    ------------------------------------------------------------
    -- THE ROUTE'S PROGRESS COUNTER, AND THE ONE MOMENT WORTH A FLOURISH.
    --
    -- `Follow.NoteStopCleared` is what the player sees as they walk a route,
    -- and the "Route complete" branch is the only celebratory thing this
    -- addon does. Neither was executed by any test -- and the counter has a
    -- history: a denominator frozen at the start produced "Stop 9 of 8
    -- cleared" and fired the flourish four times while stops remained.
    ------------------------------------------------------------
    local follow = CN:GetModule("Follow")

    local followSettings = CN.Settings()

    local realCues = followSettings.cues

    -- Cues off is the default, and off must mean off.
    followSettings.cues = nil

    assert(follow.Cue("stop") == false,
        "with cues off, nothing is played -- unsolicited noise is the most "
        .. "intrusive thing an addon can do")

    followSettings.cues = true

    assert(follow.Cue("stop") == true, "with cues on, the stop moment fires")
    assert(follow.Cue("arrival") == true, "so does arrival")
    assert(follow.Cue() == true, "and the default moment is the route")
    assert(follow.Celebrate() == true, "which is what Celebrate plays")

    -- An unknown moment must not error; it simply has no sound.
    assert(follow.Cue("nonsense") == true,
        "an unrecognised moment is a no-op, not a failure")

    -- THE COUNTER.
    follow.completed   = 0
    follow.startedWith = 3
    follow.celebrated  = false

    assert(follow.NoteStopCleared() == 1, "clearing counts")
    assert(follow.NoteStopCleared() == 2, "and counts again")

    local flourishBefore = #output

    assert(follow.NoteStopCleared() == 3, "and reaches the total")

    local celebrated = false

    for index = flourishBefore + 1, #output do
        if output[index]:find("Route complete", 1, true) then
            celebrated = true
        end
    end

    assert(celebrated,
        "reaching the end of a route is the one moment this addon marks")

    -- And it must not fire again past the end.
    local past = #output

    follow.NoteStopCleared()

    for index = past + 1, #output do
        assert(not output[index]:find("stops, everything on it done"),
            "the flourish fires once, not on every stop past the total")
    end

    -- With no total known, the message is the short form rather than an
    -- invented denominator.
    follow.completed   = 0
    follow.startedWith = 0
    follow.celebrated  = false

    local unknown = #output

    follow.NoteStopCleared()

    local named = false

    for index = unknown + 1, #output do
        if output[index]:find("of") and output[index]:find("cleared") then
            named = true
        end
    end

    assert(not named,
        "with no total, the addon does not invent one to count against")

    followSettings.cues      = realCues
    follow.completed   = 0
    follow.startedWith = 0
    follow.celebrated  = false

    print("  route progress counts up, and the flourish fires exactly once")
end)()

print("\nGetting there:")

;(function()
    local travel = CN:GetModule("Travel")

    assert(travel, "the Travel module must load")

    travel.ForgetNodes()

    local savedSpan = CN_TEST_MAP_SPAN

    CN_TEST_SetMapSpan({ 4000, 4000 })

    ------------------------------------------------------------
    -- TWO MAPS USED TO MEAN NO DISTANCE AT ALL.
    --
    -- Map coordinates are normalized per map, so 0.5 on one map and 0.5 on
    -- another are not comparable and the old code returned nil. World
    -- coordinates are yards and are continuous across a continent.
    ------------------------------------------------------------
    local sameMap = travel.YardsBetween(94, 0.1, 0.5, 94, 0.2, 0.5)

    assert(sameMap and math.abs(sameMap - 400) < 1,
        "a tenth of a 4000 yard map is 400 yards, got " .. tostring(sameMap))

    local crossMap = travel.YardsBetween(94, 0.1, 0.5, 2112, 0.2, 0.5)

    assert(crossMap, "two different maps must still yield a distance")

    print("  cross-map distances are measured in world yards")

    ------------------------------------------------------------
    -- ONLY FLIGHT POINTS YOU HAVE DISCOVERED.
    --
    -- Costing a journey through an undiscovered flight master produces a plan
    -- the player cannot follow, which is worse than a pessimistic one.
    ------------------------------------------------------------
    local nodes, continent = travel.KnownNodes(94)

    assert(continent == 1941, "the continent must be found by walking parents, got "
        .. tostring(continent))

    -- >=, not ==: the bench grows this fixture to a continent's worth of
    -- flight points, and a test that pins an exact count is a test that
    -- forbids the bench from measuring anything realistic.
    assert(#nodes >= 2, "an undiscovered node must not be usable, got " .. #nodes)

    for _, node in ipairs(nodes) do
        assert(node.name ~= "Undiscovered", "and specifically not that one")
    end

    print("  " .. #nodes .. " known flight points; the undiscovered one is not offered")

    ------------------------------------------------------------
    -- FLYING MUST BEAT RUNNING WHEN, AND ONLY WHEN, IT IS QUICKER.
    ------------------------------------------------------------
    local far, farConfident, farDetail =
        travel.EstimateSeconds(94, 0.40, 0.50, 94, 0.90, 0.50)

    assert(far, "a long journey must be costable")

    assert(farDetail.mode == "fly",
        "across the continent, with a flight point at each end, flying wins")

    local session = CN:GetModule("Session")

    local runSpeed = session.Speed()

    local runningTheWholeWay = farDetail.yards / runSpeed

    assert(far < runningTheWholeWay,
        "and it must actually be quicker than running: "
        .. string.format("%.0f vs %.0f seconds", far, runningTheWholeWay))

    -- A SHORT HOP MUST NOT BE FLOWN.
    --
    -- Deliberately positioned so the two ends have DIFFERENT nearest flight
    -- points, which means the flight branch is actually evaluated and
    -- rejected on cost. The first version of this case put both ends next to
    -- the same node, so the comparison never ran at all and the rule could
    -- have been deleted without the suite noticing.
    local near, _, nearDetail =
        travel.EstimateSeconds(94, 0.40, 0.50, 94, 0.66, 0.50)

    assert(nearDetail.mode == "run",
        "a journey quicker on foot must be run, not flown")

    -- NOT "cheaper than the long journey", which was the first assertion here
    -- and was simply false: a long flight legitimately beats a medium run,
    -- and asserting otherwise would have forced a wrong answer into the code.
    -- The property that matters is that a run estimate is a run: the whole
    -- distance at running speed, with no flight overhead hidden in it.
    assert(math.abs(near - (nearDetail.yards / runSpeed)) < 1,
        "a run estimate must be the whole distance at running speed, got "
        .. string.format("%.0f vs %.0f", near, nearDetail.yards / runSpeed))

    print("  a long journey flies, a short one runs")

    ------------------------------------------------------------
    -- THE FAST PAIR SEARCH MUST FIND WHAT THE SLOW ONE FOUND.
    --
    -- 0.46.0 rewrote the pair search: the two ends are measured once per node
    -- instead of once per pair, the flight legs come from a table computed
    -- once per continent, and an origin whose walk alone already beats the
    -- standing best is abandoned unexamined. That last one is a pruning rule,
    -- and a pruning rule that is subtly wrong does not error -- it quietly
    -- returns the second-best route forever.
    --
    -- So this brute-forces the answer independently and demands the same
    -- number. With enough nodes spread widely enough that the pruning
    -- actually fires.
    ------------------------------------------------------------
    -- THE SAME MODEL, WRITTEN A SECOND TIME AND A DIFFERENT WAY.
    --
    -- 0.53.0 made the flight leg the shortest path through the flight network
    -- rather than the straight line across it, so an exhaustive comparison
    -- that measures node-to-node distance directly no longer describes the
    -- thing under test -- it describes the model the addon replaced.
    --
    -- This rebuilds the network from the addon's published rule (hopYards,
    -- minimumNeighbours) and solves it with Floyd-Warshall, which shares no
    -- code and no shape with the addon's cached per-origin Dijkstra. Two
    -- independent solvers of the same graph must agree, and a graph the two
    -- disagree about is a defect in one of them.
    local function NetworkDistances(list)
        local sourceCount = #list
        local dist  = {}

        for i = 1, sourceCount do
            dist[i] = {}
            dist[i][i] = 0
        end

        for i = 1, sourceCount do
            local rankedSources = {}

            for j = 1, sourceCount do
                if i ~= j then
                    table.insert(rankedSources, {
                        index = j,
                        yards = travel.YardsBetweenPoints(
                            list[i].point, list[j].point),
                    })
                end
            end

            table.sort(rankedSources, function(a, right)
                if a.yards == right.yards then
                    return a.index < right.index
                end

                return a.yards < right.yards
            end)

            for rank, entry in ipairs(rankedSources) do
                if entry.yards <= travel.hopYards
                    or rank <= travel.minimumNeighbours then

                    -- Undirected: a flight path connects both ways, so an
                    -- edge either node claims is an edge.
                    dist[i][entry.index] = entry.yards
                    dist[entry.index][i] = entry.yards
                end
            end
        end

        for k = 1, sourceCount do
            for i = 1, sourceCount do
                local ik = dist[i][k]

                if ik then
                    for j = 1, sourceCount do
                        local kj = dist[k][j]

                        if kj and (not dist[i][j] or (ik + kj) < dist[i][j]) then
                            dist[i][j] = ik + kj
                        end
                    end
                end
            end
        end

        return dist
    end

    do
        local saved = CN_TEST_TAXI_NODES[1941]

        local savedCount = #travel.KnownNodes(94)

        local crowded = {}

        for index, node in ipairs(saved) do
            crowded[index] = node
        end

        for index = 4, 40 do
            crowded[index] = {
                nodeID = 500 + index,
                name   = "Spread " .. index,
                state  = 1,
                position = {
                    x = 0.02 + (((index * 7) % 24) * 0.04),
                    y = 0.02 + (((index * 11) % 19) * 0.05),
                },
            }
        end

        CN_TEST_TAXI_NODES[1941] = crowded

        travel.ForgetNodes()

        local nodeList = travel.KnownNodes(94)

        assert(#nodeList >= 30,
            "the brute-force comparison needs a crowded continent, got "
            .. #nodeList)

        -- ROUTES THE PLAYER HAS ACTUALLY FLOWN, BEFORE THE COMPARISON RUNS.
        --
        -- The first version of this test noted none, so `knownRouteBonus` --
        -- the one multiplicative term in the whole calculation -- was never
        -- applied while the exhaustive check ran. It therefore agreed with a
        -- pruning bound that ignored the discount entirely, and passed. A
        -- brute-force comparison is only as honest as the state it runs
        -- against.
        for index = 1, #nodeList - 1 do
            travel.NoteRoute(nodeList[index].id, nodeList[index + 1].id)
            travel.NoteRoute(nodeList[#nodeList].id, nodeList[index].id)
        end

        local seconds, _, detail = travel.EstimateSeconds(94, 0.05, 0.05, 94, 0.95, 0.95)

        -- Independently, the long way round: every pair, every distance
        -- recomputed, nothing pruned and nothing cached.
        local from = travel.WorldPoint(94, 0.05, 0.05)
        local to   = travel.WorldPoint(94, 0.95, 0.95)

        local flightSpeed = travel.FlightSpeed()

        local brute = travel.YardsBetweenPoints(from, to) / runSpeed

        local bruteRanking = brute

        if travel.CanFly(94) then
            brute = math.min(brute,
                (travel.YardsBetweenPoints(from, to) / travel.SelfFlightSpeed())
                    + travel.takeoffSeconds)
        end

        local bruteNetwork = NetworkDistances(nodeList)

        for i, origin in ipairs(nodeList) do
            for j, arrival in ipairs(nodeList) do
                local through = (i ~= j) and bruteNetwork[i][j] or nil

                if origin.id ~= arrival.id and through then
                    local candidate =
                        (travel.YardsBetweenPoints(from, origin.point) / runSpeed)
                        + travel.flightOverheadSeconds
                        + (through / flightSpeed)
                        + (travel.YardsBetweenPoints(to, arrival.point) / runSpeed)

                    local rankedCandidate = candidate

                    if travel.IsKnownRoute(origin.id, arrival.id) then
                        rankedCandidate = rankedCandidate * travel.knownRouteBonus
                    end

                    if rankedCandidate < bruteRanking then
                        bruteRanking = rankedCandidate
                        brute        = candidate
                    end
                end
            end
        end

        assert(math.abs(seconds - brute) < 0.001,
            "the pruned search returned " .. string.format("%.3f", seconds)
            .. " where an exhaustive one finds "
            .. string.format("%.3f", brute))

        -- AND THE REPORTED LEGS MUST ADD UP TO THE REPORTED TOTAL.
        --
        -- The rewrite carries the walked distances as seconds internally and
        -- converts them back for display. A wrong conversion there is
        -- invisible in the total and wrong on every screen that shows the
        -- breakdown.
        if detail and detail.mode == "fly" then
            local rebuilt = (detail.runToNode / runSpeed)
                + travel.flightOverheadSeconds
                + (detail.flightYards / flightSpeed)
                + (detail.runFromNode / runSpeed)

            -- NO DISCOUNT HERE ANY MORE. The known-route preference is a
            -- tie-break in the comparison, not a reduction of the duration --
            -- which is the whole point: `/cn travel` used to print legs that
            -- summed to fifty seconds more than its own headline.

            assert(math.abs(rebuilt - seconds) < 0.01,
                "the legs shown add to " .. string.format("%.3f", rebuilt)
                .. " but the estimate says " .. string.format("%.3f", seconds))
        end

        print("  " .. #nodeList .. " flight points; the fast pair search agrees "
            .. "with an exhaustive one")

        ------------------------------------------------------------
        -- AND THE PRUNING MUST NOT DISCARD A LONG WALK TO A GOOD FLIGHT.
        --
        -- The brute-force case above passes even with a badly wrong bound,
        -- because its winning route happens to start at a flight point close
        -- to the player. The route the bound could actually lose is the
        -- opposite shape: a long walk to a flight master that lands you
        -- exactly where you are going. That is a real and common shape, and
        -- it is the one a careless bound throws away.
        ------------------------------------------------------------
        CN_TEST_TAXI_NODES[1941] = {
            { nodeID = 90, name = "Halfway Out", state = 1,
              position = { x = 0.62, y = 0.62 } },
            { nodeID = 91, name = "At The Door", state = 1,
              position = { x = 0.95, y = 0.95 } },
        }

        travel.ForgetNodes()

        -- Grounded on purpose: with flying available the self-flown line
        -- beats everything and the pair search never decides anything.
        travel.FlightMemory()[94] = false

        local walked, _, walkedDetail =
            travel.EstimateSeconds(94, 0.05, 0.05, 94, 0.95, 0.95)

        assert(walkedDetail and walkedDetail.mode == "fly",
            "a long walk to a flight point that lands at the target must "
            .. "still beat walking the whole way, got "
            .. tostring(walkedDetail and walkedDetail.mode))

        assert(walkedDetail.node == "Halfway Out"
            and walkedDetail.arrival == "At The Door",
            "and it must be that pair, got "
            .. tostring(walkedDetail.node) .. " -> "
            .. tostring(walkedDetail.arrival))

        assert(walked < (travel.YardsBetweenPoints(from, to) / runSpeed),
            "and it must actually be quicker than the walk it replaces")

        travel.FlightMemory()[94] = nil

        print("  a long walk to the right flight point is not pruned away")

        ------------------------------------------------------------
        -- SOME JOURNEYS NEED TWO HOPS, AND THE CHAIN MUST BE PRINTABLE.
        --
        -- Backlog item 5. A straight line between the two ends of a chain of
        -- flight masters is not the distance a taxi flies, and until 0.53.0
        -- that was the number every long flight was costed with -- wrong
        -- always in the same direction, so distant objectives were
        -- systematically preferred over near ones.
        --
        -- A chain of flight masters in an L, spaced further apart than the
        -- direct-connection radius so that the network is a chain rather
        -- than a clique. The straight line from one end to the other cuts
        -- the corner; the bird does not.
        ------------------------------------------------------------
        do
            local spanBefore = CN_TEST_MAP_SPAN

            CN_TEST_SetMapSpan({ 40000, 40000 })

            local chain = {}

            for step = 0, 6 do
                table.insert(chain, {
                    nodeID = 70 + step,
                    name   = "Chain " .. (step + 1),
                    state  = 1,
                    position = { x = 0.05, y = 0.05 + (step * 0.15) },
                })
            end

            table.insert(chain, {
                nodeID = 77, name = "Chain 8", state = 1,
                position = { x = 0.35, y = 0.95 },
            })

            CN_TEST_TAXI_NODES[1941] = chain

            travel.ForgetNodes()

            travel.FlightMemory()[94] = false

            local hopped, hopConfident, hopDetail =
                travel.EstimateSeconds(94, 0.05, 0.04, 94, 0.36, 0.96)

            assert(hopDetail and hopDetail.mode == "fly",
                "the chain case must decide on a flight, got "
                .. tostring(hopDetail and hopDetail.mode))

            assert(hopDetail.hops and hopDetail.hops >= 2,
                "and it must take more than one hop, got "
                .. tostring(hopDetail.hops))

            assert(hopDetail.legs and #hopDetail.legs == hopDetail.hops,
                "and every hop must be printable as a leg")

            -- The legs are what the player is shown. If they do not add up to
            -- the distance the estimate was built from, the breakdown is
            -- decoration.
            local summed = 0

            for _, leg in ipairs(hopDetail.legs) do
                assert(leg.from and leg.to,
                    "a leg with no ends is not a leg")

                summed = summed + (leg.yards or 0)
            end

            assert(math.abs(summed - hopDetail.flightYards) < 0.001,
                "the legs sum to " .. string.format("%.3f", summed)
                .. " but the flight is " .. string.format("%.3f",
                    hopDetail.flightYards))

            -- And the path must be longer than the line it replaces, which is
            -- the entire reason for the change.
            local straight = travel.YardsBetweenPoints(
                travel.WorldPoint(94, 0.05, 0.05),
                travel.WorldPoint(94, 0.35, 0.95))

            assert(hopDetail.flightYards > straight,
                "a route through the network cannot be shorter than the "
                .. "straight line it replaces")

            -- A multi-hop route rests on an inferred edge list, so it is
            -- never reported as measured however good the speed data is.
            assert(hopConfident == false,
                "a multi-hop estimate must not be reported as confident")

            assert(hopped > 0, "and it must still be a duration")

            travel.FlightMemory()[94] = nil

            CN_TEST_SetMapSpan(spanBefore)

            print("  " .. hopDetail.hops .. " hops through the flight network, "
                .. "and the legs add up to the flight")
        end

        ------------------------------------------------------------
        -- AND NO FLIGHT POINT MAY BE CUT OFF FROM THE REST.
        --
        -- The edge list is inferred, so a rule that only connected nodes
        -- within a fixed radius would strand every isolated outpost -- it
        -- would drop out of the graph, out of every route, and out of the
        -- addon's answers, silently. `minimumNeighbours` exists to prevent
        -- exactly that, and this is the property it is there for.
        ------------------------------------------------------------
        do
            local spanBefore = CN_TEST_MAP_SPAN

            CN_TEST_SetMapSpan({ 90000, 90000 })

            local scattered = {}

            for index = 1, 24 do
                table.insert(scattered, {
                    nodeID = 600 + index,
                    name   = "Scattered " .. index,
                    state  = 1,
                    position = {
                        x = 0.03 + (((index * 5) % 17) * 0.055),
                        y = 0.03 + (((index * 3) % 13) * 0.072),
                    },
                })
            end

            -- One deliberately far from everything else.
            table.insert(scattered, {
                nodeID = 699, name = "Lone Outpost", state = 1,
                position = { x = 0.99, y = 0.99 },
            })

            CN_TEST_TAXI_NODES[1941] = scattered

            travel.ForgetNodes()

            local list = travel.KnownNodes(94)

            assert(#list >= 20, "the connectivity case needs a spread "
                .. "continent, got " .. #list)

            local reach = NetworkDistances(list)

            local unreachable = 0

            for index = 1, #list do
                if not reach[1][index] then
                    unreachable = unreachable + 1
                end
            end

            assert(unreachable == 0,
                unreachable .. " flight points have no route to them at all")

            CN_TEST_SetMapSpan(spanBefore)

            print("  every flight point on a spread continent is reachable "
                .. "from every other")
        end

        ------------------------------------------------------------
        -- THE WHOLE PROPERTY, SWEPT, WITH THE DISCOUNT LIVE.
        --
        -- The single hand-placed case above tests one geometry, and the
        -- brute-force case tests one more. Neither caught the bound ignoring
        -- knownRouteBonus, because whether that error changes an answer
        -- depends on the relationship between the zone's size, the flight
        -- overhead and where the flight points happen to sit -- three numbers
        -- a hand-written case fixes at one value each.
        --
        -- So sweep them. The property is simple and should hold everywhere:
        -- what the fast search returns is what an exhaustive one finds.
        ------------------------------------------------------------
        local sweepSpan = CN_TEST_MAP_SPAN

        local checked, ground = 0, 0

        for _, span in ipairs({ 200, 340, 600, 1000, 2400 }) do
            CN_TEST_SetMapSpan({ span, span })

            for _, fraction in ipairs({ 0.3, 0.5, 0.7, 0.85 }) do
                CN_TEST_TAXI_NODES[1941] = {
                    { nodeID = 80, name = "Out", state = 1,
                      position = { x = 0.05 + (0.90 * fraction),
                                   y = 0.05 + (0.90 * fraction) } },
                    { nodeID = 81, name = "In", state = 1,
                      position = { x = 0.95, y = 0.95 } },
                    { nodeID = 82, name = "Aside", state = 1,
                      position = { x = 0.95, y = 0.20 } },
                }

                travel.ForgetNodes()

                -- Every pair flown, so the discount is live on all of them.
                for _, pair in ipairs({ {80,81}, {81,80}, {80,82}, {82,81} }) do
                    travel.NoteRoute(pair[1], pair[2])
                end

                -- Grounded, so the pair search is what decides.
                travel.FlightMemory()[94] = false

                local list = travel.KnownNodes(94)

                local start  = travel.WorldPoint(94, 0.05, 0.05)
                local finish = travel.WorldPoint(94, 0.95, 0.95)

                local speed = travel.FlightSpeed()

                local expect = travel.YardsBetweenPoints(start, finish) / runSpeed

                local expectRanking = expect

                local sweepNetwork = NetworkDistances(list)

                for i, origin in ipairs(list) do
                    for j, arrival in ipairs(list) do
                        local through = (i ~= j) and sweepNetwork[i][j] or nil

                        if origin.id ~= arrival.id and through then
                            local total =
                                (travel.YardsBetweenPoints(start, origin.point) / runSpeed)
                                + travel.flightOverheadSeconds
                                + (through / speed)
                                + (travel.YardsBetweenPoints(finish, arrival.point) / runSpeed)

                            -- The discount RANKS; it does not shorten. So
                            -- the exhaustive comparison has to keep both
                            -- numbers, exactly as the search does.
                            local rankedTotal = total

                            if travel.IsKnownRoute(origin.id, arrival.id) then
                                rankedTotal = rankedTotal * travel.knownRouteBonus
                            end

                            if rankedTotal < expectRanking then
                                expectRanking = rankedTotal
                                expect        = total
                            end
                        end
                    end
                end

                local got, _, gotDetail = travel.EstimateSeconds(94, 0.05, 0.05, 94, 0.95, 0.95)

                assert(math.abs(got - expect) < 0.001,
                    "span " .. span .. ", flight point at " .. fraction
                    .. " of the way: the search returned "
                    .. string.format("%.3f", got) .. " where an exhaustive "
                    .. "one finds " .. string.format("%.3f", expect))

                checked = checked + 1

                if gotDetail and gotDetail.mode == "fly" then
                    ground = ground + 1
                end

                travel.FlightMemory()[94] = nil
            end
        end

        assert(ground >= 4,
            "the sweep must actually choose flight routes, or it is only "
            .. "checking that running is running; it chose " .. ground)

        CN_TEST_SetMapSpan(sweepSpan)

        print("  " .. checked .. " geometries swept, " .. ground
            .. " of them decided by the pair search")

        CN_TEST_TAXI_NODES[1941] = saved

        travel.ForgetNodes()

        assert(#travel.KnownNodes(94) == savedCount,
            "and the node list is forgotten with the spans that describe it")
    end

    ------------------------------------------------------------
    -- FLIGHT SPEED IS MEASURED, AND SAID TO BE UNMEASURED UNTIL IT IS.
    ------------------------------------------------------------
    CN.Account("flight").samples = {}

    local seeded, measured = travel.FlightSpeed()

    assert(seeded == travel.seededFlightSpeed and measured == false,
        "an unflown character has a seeded speed, flagged as unmeasured")

    assert(farConfident == false,
        "and an estimate built on it must not claim confidence")

    -- Now fly. The sample is taken when the flight ENDS, not per tick: a
    -- flight is one observation of a constant speed, and counting every tick
    -- would let one long flight drown out every other measurement.
    local savedX, savedY = CN_TEST_PLAYER_X, CN_TEST_PLAYER_Y

    CN_TEST_ON_TAXI = true
    CN_TEST_CLOCK   = 1000

    CN_TEST_MovePlayer(0.10, 0.50)

    travel.ObserveFlight()

    for step = 1, 20 do
        CN_TEST_CLOCK = 1000 + step
        -- 0.02 of a 4000 yard map per second = 80 yards/second.
        CN_TEST_PLAYER_X = 0.10 + (step * 0.02)

        travel.ObserveFlight()
    end

    assert(travel.FlightSampleCount() == 0,
        "nothing is recorded while still in the air")

    CN_TEST_ON_TAXI = false

    travel.ObserveFlight()

    assert(travel.FlightSampleCount() == 1,
        "one flight is one sample, got " .. travel.FlightSampleCount())

    local flown, nowMeasured = travel.FlightSpeed()

    assert(nowMeasured, "and the speed is now measured")
    assert(math.abs(flown - 80) < 5,
        "at about 80 yards per second, got " .. string.format("%.1f", flown))

    print(string.format("  flight speed measured from one flight: %.0f yd/s", flown))

    ------------------------------------------------------------
    -- ANOTHER CONTINENT IS "I DO NOT KNOW", NOT A LARGE NUMBER.
    ------------------------------------------------------------
    CN_TEST_CONTINENT_FOR_MAP = { [2112] = 99 }

    local offContinent, _, elsewhereDetail =
        travel.EstimateSeconds(94, 0.4, 0.5, 2112, 0.5, 0.5)

    assert(offContinent == nil,
        "a journey the addon cannot model must return nothing")
    assert(elsewhereDetail and elsewhereDetail.mode == "elsewhere",
        "and must say why")

    CN_TEST_CONTINENT_FOR_MAP = nil

    print("  another continent returns nothing rather than a fabricated number")

    ------------------------------------------------------------
    -- A FAILED CONVERSION MUST NOT BE REMEMBERED.
    --
    -- During a loading screen the client refuses every conversion. Caching
    -- that refusal would leave the addon unable to cost any journey for the
    -- rest of the session, and nothing would ever tell the player why.
    ------------------------------------------------------------
    travel.ForgetWorldPoints()

    local realConvert = C_Map.GetWorldPosFromMapPos

    C_Map.GetWorldPosFromMapPos = function() return nil, nil end

    assert(travel.WorldPoint(94, 0.3, 0.3) == nil,
        "a client that will not convert yields nothing")

    C_Map.GetWorldPosFromMapPos = realConvert

    assert(travel.WorldPoint(94, 0.3, 0.3) ~= nil,
        "and the question must be asked again once it can answer")

    print("  a refused conversion is not remembered as an answer")

    ------------------------------------------------------------
    -- AND THE SESSION PLANNER MUST ACTUALLY SPEND THE TRAVEL TIME.
    --
    -- The plan exists to answer "what fits in half an hour". A planner that
    -- costs the work and not the journey answers a different question, and
    -- flatters itself doing it.
    ------------------------------------------------------------
    local durations = CN.Account("taskDurations")

    local QUEST = CN.objectiveTypes.QUEST

    local savedDurations = durations[QUEST]

    durations[QUEST] = {}

    for _ = 1, 20 do
        table.insert(durations[QUEST], 60)
    end

    local hub = {
        mapID = 94, x = 0.90, y = 0.50,
        objectives = { { type = QUEST, id = 1 } },
    }

    local total, _, travelPart, workPart =
        session.EstimateHub(hub, 0.40, 0.50)

    assert(workPart and math.abs(workPart - 60) < 1,
        "the work is one timed quest")
    assert(travelPart and travelPart > 30,
        "and the journey across the zone must cost something, got "
        .. tostring(travelPart))
    assert(math.abs(total - (travelPart + workPart)) < 1,
        "the estimate is the sum of both")

    print(string.format("  the planner spends %.0fs travelling and %.0fs working",
        travelPart, workPart))

    durations[QUEST] = savedDurations

    CN_TEST_ON_TAXI = false
    CN_TEST_MovePlayer(savedX, savedY)
    CN_TEST_SetMapSpan(savedSpan)
    nav.ForgetMapScales()
    travel.ForgetNodes()
end)()

print("\nHow long a chase will take:")

;(function()
    local chase = CN:GetModule("Chase")
    local session = CN:GetModule("Session")

    local QUEST = CN.objectiveTypes.QUEST

    ------------------------------------------------------------
    -- NOT ENOUGH TIMED STEPS MEANS NO NUMBER.
    --
    -- Half an answer stated confidently is worse than "not enough to say".
    ------------------------------------------------------------
    local durations = CN.Account("taskDurations")

    durations[QUEST] = nil

    local chain = {
        name  = "Test Goal",
        type  = QUEST,
        steps = {
            { state = chase.states.TODO, text = "one", objectiveType = QUEST },
            { state = chase.states.TODO, text = "two", objectiveType = QUEST },
            { state = chase.states.DONE, text = "done", objectiveType = QUEST },
            { state = chase.states.NOTE, text = "context" },
        },
    }

    local blind = chase.Estimate(chain)

    assert(blind and blind.enough == false,
        "an untimed chain must refuse to estimate")
    assert(blind.unknown == 2, "and must count what it could not time, got "
        .. tostring(blind.unknown))

    local text = chase.DescribeEstimate(chain)

    assert(text:find("unknown"), "and must say so: " .. text)

    -- DONE AND NOTE STEPS ARE NOT WORK. Counting them would inflate every
    -- estimate by everything the player has already finished.
    assert(blind.timed + blind.unknown == 2,
        "finished steps and notes are not outstanding work")

    print("  an untimed chain says 'unknown' rather than guessing")

    ------------------------------------------------------------
    -- WITH DATA, A RANGE -- NEVER A FIGURE.
    ------------------------------------------------------------
    durations[QUEST] = {}

    for _ = 1, 20 do
        table.insert(durations[QUEST], 600)
    end

    local typical = session.TypicalSeconds(QUEST)

    assert(typical == 600, "the fixture must be timed, got " .. tostring(typical))

    local estimate = chase.Estimate(chain)

    assert(estimate.enough, "with data it must estimate")
    assert(math.abs(estimate.seconds - 1200) < 60,
        "two ten-minute steps is twenty minutes, got "
        .. string.format("%.0f", estimate.seconds))

    assert(estimate.low < estimate.seconds and estimate.high > estimate.seconds,
        "the answer must be a range")

    local described = chase.DescribeEstimate(chain)

    assert(described:find("to"), "and must be printed as one: " .. described)

    print("  " .. described)

    durations[QUEST] = nil
end)()


print("\nSituation awareness:")

;(function()
    local group = CN:GetModule("Group")

    assert(group, "the Group module must load")

    ------------------------------------------------------------
    -- BEING DEAD CHANGES THE ANSWER.
    --
    -- Recommending a battle pet to a corpse is the clearest possible signal
    -- that an addon is not watching what the player is doing.
    ------------------------------------------------------------
    CN_TEST_DEAD = false

    local objective = { type = CN.objectiveTypes.PET, id = 1,
        completionValue = 10, travelCost = 0, reasons = {} }

    local alive = CN.ScoreObjective(objective)

    CN_TEST_DEAD = true

    CN.InvalidateRanking()

    local dead = { type = CN.objectiveTypes.PET, id = 1,
        completionValue = 10, travelCost = 0, reasons = {} }

    local deadScore = CN.ScoreObjective(dead)

    assert(deadScore < alive,
        "everything is worth less than getting up: "
        .. string.format("%.2f dead vs %.2f alive", deadScore, alive))

    assert(deadScore > 0,
        "but not zero -- the list still answers 'what next', it just stops "
        .. "pretending you can act on it this second")

    local explainedDeath = false

    for _, reason in ipairs(CN.Reasons(dead)) do
        if reason:find("dead") then explainedDeath = true end
    end

    assert(explainedDeath, "and the line must say why it moved")

    local notice = group.Notice()

    assert(notice and notice:find("dead"),
        "and the recommendation must lead with it: " .. tostring(notice))

    print("  a dead player is told to get up first")

    ------------------------------------------------------------
    -- IN AN INSTANCE WITH A GROUP, OUTSIDE WORK RANKS DOWN.
    ------------------------------------------------------------
    CN_TEST_DEAD = false
    CN_TEST_INSTANCE = "party"
    CN_TEST_GROUP_SIZE = 5

    CN.InvalidateRanking()

    assert(group.Situation() == "instanced", "the situation must be read")

    local inside = { type = CN.objectiveTypes.PET, id = 1,
        completionValue = 10, travelCost = 0, reasons = {} }

    local insideScore = CN.ScoreObjective(inside)

    assert(insideScore < alive, "a pet detour ranks below its solo value")

    local quest = { type = CN.objectiveTypes.QUEST, id = 1,
        completionValue = 10, travelCost = 0, reasons = {} }

    local questScore = CN.ScoreObjective(quest)

    assert(questScore > insideScore,
        "but only the outside-work types are pushed down")

    CN_TEST_INSTANCE = nil
    CN_TEST_GROUP_SIZE = 1
    CN.InvalidateRanking()

    print("  outside work ranks down in an instance, and only outside work")
end)()

print("\nContributed chains:")

;(function()
    local contribute = CN:GetModule("Contribute")

    assert(contribute, "the Contribute module must load")

    ------------------------------------------------------------
    -- A MALFORMED IMPORT IS REFUSED OUTRIGHT.
    --
    -- A half-parsed contribution is worse than a refused one: it silently
    -- teaches the addon a chain nobody wrote.
    ------------------------------------------------------------
    local rejects = {
        "",
        "hello",
        "CN2 100:99",
        "CN1",
        "CN1 100",
        "CN1 100:",
        "CN1 abc:99",
    }

    for _, bad in ipairs(rejects) do
        local parsed, err = contribute.Parse(bad)

        assert(parsed == nil,
            "must refuse: '" .. bad .. "'")
        assert(err, "and say why")
    end

    ------------------------------------------------------------
    -- A GOOD ONE ROUND-TRIPS.
    ------------------------------------------------------------
    local parsed, err, entries = contribute.Parse("CN1 100:98,99 200:150")

    assert(parsed, "a well-formed export must parse: " .. tostring(err))
    assert(entries == 2, "two entries, got " .. tostring(entries))
    assert(#parsed[100] == 2 and parsed[100][1] == 98,
        "with their prerequisites intact")

    local ok, importErr, imported = contribute.Import("CN1 100:98,99 200:150")

    assert(ok, "and import: " .. tostring(importErr))
    assert(imported == 2, "both of them")

    -- AS OBSERVATIONS, NEVER AS CURATED FACT. A stranger's addon watching an
    -- ordering is the weakest of the three sources the addon has.
    local imported100 = CN.GetDependency(CN.ObjectiveKey("QUEST", 100))

    assert(imported100 and imported100.observedRequires,
        "an imported chain is published as an observation")
    assert(imported100.requires == nil,
        "and must never be able to present itself as curated data")

    ------------------------------------------------------------
    -- AND `/cn why` MUST SAY WHERE THE CHAIN CAME FROM.
    --
    -- The import command promises exactly that, and it was not true: an
    -- imported edge was indistinguishable from a locally observed one, so the
    -- eligibility checker formatted it as "seen first on N characters" with N
    -- read from the harvest store -- which has no record of an imported quest
    -- and therefore answered zero. The player was told the addon had watched
    -- the ordering hold on ZERO characters.
    ------------------------------------------------------------
    assert(imported100.origin == "contributed",
        "an imported edge must carry where it came from")

    -- Drive it through the eligibility checker, which is what `/cn why`
    -- prints, rather than asserting on the field alone.
    local checker = CN.eligibilityCheckers
        and CN.eligibilityCheckers[CN.objectiveTypes.QUEST]

    if checker then
        local _, _, detail = checker(100)

        assert(detail == nil or not detail:find("0 characters"),
            "a chain nobody here observed must not be reported as observed "
            .. "on zero characters: " .. tostring(detail))

        if detail then
            assert(detail:find("imported"),
                "it must say the chain was imported: " .. detail)
        end
    end

    ------------------------------------------------------------
    -- AND WHAT THIS ACCOUNT HAS LEARNED MUST BE EXPORTABLE.
    --
    -- The other half of the feature. `Build` reads the harvest store and
    -- produces the one line a player is asked to paste; nothing had ever run
    -- it, so the format it emits had never been checked against the parser
    -- that has to read it back.
    ------------------------------------------------------------
    local contributeHarvest = CN:GetModule("Harvest")

    local store = contributeHarvest.Store()

    store[900001] = {
        observed = {
            [900010] = { seen = 9, characters = { a = true, b = true, c = true } },
        },
    }

    local export, buildErr, chains = contribute.Build()

    if export then
        assert(chains and chains > 0, "something must be exportable")

        assert(export:find("^" .. contribute.formatVersion),
            "the export must be stamped with its format version")

        -- The parser and the writer are two halves of one format, and the
        -- only way to know they agree is to hand one the other's output.
        local roundTrip, roundErr = contribute.Parse(export)

        assert(roundTrip,
            "what Build writes, Parse must read: " .. tostring(roundErr))
    else
        assert(buildErr, "and when there is nothing to share it says why")
    end

    store[900001] = nil

    CN.HandleSlashCommand("contribute")

    assert(contribute.Forget() >= 2, "and it can all be thrown away")

    print("  malformed imports refused, good ones land as observations, and "
        .. "the export round-trips")
end)()

print("\nOne grammar for uncertainty:")

;(function()
    ------------------------------------------------------------
    -- An estimated number must be visibly different from a measured one.
    -- Three hedging styles taught readers to ignore all three.
    ------------------------------------------------------------
    local measured  = CN.WithConfidence("14 min", CN.confidence.MEASURED)
    local estimated = CN.WithConfidence("14 min", CN.confidence.ESTIMATED)
    local unknown   = CN.WithConfidence("14 min", CN.confidence.UNKNOWN)

    assert(measured == "14 min", "a measured number is printed plain")

    assert(estimated ~= measured,
        "an estimate must not look identical to a measurement")
    assert(estimated:find("estimated"), "and must say the word")

    assert(not unknown:find("14"),
        "and an unknown must not print the number at all, got " .. unknown)

    assert(CN.ConfidenceFor(true) == CN.confidence.MEASURED)
    assert(CN.ConfidenceFor(false) == CN.confidence.ESTIMATED)

    print("  measured, estimated and unknown are three visibly different things")
end)()


print("\nErrors are kept where the player can find them:")

;(function()
    local errors = CN:GetModule("Errors")

    assert(errors, "the Errors module must load")

    errors.Clear()

    ------------------------------------------------------------
    -- A CAUGHT ERROR THAT NOBODY RECORDS IS AN ERROR NOBODY KNOWS ABOUT.
    ------------------------------------------------------------
    local ok, message = errors.Guard("a failing thing", function()
        error("something broke")
    end)

    assert(ok == false, "Guard returns what pcall returns")
    assert(tostring(message):find("something broke"), "including the message")

    assert(errors.Count() == 1, "and records it")

    ------------------------------------------------------------
    -- REPEATS ARE COUNTED, NOT LISTED.
    --
    -- A failure inside a ticker fires ten times a second. Twenty identical
    -- lines is not twenty pieces of evidence, and it pushes out the one
    -- different error that would have explained the whole thing.
    ------------------------------------------------------------
    -- Recorded directly rather than through Guard: error() prefixes the
    -- message with its own file and line, so two calls from two lines produce
    -- two genuinely different messages -- which is correct, and which the
    -- first version of this assertion mistook for a deduplication failure.
    for _ = 1, 50 do
        errors.Record("a ticker", "the same failure every tick")
    end

    assert(errors.Count() == 2,
        "fifty identical failures collapse to one entry, alongside the "
        .. "earlier distinct one -- got " .. errors.Count())

    local repeated

    for _, entry in ipairs(errors.All()) do
        if entry.context == "a ticker" then repeated = entry end
    end

    assert(repeated and repeated.count == 50,
        "with a count, got " .. tostring(repeated and repeated.count))

    ------------------------------------------------------------
    -- AND THE BUFFER IS BOUNDED.
    ------------------------------------------------------------
    for index = 1, errors.capacity + 10 do
        errors.Record("context " .. index, "distinct failure " .. index)
    end

    assert(errors.Count() == errors.capacity,
        "the ring is capped at " .. errors.capacity
        .. ", got " .. errors.Count())

    local oldest = errors.All()[1]

    assert(not oldest.message:find("something broke"),
        "and the oldest entries are the ones dropped")

    assert(errors.Clear() == errors.capacity, "clearing reports what it threw away")
    assert(errors.Count() == 0, "and empties it")

    -- A successful call must record nothing at all.
    local fine = errors.Guard("fine", function() return 42 end)

    assert(fine == true, "a successful guard succeeds")
    assert(errors.Count() == 0, "and records nothing")

    ------------------------------------------------------------
    -- AND THE GUARD MUST NOT CHANGE THE ARITY OF WHAT IT WRAPS.
    --
    -- `{ pcall(fn, ...) }` measured with `#` truncates at the first nil, so a
    -- wrapped function returning `value, nil` came back as one value. `#` on
    -- a table with holes is undefined in both interpreters; they happen to
    -- agree on the cases here, which is the kind of agreement this project
    -- has learned not to rest on.
    ------------------------------------------------------------
    local gotToy, first, second, third =
        errors.Guard("arity", function() return "a", nil, "c" end)

    assert(gotToy == true, "the guard still reports success first")
    assert(first == "a" and second == nil and third == "c",
        "and every return survives, holes included: got "
        .. tostring(first) .. ", " .. tostring(second) .. ", "
        .. tostring(third))

    local trailing = { errors.Guard("trailing",
        function() return "value", nil end) }

    assert(trailing[1] == true and trailing[2] == "value",
        "a trailing nil must not swallow the value in front of it")

    ------------------------------------------------------------
    -- AND `/cn errors` MUST PRINT WHAT IT HOLDS.
    --
    -- The command is what the bug template asks people to paste, and every
    -- branch of it -- this session, the previous one, the events the client
    -- refused -- was unexecuted.
    ------------------------------------------------------------
    errors.Clear()
    errors.ForgetPrevious()

    -- Nothing at all.
    local quietAt = #output

    CN.HandleSlashCommand("errors")

    local saidQuiet = false

    for index = quietAt + 1, #output do
        if output[index]:find("Nothing has gone wrong") then saidQuiet = true end
    end

    assert(saidQuiet, "with nothing recorded, it says so")

    -- This session.
    errors.Record("a failing provider", "it exploded")

    local liveAt = #output

    CN.HandleSlashCommand("errors")

    local named = false

    for index = liveAt + 1, #output do
        if output[index]:find("a failing provider") then named = true end
    end

    assert(named, "and it names what failed")

    -- The previous session, shown once and then forgotten.
    errors.Persist()
    errors.Clear()

    local previousAt = #output

    CN.HandleSlashCommand("errors")

    local fromLast = false

    for index = previousAt + 1, #output do
        if output[index]:find("From the previous one") then fromLast = true end
    end

    assert(fromLast, "the previous session's record is offered")

    assert(#errors.Previous() == 0,
        "and shown once, then forgotten -- otherwise it follows the player "
        .. "around forever")

    -- Events the client refused, which is the failure most likely to be
    -- mistaken for "there is just nothing to do".
    CN.rejectedEvents["MADE_UP_EVENT"] = "no such event"

    local refusedAt = #output

    CN.HandleSlashCommand("errors")

    local sawRefusal = false

    for index = refusedAt + 1, #output do
        if output[index]:find("MADE_UP_EVENT") then sawRefusal = true end
    end

    assert(sawRefusal,
        "an event the client refused must be named: a handler that never "
        .. "runs is silent in every other way")

    CN.rejectedEvents["MADE_UP_EVENT"] = nil

    CN.HandleSlashCommand("errors clear")

    print("  caught, deduplicated, bounded, clearable, and printed")
end)()

print("\nThe things that make it legible:")

;(function()
    local hud = CN:GetModule("Hud")

    assert(hud, "the Hud module must load")

    ------------------------------------------------------------
    -- NO INFORMATION CARRIED BY COLOUR ALONE.
    ------------------------------------------------------------
    assert(hud.BearingWord(0) == "ahead", "straight on")
    assert(hud.BearingWord(math.pi) == "back", "and a reversal")
    assert(hud.BearingWord(nil) == "?", "and an unknown bearing is not a claim")

    local words = {}

    for _, radians in ipairs({ 0, 0.8, 1.6, 3.0 }) do
        words[hud.BearingWord(radians)] = true
    end

    local distinct = 0

    for _ in pairs(words) do distinct = distinct + 1 end

    assert(distinct == 4,
        "four bearings must produce four different words, got " .. distinct)

    ------------------------------------------------------------
    -- THE SCALE IS BOUNDED, because a scale of 0.01 is an addon the player
    -- can no longer read well enough to fix.
    ------------------------------------------------------------
    local hudSettings = CN.Settings()

    hudSettings.uiScale = 50

    assert(hud.Scale() == 1, "an absurd scale falls back to 1")

    hudSettings.uiScale = 1.25

    assert(hud.Scale() == 1.25, "a sensible one is kept")

    hudSettings.uiScale = nil

    ------------------------------------------------------------
    -- OFF BY DEFAULT. Everything that puts pixels on screen uninvited is.
    ------------------------------------------------------------
    assert(hud.IsEnabled() == false, "the heads-up line is off by default")
    assert(hud.IsColourblind() == false, "and so is the word mode")

    print("  four distinct bearing words, a bounded scale, both off by default")
end)()

