;(function()
    ------------------------------------------------------------
    -- FINDING A CANDIDATE IS AN INDEX, NOT A WALK.
    ------------------------------------------------------------
    -- `CN.FindCandidate` is called from the item tooltip on every mount, pet
    -- and toy the player hovers, and once per step of every chase chain, and
    -- it walked the whole candidate list each time. The same shape was
    -- removed from the pet tooltip path in 0.87.0 and the recipe tooltip path
    -- in 0.86.0.
    local allRows = CN.CollectCandidates() or {}

    assert(#allRows > 0, "the fixture must produce candidates")

    -- IT STILL ANSWERS THE SAME, ROW FOR ROW, INCLUDING FIRST-MATCH-WINS.
    for _, objective in ipairs(allRows) do
        local found = CN.FindCandidate(objective.type, objective.id)

        assert(found,
            "every candidate is findable by its own pair: "
            .. tostring(objective.type) .. " / " .. tostring(objective.id))

        local walked

        for _, row in ipairs(allRows) do
            if row.type == objective.type and row.id == objective.id then
                walked = row
                break
            end
        end

        assert(found == walked,
            "and the index returns the row the walk returned: "
            .. tostring(objective.name))
    end

    assert(CN.FindCandidate(CN.objectiveTypes.QUEST, 970404) == nil,
        "and something that is not a candidate is still not found")

    -- AND IT IS BUILT ONCE, not once per lookup.
    local source = CN_TEST_ReadAddonFile("Scoring.lua")

    assert(source and source:find('CN.Memo("CandidateIndex"', 1, true),
        "the index is memoised rather than rebuilt per call")

    -- THE KEY MOVES WHEN THE LIST DOES. A row added by a rebuild has to be
    -- findable, which a memo keyed on something that does not move would not
    -- manage -- the 0.87.0 defect, in the other direction.
    CN.InvalidateCandidates()

    local rebuilt = CN.CollectCandidates() or {}

    for _, objective in ipairs(rebuilt) do
        assert(CN.FindCandidate(objective.type, objective.id),
            "a candidate present after a rebuild is found after it: "
            .. tostring(objective.name))
    end

    print("  finding a candidate is an index, not a walk")
end)()


;(function()
    ------------------------------------------------------------
    -- THE SAVED SCALE REACHES EVERY FRAME THE ADDON DRAWS.
    ------------------------------------------------------------
    -- `Hud.ApplyScale` is the only thing that scales the addon's five named
    -- frames, and it runs at login, from `/cn scale`, and from
    -- `UI.BuildWindow`. Three of the five -- the arrow, the follow frame and
    -- the welcome screen -- are built LAZILY, so at login `_G[name]` is nil
    -- for all three and the saved scale never reached them. `Hud.Build` and
    -- `UI.BuildWindow` each end by applying it; the fix landed on two of five.
    --
    -- A player who set `/cn scale 1.5` got the window and the heads-up line
    -- at 1.5 and the ARROW at 1.0, on every login, for the whole session.
    local hud = CN:GetModule("Hud")

    assert(hud and hud.SetScale, "the scale setting exists")

    hud.SetScale(1.4)

    local builders = {
        CompletionNavigatorArrow   = function()
            return CN:GetModule("Navigation").BuildArrow()
        end,
        CompletionNavigatorFollow  = function()
            return CN:GetModule("Follow").BuildFrame()
        end,
        CompletionNavigatorWelcome = function()
            return CN:GetModule("Welcome").Build()
        end,
        CompletionNavigatorHud     = function() return hud.Build() end,
    }

    for name, build in pairs(builders) do
        _G[name] = nil

        local made = build()

        assert(made, name .. " builds")

        assert(math.abs((made:GetScale() or 1) - 1.4) < 0.001,
            name .. " is built at the scale the player chose, got "
            .. tostring(made:GetScale()))
    end

    -- AND EVERY FRAME `ApplyScale` KNOWS ABOUT HAS A BUILDER THAT APPLIES IT.
    -- A sixth frame added later must not repeat this.
    local hudSource = CN_TEST_ReadAddonFile("Modules/Hud.lua")

    local named = 0

    for name in string.gmatch(hudSource, '"(CompletionNavigator%w*)"') do
        if name ~= "CompletionNavigatorFrame" then
            named = named + 1

            assert(builders[name],
                "every frame ApplyScale scales is built at that scale: "
                .. name)
        end
    end

    assert(named >= 4, "the list was found: " .. tostring(named))

    -- THE BUILDERS THEMSELVES, because a frame is built once per session and
    -- the harness cannot un-build one: by the time this runs the login sweep
    -- has already made them, so the assertion above would hold even if the
    -- builder did nothing. The defect was in the BUILD path, so that is what
    -- is checked.
    --
    -- The window and the heads-up line have applied it since 0.85.0 and
    -- 0.84.0; these three are the ones the fix missed.
    for _, file in ipairs({ "Modules/Navigation.lua", "Modules/Follow.lua",
                            "Modules/Welcome.lua" }) do
        local text = CN_TEST_ReadAddonFile(file)

        assert(text and text:find("hudModule.ApplyScale()", 1, true),
            file .. " applies the saved scale to the frame it builds")
    end

    -- And through the one writer, not a fourth hand-written copy of the
    -- screen-height clamp 0.85.0 added.
    for _, file in ipairs({ "Modules/Navigation.lua", "Modules/Follow.lua",
                            "Modules/Welcome.lua" }) do
        local text = CN_TEST_ReadAddonFile(file)

        assert(not text:find("SetScale(hud", 1, true)
            and not text:find(":SetScale(Hud.Scale", 1, true),
            file .. " does not keep its own copy of the scaling rule")
    end

    hud.SetScale(1)

    print("  the saved scale reaches every frame the addon draws")
end)()

;(function()
    ------------------------------------------------------------
    -- /cn navdiag DOES NOT PRINT A SHRUG AS A MEASUREMENT.
    ------------------------------------------------------------
    -- `Navigation.MapScale` returns `1, 1, false` on both refusal paths and
    -- its own header says "callers that want yards must check it". Routing
    -- checks it, Capture checks it and quotes the header while doing so, and
    -- the diagnostic command -- in the file that owns the function -- did
    -- not. So during a loading screen or in an instance, which is exactly
    -- when somebody runs a diagnostic, it reported "map scale 1 x 1 yards
    -- across" as an observation.
    local navigation = CN:GetModule("Navigation")

    local realScale = navigation.MapScale

    navigation.MapScale = function() return 1, 1, false end

    local spoken = {}

    local realAdd = DEFAULT_CHAT_FRAME.AddMessage

    DEFAULT_CHAT_FRAME.AddMessage = function(self, message)
        table.insert(spoken, tostring(message))
    end

    CN.HandleSlashCommand("navdiag")

    DEFAULT_CHAT_FRAME.AddMessage = realAdd

    navigation.MapScale = realScale

    local text = table.concat(spoken, "\n")

    assert(not text:find("1 x 1 yards", 1, true),
        "an unmeasured map scale is not printed as a number:\n" .. text)

    assert(text:find("would not convert", 1, true),
        "it says the client would not answer instead:\n" .. text)

    -- And a real measurement is still printed.
    spoken = {}

    navigation.MapScale = function() return 3000, 2000, true end

    DEFAULT_CHAT_FRAME.AddMessage = function(self, message)
        table.insert(spoken, tostring(message))
    end

    CN.HandleSlashCommand("navdiag")

    DEFAULT_CHAT_FRAME.AddMessage = realAdd

    navigation.MapScale = realScale

    assert(table.concat(spoken, "\n"):find("3000 x 2000 yards", 1, true),
        "a measured one still is:\n" .. table.concat(spoken, "\n"))

    print("  /cn navdiag does not print a shrug as a measurement")
end)()

;(function()
    ------------------------------------------------------------
    -- A LARGER TEXT SIZE RE-MEASURES WHAT WAS SIZED FROM THE TEXT.
    ------------------------------------------------------------
    -- Re-applying a font object changes what is drawn and nothing that was
    -- MEASURED from it. The eleven tab buttons are sized from the rendered
    -- width of their caption, and the list rows sit on a fixed 20-pixel
    -- pitch under a 12pt font the same setting grows to 24pt.
    --
    -- The harness could not see either, because `GetTextWidth` answered a
    -- flat 60 for every caption at every size -- the twentieth defect in this
    -- project hidden by a stub simpler than the client.
    local ui = CN.UI

    local window = ui.BuildWindow()

    assert(window and window.tabButtons and #window.tabButtons > 0,
        "the window and its tab strip build")

    CN.SetTextScale(1)

    ui.RebuildTabs()

    local narrow = {}

    for index, button in ipairs(window.tabButtons) do
        narrow[index] = button:GetWidth()
    end

    CN.SetTextScale(1.5)

    local grew = 0

    for index, button in ipairs(window.tabButtons) do
        local width = button:GetWidth()

        assert(width >= (narrow[index] or 0),
            "a tab button never shrinks when its caption grows: "
            .. tostring(narrow[index]) .. " -> " .. tostring(width))

        if width > (narrow[index] or 0) then
            grew = grew + 1
        end
    end

    assert(grew > 0,
        "the strip is re-measured when the text size changes, not only when "
        .. "a tab is registered")

    -- AND THE ROWS MOVE APART, so a 21pt line is not drawn on a 20px pitch.
    assert(ui.RowPitch and ui.RowPitch() > 20,
        "the row pitch follows the text size: " .. tostring(ui.RowPitch()))

    CN.SetTextScale(1)

    assert(ui.RowPitch() == 20,
        "and comes back: " .. tostring(ui.RowPitch()))

    ui.RebuildTabs()

    print("  a larger text size re-measures what was sized from the text")
end)()

;(function()
    ------------------------------------------------------------
    -- THE SORT CAPTION IS NOT DRAWN ON THE FIRST ROW.
    ------------------------------------------------------------
    -- The caption is anchored inside the list under a comment claiming "the
    -- first row starts below the scroll frame's own inset". There was no
    -- inset, so a 14-tall caption at y=+3 covered the top eleven pixels of
    -- the first 20-pixel row, in the x-range holding that row's chevron and
    -- the right end of its value column -- and it is deliberately four frame
    -- levels above the rows, so it won. Every tab whose first row carries a
    -- number showed it.
    local source = CN_TEST_ReadAddonFile("UI/List.lua")

    assert(source and source:find('scroll:SetPoint("TOPLEFT", 0, -CaptionHeight())',
            1, true),
        "the scroll frame reserves the band the caption sits in")

    assert(not source:find('sortButton:SetPoint("TOPRIGHT", list, "TOPRIGHT", -28, 3)',
            1, true),
        "and the caption no longer hangs three pixels into the rows")

    -- The band grows with the text, or the caption outgrows its own gap.
    CN.SetTextScale(1)

    local panel = CN.UI and CN.UI.listPanels and next(CN.UI.listPanels)

    if panel then
        local list = CN.UI.listPanels[panel]

        local narrow = list.sortButton and list.sortButton:GetHeight()

        CN.SetTextScale(1.5)

        local wide = list.sortButton and list.sortButton:GetHeight()

        assert(narrow and wide and wide > narrow,
            "the caption band grows with the caption: " .. tostring(narrow)
            .. " -> " .. tostring(wide))

        CN.SetTextScale(1)
    end

    print("  the sort caption is not drawn on the first row")
end)()

;(function()
    ------------------------------------------------------------
    -- THE MAP ROUTE IS ORDERED FROM WHERE YOU ARE NOW.
    ------------------------------------------------------------
    -- The pin cache was keyed on the candidate generation and the type
    -- filter, and neither moves when the player walks -- nor does anything
    -- else invalidate on movement. So: open the map at one end of a zone, run
    -- to the other end, open it again, and the numbered stops were still
    -- ordered from where you were standing the first time, for the rest of
    -- the session. Route order is the entire content of this feature.
    local pins = CN:GetModule("MapPins")

    pins.InvalidateCache()

    local realPosition = CN.GetPlayerPosition

    local at = { 94, 0.10, 0.10 }

    CN.GetPlayerPosition = function() return at[1], at[2], at[3] end

    local asked = {}

    local realRoute = CN.BuildZoneRoute

    CN.BuildZoneRoute = function(mapID, startX, startY)
        table.insert(asked, tostring(startX) .. "," .. tostring(startY))

        return realRoute(mapID, startX, startY)
    end

    pins.HubsForMap(94)

    -- A pan, or a step: the cache must still answer, because rebuilding on
    -- every frame the map is open is the cost it exists to avoid.
    at[2], at[3] = 0.105, 0.105

    pins.HubsForMap(94)

    assert(#asked == 1,
        "a few yards does not rebuild the route: " .. tostring(#asked))

    -- The other end of the zone is a different route.
    at[2], at[3] = 0.90, 0.90

    pins.HubsForMap(94)

    assert(#asked == 2,
        "walking across the zone does: " .. tostring(#asked))

    CN.BuildZoneRoute    = realRoute
    CN.GetPlayerPosition = realPosition

    pins.InvalidateCache()

    print("  the map route is ordered from where you are now")
end)()

;(function()
    ------------------------------------------------------------
    -- /cn harvestnow COUNTS WHAT ITS SENTENCE CLAIMS.
    ------------------------------------------------------------
    -- `Harvest.Capture` returns whether anything CHANGED, and a field is
    -- written only when it was previously nil -- while the login hook already
    -- captures every entry in the log. So by the time a player could type
    -- this, nothing changed, and the command reported "Harvested 0 quests
    -- from the current log" immediately after harvesting every quest in it.
    local sweep = CN:GetModule("Harvest")

    for _, info in ipairs(CN.Blizzard.GetQuestLogEntries()) do
        sweep.Capture(info.questID, "login")
    end

    local spoken = {}

    local realAdd = DEFAULT_CHAT_FRAME.AddMessage

    DEFAULT_CHAT_FRAME.AddMessage = function(self, message)
        table.insert(spoken, tostring(message))
    end

    CN.HandleSlashCommand("harvestnow")

    DEFAULT_CHAT_FRAME.AddMessage = realAdd

    local text = table.concat(spoken, "\n")

    local entries = #CN.Blizzard.GetQuestLogEntries()

    assert(entries > 0, "the fixture must have quests in the log")

    assert(text:find(tostring(entries), 1, true),
        "the count is the number of quests it harvested (" .. entries
        .. "):\n" .. text)

    assert(not text:find("Harvested 0 ", 1, true),
        "and never zero after harvesting a full log:\n" .. text)

    print("  /cn harvestnow counts what its sentence claims")
end)()

;(function()
    ------------------------------------------------------------
    -- A SIGHTING COUNTER NOTHING READS IS NOT STORED.
    ------------------------------------------------------------
    -- One integer per (quest, prerequisite) pair, on a store capped at 2000
    -- rows, incremented on every quest accepted inside the five-minute window
    -- and read by nothing: `Harvest.Confidence` counts distinct CHARACTERS
    -- instead, deliberately.
    for _, record in pairs(CN.Account("questHarvest")) do
        if type(record) == "table" and type(record.observed) == "table" then
            for prerequisiteID, candidate in pairs(record.observed) do
                assert(type(candidate) ~= "table" or candidate.seen == nil,
                    "prerequisite " .. tostring(prerequisiteID)
                    .. " must not persist a sighting counter")
            end
        end
    end

    -- AND THE MIGRATION REMOVES ONE ALREADY ON DISK.
    local aged = {
        version = 34,
        account = {
            questHarvest = {
                [4242] = { observed = {
                    [1111] = { seen = 9, characters = { ["a"] = true } },
                } },
            },
        },
        characters = {},
    }

    CN.RunMigrations(aged)

    local row = aged.account.questHarvest[4242].observed[1111]

    assert(row.seen == nil,
        "the field is dropped from a database that already has it")

    assert(row.characters and row.characters["a"],
        "without taking the evidence with it")

    -- AND THE MIGRATION THAT SEEDED IT STOPS SEEDING IT. A database old
    -- enough to run migration 3 runs 34 afterwards, but a migration that puts
    -- back what a later one removes is a rule written twice.
    local database = CN_TEST_ReadAddonFile("Database.lua")

    assert(database and not database:find("seen = 1, characters", 1, true),
        "migration 3 does not seed a field migration 34 removes")

    print("  a sighting counter nothing reads is not stored")
end)()

;(function()
    ------------------------------------------------------------
    -- /cn alts DOES NOT INVENT A DATE FOR A CHARACTER WITHOUT ONE.
    ------------------------------------------------------------
    -- `Alts.AgeDays` returns nil when a record has no `lastSeen` and
    -- `DescribeAge` renders that as "never seen". The suggestion line rebuilt
    -- a record out of `ageDays`, and `or 0` turned "unknown" into `time()` --
    -- "today". `Alts.Assignments` admits a character on
    -- `not age or age <= staleDays`, so a record with no timestamp is exactly
    -- what arrives there.
    local alts = CN:GetModule("Alts")

    local key = "Undated-Testrealm"

    CN.db.characters[key] = {
        name  = "Undated",
        realm = "Testrealm",
        level = 80,
    }

    assert(alts.AgeDays(CN.db.characters[key]) == nil,
        "the fixture character has no timestamp")

    assert(alts.DescribeAge(CN.db.characters[key]):find("never", 1, true),
        "which the describer calls never seen: "
        .. alts.DescribeAge(CN.db.characters[key]))

    local spoken = {}

    local realAdd = DEFAULT_CHAT_FRAME.AddMessage

    DEFAULT_CHAT_FRAME.AddMessage = function(self, message)
        table.insert(spoken, tostring(message))
    end

    CN.HandleSlashCommand("alts")

    DEFAULT_CHAT_FRAME.AddMessage = realAdd

    local text = table.concat(spoken, "\n")

    if text:find("Undated", 1, true) then
        assert(not text:find("Undated|r %(80%) |cff8a8f96last played today"),
            "a character with no timestamp is never reported as played "
            .. "today:\n" .. text)
    end

    local source = CN_TEST_ReadAddonFile("Modules/Alts.lua")

    assert(source and not source:find("best.ageDays", 1, true),
        "the command reads the real record rather than rebuilding one out of "
        .. "an age in days, whose 'unknown' collapses to 'today'")

    CN.db.characters[key] = nil

    print("  /cn alts does not invent a date for a character without one")
end)()

;(function()
    ------------------------------------------------------------
    -- NO WINDOW LIST PADS A NUMBER WITH SPACES.
    ------------------------------------------------------------
    -- `%2d` puts a leading space in front of rows one to nine. WoW ships no
    -- monospace font -- a space is about three units against a digit's seven
    -- -- so the padding moved the periods further out of line rather than
    -- into it. The chat side has been swept for this three times; the window
    -- had two sites left.
    local offenders = {}

    for _, file in ipairs(CN_TEST_ADDON_FILES) do
        local text = CN_TEST_ReadAddonFile(file)

        if text then
            for line in string.gmatch(text, "[^\n]+") do
                if not string.find(line, "^%s*%-%-") then
                    for pad in string.gmatch(line, "%%%d+d") do
                        table.insert(offenders, file .. " uses " .. pad)
                    end
                end
            end
        end
    end

    assert(#offenders == 0,
        "a number is never padded to a column width:\n"
        .. table.concat(offenders, "\n"))

    print("  no window list pads a number with spaces")
end)()


;(function()
    ------------------------------------------------------------
    -- /cn capture DOES NOT RECORD FIVE APIS AS GONE FROM THE CLIENT.
    ------------------------------------------------------------
    -- `SelfTest.optionalApi` names five APIs this addon PROBES for and falls
    -- back from, and it exists because their absence made the first check in
    -- `/cn selftest` report FAIL on every Retail client, permanently. The fix
    -- landed in the self-test and nowhere else. This is the sibling call site
    -- over the same list.
    --
    -- The offline suite asserts that a real recording has no missing names,
    -- so the first genuine contribution would have hard-failed the build --
    -- and printed five "the client has no GetItemInfo" lines on the way.
    local capture = CN:GetModule("Capture")

    local selftest = CN:GetModule("SelfTest")

    assert(selftest and selftest.optionalApi,
        "the exemption list exists")

    local collect

    for _, definition in ipairs(CN.captures or {}) do
        if definition.name == "apiSurface" then
            collect = definition.run
        end
    end

    assert(collect, "the api surface capture is registered")

    local result = collect()

    assert(type(result) == "table",
        "the api surface capture answers")

    for path in pairs(selftest.optionalApi) do
        for _, missing in ipairs(result.missing or {}) do
            assert(missing ~= path,
                "an API this addon only probes for is not recorded as gone "
                .. "from the client: " .. path)
        end
    end

    assert(result.examined < #CN.apiSurface,
        "and the count reported is what was actually checked: "
        .. tostring(result.examined) .. " of " .. tostring(#CN.apiSurface))

    -- The two call sites read one list, so a sixth exemption cannot land in
    -- one and not the other.
    local source = CN_TEST_ReadAddonFile("Modules/Capture.lua")

    assert(source and source:find("selftest.optionalApi", 1, true),
        "the capture asks the self-test rather than keeping its own copy")

    print("  /cn capture honours the same API exemptions the self-test does")
end)()

;(function()
    ------------------------------------------------------------
    -- /cn breakdown DOES NOT CLAIM A COUNT IT NEVER COMPUTED.
    ------------------------------------------------------------
    -- The quests row said "N harvested with location data" where N was EVERY
    -- harvested row. Coordinates are written only when the client resolved a
    -- waypoint, which for a turned-in or off-map quest it does not --
    -- `Harvest.BuildExport`'s default mode exists because most rows have
    -- none. `Harvest.Summary` already returns the real figure.
    -- A ROW WITH NO COORDINATES, so the two numbers are demonstrably
    -- different. If every row in the fixture happened to be located, the
    -- assertion below would hold of the defect it exists for -- backlog rule
    -- 87, in the other direction.
    CN.Account("questHarvest")[970991] = { requires = { 1 } }

    local located = CN:GetModule("Harvest").Summary()

    assert(located and located.located ~= nil,
        "the harvester reports how many rows carry a location")

    local total = CN.CountKeys(CN.Account("questHarvest"))

    assert(located.located < total,
        "the fixture holds a harvested row with no coordinates: "
        .. tostring(located.located) .. " of " .. tostring(total))

    local breakdown = CN:GetModule("Breakdown")

    local sentence

    for _, category in ipairs(breakdown.categories or {}) do
        local ok, row = pcall(category.report)

        if ok and type(row) == "table" then
            for _, reason in ipairs(row.reasons or {}) do
                if reason:find("harvested", 1, true) then
                    sentence = reason
                end
            end
        end
    end

    assert(sentence, "the quests row still says something about harvesting")

    if located.located ~= total then
        assert(not sentence:find(tostring(total) .. " harvested with", 1, true),
            "and does not report the whole store as located: " .. sentence)
    end

    assert(sentence:find(tostring(located.located), 1, true),
        "it reports the number that was measured: " .. sentence)

    assert(not sentence:find(tostring(total), 1, true),
        "and not the size of the whole store: " .. sentence)

    CN.Account("questHarvest")[970991] = nil

    print("  /cn breakdown does not claim a count it never computed")
end)()

;(function()
    ------------------------------------------------------------
    -- A BREADCRUMB YOU HAVE WALKED PAST IS GONE.
    ------------------------------------------------------------
    -- `Data/Quests.lua` has documented `breadcrumb` -- "skippable and
    -- permanently missable" -- since 0.43.0, and `CN.blockReasons` has
    -- carried `BREADCRUMB_SKIPPED` just as long. Neither had a producer: the
    -- field had zero references in the tree, so a curator following the
    -- addon's own schema wrote something that reached nothing.
    --
    -- Sending a completionist to find a quest that is not there is the worst
    -- kind of wrong answer this addon can give.
    local Static = CN.Static

    Static.RegisterQuests({
        [88030] = { name = "Go and see the captain",
                    breadcrumb = true, unlocks = { 88031 } },
        [88031] = { name = "The captain's business" },
        [88032] = { name = "Untargeted breadcrumb", breadcrumb = true },
    }, "TestSupplier")

    local states = CN.objectiveStates

    -- The target is untouched: the breadcrumb is still there to take.
    local state = CN.Explain(CN.objectiveTypes.QUEST, 88030)

    assert(state ~= states.UNOBTAINABLE,
        "a breadcrumb whose target you have not started is available: "
        .. tostring(state))

    -- The target is in the log: the game has already removed the breadcrumb.
    -- The target is finished: the game removed the breadcrumb long ago.
    CN_TEST_COMPLETED[88031] = true

    local skipped, reason = CN.Explain(CN.objectiveTypes.QUEST, 88030)

    assert(skipped == states.UNOBTAINABLE,
        "a breadcrumb whose target you have started is gone, not available: "
        .. tostring(skipped))

    assert(reason == CN.blockReasons.BREADCRUMB_SKIPPED,
        "and says why in the token that has existed for it since 0.43.0: "
        .. tostring(reason))

    CN_TEST_COMPLETED[88031] = nil

    -- A breadcrumb with no known target is left alone rather than guessed at.
    assert(CN.Explain(CN.objectiveTypes.QUEST, 88032) ~= states.UNOBTAINABLE,
        "a breadcrumb with no `unlocks` is not assumed gone")

    -- AND EVERY FIELD THE DATA FILE DOCUMENTS REACHES SOMETHING.
    local header = CN_TEST_ReadAddonFile("Data/Quests.lua")

    local documented = {}

    for field in string.gmatch(header, "\n%-%-   (%w+)") do
        documented[field] = true
    end

    documented["x"] = nil
    documented["turnInX"] = nil
    documented["turnInY"] = nil

    for field in pairs(documented) do
        assert(CN.Static.validFields[field],
            "a field the data file's own header documents is one the addon "
            .. "reads: " .. field)
    end

    assert(documented.breadcrumb, "including the one this test is about")

    assert(documented.expansion == nil,
        "and `expansion`, which had no reader anywhere, is no longer offered "
        .. "to curators")

    -- A TEST THAT LEAVES THE WORLD CHANGED breaks a later one for a reason
    -- nobody can see from either of them -- and `bench.lua` runs this whole
    -- file before it measures anything, so a row left in the curated table
    -- is a row the benchmark walks on every collect.
    for _, id in ipairs({ 88030, 88031, 88032 }) do
        CN.Static.quests[id] = nil
    end

    print("  a breadcrumb you have walked past is gone")
end)()

;(function()
    ------------------------------------------------------------
    -- THE CURATED SWEEP IS A SHORTLIST, NOT A WALK OF THE DATABASE.
    ------------------------------------------------------------
    -- The Quests provider walked every curated row and called `CN.Explain` on
    -- each; `Explain` reaches `Quests.GetRecord`, which for a row without
    -- gating fields pcalls `IsAvailable` AND `GetQuestData` on every
    -- registered external addon. The provider declares `QUEST_LOG_UPDATE` at
    -- a two-second cooldown.
    --
    -- With one shipped row that cost nothing. With a few thousand curated
    -- rows and AllTheThings installed it is thousands of cross-addon lookups
    -- every two seconds while questing -- which is exactly what a companion
    -- data addon creates.
    local Static = CN.Static

    local builds = 0

    local realCompleted = CN.Blizzard.IsQuestCompletedByCharacter

    for id = 88100, 88140 do
        Static.RegisterQuest(id, { name = "Bulk " .. id }, "TestSupplier")
    end

    CN.ClearShortlist("Quests.Curated")

    CN.InvalidateCandidates()

    CN.candidateProviders["Quests"].fn()

    local _, revision = CN.ShortlistState("Quests.Curated")

    assert(revision, "the curated rows are held as a shortlist")

    CN.candidateProviders["Quests"].fn()

    local _, again = CN.ShortlistState("Quests.Curated")

    assert(again == revision,
        "which is not rebuilt when nothing has changed: "
        .. tostring(revision) .. " -> " .. tostring(again))

    -- REGISTERING A ROW LATE MOVES IT. A companion addon that registers on
    -- demand would otherwise leave the shortlist, the aggregate cache and the
    -- ranked list holding the pre-registration answer for the session.
    Static.RegisterQuests({ [88141] = { name = "Late arrival" } },
        "TestSupplier")

    CN.candidateProviders["Quests"].fn()

    local _, moved = CN.ShortlistState("Quests.Curated")

    assert(moved ~= revision,
        "a row registered after the list was built invalidates it: "
        .. tostring(revision) .. " -> " .. tostring(moved))

    -- AND THE RANKED LIST TOO, not only the shortlist. A companion addon
    -- registering on demand would otherwise leave the aggregate candidate
    -- cache and the ranked list holding the pre-registration answer for the
    -- whole session -- which is what `Contribute.Import` calls this for.
    local invalidated = 0

    local realInvalidate = CN.InvalidateCandidates

    -- The unlock index also invalidates, so it is silenced for the count --
    -- otherwise this assertion holds on a registrar that invalidates nothing
    -- itself, which is the defect it exists for.
    local unlockIndex = CN:GetModule("Harvest")

    local realUnlocks = unlockIndex.NoteUnlocksChanged

    unlockIndex.NoteUnlocksChanged = function() end

    CN.InvalidateCandidates = function(...)
        invalidated = invalidated + 1

        return realInvalidate(...)
    end

    Static.RegisterQuests({ [88142] = { name = "Later still" } },
        "TestSupplier")

    CN.InvalidateCandidates = realInvalidate
    unlockIndex.NoteUnlocksChanged = realUnlocks

    assert(invalidated > 0,
        "registering a row invalidates the aggregate rather than leaving the "
        .. "pre-registration answer in place for the session -- which is what "
        .. "`Contribute.Import` calls this for")

    -- AND NOT WHEN NOTHING LANDED, because a refused batch has changed no
    -- answer and throwing the caches away would be pure cost.
    invalidated = 0

    unlockIndex.NoteUnlocksChanged = function() end

    CN.InvalidateCandidates = function(...)
        invalidated = invalidated + 1

        return realInvalidate(...)
    end

    Static.RegisterQuests({ ["bad"] = { name = "Refused" } }, "TestSupplier")

    CN.InvalidateCandidates = realInvalidate
    unlockIndex.NoteUnlocksChanged = realUnlocks

    assert(invalidated == 0,
        "and a batch where nothing landed invalidates nothing")

    -- AND THE UNLOCK INDEX TOO. A curated row's `unlocks` feeds the index
    -- `Harvest` builds, so a supplier arriving after login leaves that index
    -- holding the pre-registration answer for the session -- the same defect
    -- as the candidate cache, in the other direction.
    local unlocksNoted = 0

    unlockIndex.NoteUnlocksChanged = function(...)
        unlocksNoted = unlocksNoted + 1

        return realUnlocks(...)
    end

    Static.RegisterQuests({ [88143] = { name = "Unlocking",
                                        unlocks = { 88144 } } },
        "TestSupplier")

    unlockIndex.NoteUnlocksChanged = realUnlocks

    assert(unlocksNoted > 0,
        "registering a row rebuilds the unlock index rather than leaving it "
        .. "holding what it had before the supplier loaded")

    Static.quests[88143] = nil

    -- AND SO DOES FINISHING ONE, through the one function that re-reads the
    -- completed set rather than at three of its seven call sites.
    local wasAt = CN:GetModule("Quests").completionRevision

    CN_TEST_COMPLETED[88100] = true

    CN:GetModule("Quests").RecordStatus(88100)

    assert(CN:GetModule("Quests").completionRevision > wasAt,
        "handing a quest in moves the revision the shortlist is keyed on")

    -- BUT AN IDEMPOTENT RE-READ DOES NOT. `Quests.ScanKnown` walks every
    -- discovered quest through the same function; a bump per read would
    -- destroy the cache at the worst possible moment.
    local settled = CN:GetModule("Quests").completionRevision

    CN:GetModule("Quests").RecordStatus(88100)
    CN:GetModule("Quests").RecordStatus(88100)

    assert(CN:GetModule("Quests").completionRevision == settled,
        "re-reading an unchanged quest does not: " .. tostring(settled)
        .. " -> " .. tostring(CN:GetModule("Quests").completionRevision))

    CN_TEST_COMPLETED[88100] = nil

    for id = 88100, 88142 do
        Static.quests[id] = nil
    end

    CN.ClearShortlist("Quests.Curated")
    CN.InvalidateCandidates()

    ------------------------------------------------------------
    -- AND /cn provenance SAYS WHOSE ROWS THEY ARE.
    ------------------------------------------------------------
    -- This counted every row in the curated table under the headline "each
    -- one checked by hand", and the table has been writable by any addon
    -- since it was published. The one command whose whole job is to expose
    -- unchecked claims would have mislabelled a companion addon's rows as
    -- hand-checked the moment one existed.
    Static.RegisterQuests({
        [88150] = { name = "Supplied row one" },
        [88151] = { name = "Supplied row two" },
    }, "TestSupplier")

    local spoken = {}

    local realAdd = DEFAULT_CHAT_FRAME.AddMessage

    DEFAULT_CHAT_FRAME.AddMessage = function(self, message)
        table.insert(spoken, tostring(message))
    end

    CN.HandleSlashCommand("provenance")

    DEFAULT_CHAT_FRAME.AddMessage = realAdd

    local text = table.concat(spoken, "\n")

    local total, curated = Static.Count()

    assert(total > curated,
        "the fixture holds rows from a supplier as well as this addon's own")

    assert(text:find("checked by hand: " .. curated, 1, true),
        "the hand-checked count is this addon's own rows, not the size of "
        .. "the table:\n" .. text)

    assert(not text:find("checked by hand: " .. total, 1, true),
        "and never the whole table:\n" .. text)

    assert(text:find("TestSupplier", 1, true),
        "and the supplier is named, under its own heading:\n" .. text)

    for id = 88150, 88151 do
        Static.quests[id] = nil
    end

    ------------------------------------------------------------
    -- AND A ROW IN THE DOCUMENTED VOCABULARY WINS, LIKE ONE IN THE OTHER.
    ------------------------------------------------------------
    -- `Quests.GetRecord` returns static data first "because it is the only
    -- source this addon controls and ships" -- and it tested `requiresLevel`,
    -- which is what `/cn export` emits, not `minLevel`, which is what the
    -- data file's header documents. So a row written to the addon's OWN
    -- schema was not treated as authoritative and could lose to an external
    -- addon's answer.
    Static.RegisterQuests({
        [88160] = { name = "Documented gate", minLevel = 70 },
        [88161] = { name = "Exported gate",   requiresLevel = 70 },
    }, "TestSupplier")

    local questModule = CN:GetModule("Quests")

    -- AN EXTERNAL ADDON THAT ANSWERS, because without one the fallthrough at
    -- the bottom of `GetRecord` returns the static row regardless and the
    -- assertion holds of the defect it exists for.
    CN.RegisterQuestDataProvider("TestExternal", {
        IsAvailable  = function() return true end,
        GetQuestData = function(questID)
            if questID == 88160 or questID == 88161 then
                return { name = "From an external addon",
                         requires = { 99999 } }
            end

            return nil
        end,
    })

    for _, questID in ipairs({ 88160, 88161 }) do
        local record, source = questModule.GetRecord(questID)

        assert(record and source == "static",
            "a curated row beats an external addon's answer whichever of the "
            .. "two documented spellings it gates on: " .. questID .. " -> "
            .. tostring(source))

        assert(record.name ~= "From an external addon",
            "and it is the curated row that comes back: "
            .. tostring(record.name))
    end

    -- Through the registrar's own withdrawal, so the order list and the
    -- provider table stay in step. Clearing one and not the other is what
    -- made  throw.
    CN.UnregisterQuestDataProvider("TestExternal")

    Static.quests[88160] = nil
    Static.quests[88161] = nil

    print("  the curated sweep is a shortlist, not a walk of the database")
end)()

;(function()
    ------------------------------------------------------------
    -- SIX MORE FIELDS NOTHING READS ARE NOT STORED.
    ------------------------------------------------------------
    -- `currencies.lastSeen` is the seventh store to carry this field with no
    -- reader, and `Modules/Currencies.lua`'s own header said so while the
    -- write survived four separate sweeps. `progress.previousDayKey` and
    -- `bestDay` sat beside `progress.total`, which migration 29 removed. The
    -- three harvest fields are on a store capped at two thousand rows.
    CN:GetModule("Currencies").Scan()

    for id, record in pairs(CN.Account("currencies") or {}) do
        assert(type(record) ~= "table" or record.lastSeen == nil,
            "account currency " .. tostring(id) .. " stores no timestamp")
    end

    for id, record in pairs((CN.character and CN.character.currencies) or {}) do
        assert(type(record) ~= "table" or record.lastSeen == nil,
            "character currency " .. tostring(id) .. " stores no timestamp")
    end

    for questID, record in pairs(CN.Account("questHarvest")) do
        if type(record) == "table" then
            for _, field in ipairs({ "observedLevel", "requiresFrom",
                                     "reason" }) do
                assert(record[field] == nil,
                    "harvest row " .. tostring(questID)
                    .. " stores no " .. field)
            end
        end
    end

    -- FORCE THE ROLLOVER, which is the branch that wrote the day key. A
    -- fixture that never crosses a day boundary asserts about a line that
    -- never ran.
    local progressModule = CN:GetModule("Progress")

    local held = CN.character.progress or {}

    CN.character.progress = held

    held.dayKey = "not-today"
    held.today  = 7

    progressModule.RollDay(held)

    assert(held.dayKey ~= "not-today",
        "the rollover branch ran: " .. tostring(held.dayKey))

    assert(held.previousDay == 7,
        "and moved yesterday's count where the reader looks for it: "
        .. tostring(held.previousDay))

    for _, field in ipairs({ "previousDayKey", "bestDay" }) do
        assert(held[field] == nil,
            "progress stores no " .. field .. ": " .. tostring(held[field]))
    end

    -- AND THE MIGRATION REMOVES THEM FROM A DATABASE THAT HAS THEM.
    local aged = {
        version = 35,
        account = {
            currencies   = { [3001] = { quantity = 5, lastSeen = 1 } },
            questHarvest = { [4242] = { requires = { 1 }, observedLevel = 60,
                                        requiresFrom = { "ATT" },
                                        reason = "login" } },
        },
        characters = {
            ["Someone-Realm"] = {
                currencies = { [3002] = { quantity = 7, lastSeen = 1 } },
                progress   = { today = 3, previousDayKey = "x",
                               bestDay = "y", best = 9 },
            },
        },
    }

    CN.RunMigrations(aged)

    assert(aged.account.currencies[3001].lastSeen == nil
        and aged.account.currencies[3001].quantity == 5,
        "the account currency loses the field and keeps the balance")

    assert(aged.characters["Someone-Realm"].currencies[3002].lastSeen == nil,
        "and so does the character half, which holds the larger share")

    local harvested = aged.account.questHarvest[4242]

    assert(harvested.observedLevel == nil and harvested.requiresFrom == nil
        and harvested.reason == nil and harvested.requires,
        "the harvest row loses three fields and keeps its evidence")

    local progress = aged.characters["Someone-Realm"].progress

    assert(progress.previousDayKey == nil and progress.bestDay == nil
        and progress.best == 9,
        "and progress loses two and keeps the number it prints")

    print("  six more fields nothing reads are not stored")
end)()

;(function()
    ------------------------------------------------------------
    -- A MODE'S NOTE DESCRIBES THE PROFILE IT SELECTS.
    ------------------------------------------------------------
    -- `/cn mode leveling` read "weighted toward fast travel" while its
    -- profile had a `types` table and no `weights` table at all, so
    -- `EffectiveWeights` returned the default travel cost unchanged. The note
    -- is printed by `/cn mode leveling`, by bare `/cn mode` and by
    -- `/cn status`.
    for name, mode in pairs(CN.modes) do
        local note = mode.note or ""

        if note:lower():find("travel", 1, true) then
            local selected = CN.priorityProfiles[mode.profile] or {}

            local weights = selected.weights or {}

            assert(weights.travelCost or weights.estimatedTime,
                "the mode named " .. name .. " claims a travel weighting its "
                .. "profile does not carry: " .. note)
        end
    end

    -- The two that DO weight travel still say so somewhere reachable.
    assert(CN.priorityProfiles.fastest.weights.travelCost < -1.0,
        "and the profile that does weight travel still does")

    -- AND THE RANKING RESOLVES THE MODE ONCE, NOT ONCE PER CANDIDATE.
    --
    -- `CN.Settings()` goes through the database's `__index`, which resolves
    -- the override table and the account settings on every read. The value is
    -- identical either way, so no fixture can tell the difference -- which is
    -- exactly why the contract is asserted where it is written.
    local scoring = CN_TEST_ReadAddonFile("Scoring.lua")

    assert(scoring and scoring:find("CN.ScoreObjective(objective, mode)", 1,
            true),
        "the rank loop passes the mode it has already computed")

    assert(scoring:find("function CN.ScoreObjective(objective, mode)", 1, true),
        "and the scorer takes it")

    -- Still correct when nobody passes one, which is every other caller.
    local alone = CN.ScoreObjective({ type = CN.objectiveTypes.QUEST,
        id = 970993, completionValue = 6 })

    assert(type(alone) == "number",
        "a caller that does not know the mode still gets a score: "
        .. tostring(alone))

    print("  a mode's note describes the profile it selects")
end)()

;(function()
    ------------------------------------------------------------
    -- THE QUEST LOG HAS HEADERS IN IT, AND THEY ARE NOT QUESTS.
    ------------------------------------------------------------
    -- `C_QuestLog.GetNumQuestLogEntries` counts zone-header rows as well as
    -- quests, and `GetInfo` returns `isHeader = true, questID = 0` for them.
    -- `Blizzard.GetQuestLogEntries` filters on exactly that -- and with a
    -- fixture containing no headers the filter had never been exercised once.
    local entries = CN.Blizzard.GetQuestLogEntries()

    assert(#entries > 0, "the log answers")

    for _, entry in ipairs(entries) do
        assert(entry.questID and entry.questID ~= 0,
            "a zone header is not a quest: " .. tostring(entry.title))

        assert(entry.isHeader ~= true,
            "and is filtered out rather than carried: "
            .. tostring(entry.title))
    end

    local headers = 0

    for index = 1, C_QuestLog.GetNumQuestLogEntries() do
        local info = C_QuestLog.GetInfo(index)

        if info and info.isHeader then
            headers = headers + 1
        end
    end

    assert(headers >= 2,
        "the fixture contains headers for the filter to remove: "
        .. tostring(headers))

    print("  the quest log has headers in it, and they are not quests")
end)()

;(function()
    ------------------------------------------------------------
    -- THE DAILY RESET IS AN INSTANT, AND IT DOES NOT MOVE.
    ------------------------------------------------------------
    -- The client returns a COUNTDOWN. The stub returned a fixed number of
    -- seconds whatever the clock said, so `Progress.CurrentDayKey`'s
    -- `knownResetAt = now + seconds` drifted forward with `time()` instead of
    -- standing still -- and standing still is the invariant the 0.61.0 fix
    -- rests on: "the reset instant is an ABSOLUTE time and it does not move".
    -- An earlier block leaves the client refusing, deliberately, so this one
    -- re-anchors rather than depending on whatever ran before it.
    CN_TEST_SetDailyReset(5 * 3600)

    local first = GetQuestResetTime()

    assert(type(first) == "number" and first > 0,
        "the client answers with seconds remaining: " .. tostring(first))

    local realTime = time

    time = function() return realTime() + 60 end

    local later = GetQuestResetTime()

    time = realTime

    assert(later < first,
        "and a minute later there is less of it left: " .. tostring(first)
        .. " -> " .. tostring(later))

    assert(math.abs((first - later) - 60) <= 1,
        "by exactly the minute that passed: " .. tostring(first - later))

    print("  the daily reset is an instant, and it does not move")
end)()


;(function()
    ------------------------------------------------------------
    -- "FOREVER" IS THE ABSENCE OF A DEADLINE, NOT AN INFINITE ONE.
    ------------------------------------------------------------
    -- `/cn defer forever` passes `math.huge`, and `CN.SetDeferred` stored
    -- `time() + math.huge` -- which is `inf`. The client serialises that as
    -- the bare word `inf`, which parses on the next login as an UNDEFINED
    -- GLOBAL and comes back as nil. So the addon wrote a deadline and read
    -- back nothing, silently, with no error anywhere.
    --
    -- It behaved correctly by accident: a missing `until_` means "never
    -- expires". Behaving correctly by accident is not being correct -- any
    -- addon defining a global named `inf` would have changed the value, and
    -- every reader doing arithmetic on it was one line from a bug nobody
    -- could reproduce.
    local objective = { type = CN.objectiveTypes.QUEST, id = 970771 }

    CN.SetDeferred(objective.type, objective.id, math.huge)

    local store = CN.Account("deferredObjectives")

    local entry = store[objective.type] and store[objective.type][objective.id]

    assert(entry, "the deferral is stored")

    assert(entry.until_ == nil,
        "an endless deferral stores no deadline, rather than one that cannot "
        .. "be read back: " .. tostring(entry.until_))

    assert(CN.IsDeferred(objective.type, objective.id),
        "and it is still deferred, which is what forever means")

    -- A FINITE ONE STILL STORES A NUMBER.
    CN.SetDeferred(objective.type, objective.id, 3600)

    entry = store[objective.type][objective.id]

    assert(type(entry.until_) == "number" and entry.until_ > time(),
        "an hour is still an hour: " .. tostring(entry.until_))

    -- AND EVERY DURATION THE ADDON OFFERS ROUND-TRIPS.
    local durationTable = CN:GetModule("Filters")

    for _, duration in ipairs(durationTable.durations) do
        local seconds = durationTable.DurationSeconds(duration.key)

        CN.SetDeferred(objective.type, objective.id, seconds)

        local held = store[objective.type][objective.id]

        assert(held.until_ == nil
            or (held.until_ == held.until_ and held.until_ < math.huge),
            "the duration named " .. tostring(duration.key)
            .. " stores a value the client can write and read back: "
            .. tostring(held.until_))
    end

    -- AND THE MIGRATION NORMALISES ONE ALREADY ON DISK.
    local aged = {
        version = 36,
        account = {
            deferredObjectives = {
                QUEST = { [4242] = { since = 1, until_ = math.huge } },
            },
            vendors = { [77] = { npcID = 77, firstSeen = 1, name = "Bob" } },
            rares   = { [88] = { vignetteID = 88, firstSeen = 1,
                                 lastSeen = 2 } },
        },
        characters = {},
    }

    CN.RunMigrations(aged)

    assert(aged.account.deferredObjectives.QUEST[4242].until_ == nil,
        "a deadline that could not be read back is normalised away")

    assert(aged.account.vendors[77].firstSeen == nil
        and aged.account.vendors[77].name == "Bob",
        "the vendor loses a timestamp nothing reads and keeps its name")

    assert(aged.account.rares[88].firstSeen == nil
        and aged.account.rares[88].lastSeen == 2,
        "and the rare keeps `lastSeen`, which the sightings gap does read")

    CN.SetDeferred(objective.type, objective.id, nil)

    print("  an endless deferral stores no deadline")
end)()

;(function()
    ------------------------------------------------------------
    -- CAGING A PET SCANS THE JOURNAL ONCE.
    ------------------------------------------------------------
    -- `NEW_PET_ADDED` set `lastScan = 0` and then called `Pets.Scan`, which
    -- makes the throttle test in the sibling handler false -- so caging a pet
    -- ran the whole sweep, then `PET_JOURNAL_LIST_UPDATE` arrived and ran it
    -- again. Each sweep widens and restores the player's own journal filters.
    --
    -- `Modules/Currencies.lua` records fixing this exact shape in 0.65.0, in
    -- as many words.
    local pets = CN:GetModule("Pets")

    -- COUNTED AT THE CLIENT, not at `Pets.Scan`. An event handler registered
    -- with the function VALUE holds the original, so wrapping the module
    -- field measures nothing about what the handler actually calls.
    -- COUNTED AT THE JOURNAL SWEEP, not at `Pets.Scan`. An event handler
    -- registered with the function VALUE holds the original, so wrapping the
    -- module field measures nothing about what the handler actually calls --
    -- and `GetNumPets` is asked more than once per sweep, so it is not a
    -- sweep counter either.
    --
    -- `WithAllPetsShown` runs exactly once per scan, and it is the expensive
    -- part: it widens and then restores the player's own journal filters.
    local sweeps = 0

    local realShown = CN.Blizzard.WithAllPetsShown

    CN.Blizzard.WithAllPetsShown = function(...)
        sweeps = sweeps + 1

        return realShown(...)
    end

    pets.lastScan = 0

    CN.FireEvent("NEW_PET_ADDED")
    CN.FireEvent("PET_JOURNAL_LIST_UPDATE")

    CN.Blizzard.WithAllPetsShown = realShown

    assert(sweeps == 1,
        "caging a pet reads the journal once, not twice: " .. tostring(sweeps))

    -- AND THE SCAN STAMPS THE THROTTLE ITSELF, which is what makes that true
    -- from every entry point rather than from one handler.
    assert(type(pets.lastScan) == "number" and pets.lastScan > 0,
        "the scan records when it ran: " .. tostring(pets.lastScan))

    local source = CN_TEST_ReadAddonFile("Modules/Pets.lua")

    for line in string.gmatch(source, "[^\n]+") do
        if not line:find("^%s*%-%-") then
            assert(not line:find("Pets.lastScan = 0", 1, true)
                or line:find("^Pets.lastScan", 1, true),
                "nothing clears the stamp before scanning, which is the "
                .. "shape that guarantees the double sweep: " .. line)
        end
    end

    print("  caging a pet scans the journal once")
end)()

;(function()
    ------------------------------------------------------------
    -- A COLD PET JOURNAL IS NOT AN EMPTY COLLECTION.
    ------------------------------------------------------------
    -- `GetNumPets` answers 0 while the journal is cold, which is the state at
    -- login -- and `CN:OnLogin` runs the scan. Recording that as a scan threw
    -- away the name index (~1,800 client calls to rebuild, on the tooltip
    -- path), marked the setup step done so the reminder stopped asking, and
    -- made `/cn petscan` print "0 species" while `/cn pets` reported the full
    -- collection a second later.
    local pets = CN:GetModule("Pets")

    pets.Scan()

    local held = CN.CountKeys(pets.Store())

    assert(held > 0, "the fixture has pets")

    local settled = pets.nameRevision

    local realNum = C_PetJournal.GetNumPets

    C_PetJournal.GetNumPets = function() return 0, 0 end

    local seen, owned, missing = pets.Scan()

    C_PetJournal.GetNumPets = realNum

    assert(seen == 0 and owned == 0 and missing == 0,
        "a refused sweep reports nothing rather than a confident zero: "
        .. tostring(seen))

    assert(CN.CountKeys(pets.Store()) == held,
        "and leaves the store alone: " .. tostring(CN.CountKeys(pets.Store()))
        .. " of " .. tostring(held))

    assert(pets.nameRevision == settled,
        "and does not throw away the name index the tooltip path depends on: "
        .. tostring(settled) .. " -> " .. tostring(pets.nameRevision))

    print("  a cold pet journal is not an empty collection")
end)()

;(function()
    ------------------------------------------------------------
    -- /cn who DOES NOT NAME THE CHARACTER WHO ALREADY DID IT.
    ------------------------------------------------------------
    -- `WhoShould` sets `switchable = false` for a recipe or title, because
    -- the character it names is the one who ALREADY HAS IT. Three callers
    -- honour that -- `Alts.Assignments` since 0.79.0, `Goals` since 0.84.0,
    -- `Warband.Suitability` since 0.88.0, whose own note calls itself "the
    -- third caller". `/cn who` was the fourth, and it is the command whose
    -- help line is "Which character should do something".
    local warband = CN:GetModule("Warband")

    local holder = "Holder-Testrealm"

    CN.db.characters[holder] = {
        name     = "Holder",
        realm    = "Testrealm",
        lastSeen = time(),
        recipes  = { [7301] = true },
    }

    local _, _, _, switchable =
        warband.WhoShould(CN.objectiveTypes.RECIPE, 7301)

    assert(switchable == false,
        "the fixture reaches the branch where there is nothing to switch for")

    local spoken = {}

    local realAdd = DEFAULT_CHAT_FRAME.AddMessage

    DEFAULT_CHAT_FRAME.AddMessage = function(self, message)
        table.insert(spoken, tostring(message))
    end

    CN.HandleSlashCommand("who recipe 7301")

    DEFAULT_CHAT_FRAME.AddMessage = realAdd

    local text = table.concat(spoken, "\n")

    assert(not text:find("Best character", 1, true),
        "a recipe somebody already knows has no better character to switch "
        .. "to:\n" .. text)

    assert(text:find("Holder", 1, true),
        "while still naming who holds it:\n" .. text)

    CN.db.characters[holder] = nil

    print("  /cn who does not name the character who already did it")
end)()

;(function()
    ------------------------------------------------------------
    -- "IN YOUR CURRENT ZONE" IS A CLAIM ABOUT THE ZONE.
    ------------------------------------------------------------
    -- The guard tested whether the client would give the player a position at
    -- all. So a vignette on another map was still labelled "in your current
    -- zone", and a rare genuinely in this zone lost the line whenever the
    -- client withheld coordinates -- indoors, mid-loading-screen -- which is
    -- when a `/cn why` line is most likely to be read.
    local source = CN_TEST_ReadAddonFile("Modules/Rares.lua")

    assert(source:find("if vignette.mapID and vignette.mapID == playerMap then",
            1, true),
        "the guard compares maps")

    assert(not source:find("if playerX and playerY then", 1, true),
        "and not whether the client placed the player")

    for _, objective in ipairs(CN.candidateProviders["Rares"].fn() or {}) do
        local claimsZone = false

        for _, reason in ipairs(objective.reasons or {}) do
            if reason:find("in your current zone", 1, true) then
                claimsZone = true
            end
        end

        if claimsZone then
            assert(objective.mapID == nil
                or objective.mapID == select(1, CN.GetPlayerPosition()),
                "only a rare actually on this map says it is on this map: "
                .. tostring(objective.name))
        end
    end

    -- AND NEITHER STORE WRITES A TIMESTAMP NOTHING READS. `lastSeen` on a
    -- rare IS read, for the sightings gap, and stays.
    for id, record in pairs(CN.Account("rares") or {}) do
        assert(type(record) ~= "table" or record.firstSeen == nil,
            "rare " .. tostring(id) .. " stores no firstSeen")
    end

    for id, record in pairs(CN.Account("vendors") or {}) do
        assert(type(record) ~= "table" or record.firstSeen == nil,
            "vendor " .. tostring(id) .. " stores no firstSeen")
    end

    for _, file in ipairs({ "Modules/Rares.lua", "Modules/Vendors.lua" }) do
        local text = CN_TEST_ReadAddonFile(file)

        for line in string.gmatch(text, "[^\n]+") do
            if not line:find("^%s*%-%-") then
                assert(not line:find("firstSeen", 1, true),
                    file .. " does not write a timestamp nothing reads: "
                    .. line)
            end
        end
    end

    print("  in your current zone is a claim about the zone")
end)()

;(function()
    ------------------------------------------------------------
    -- A NAME CLAIMED TWICE IS SAID OUT LOUD.
    ------------------------------------------------------------
    -- `Core.lua` has recorded duplicate command names since it was written,
    -- under a comment reading "`/cn selftest` names them". Nothing named
    -- them: `CN.commandCollisions` had two references in the tree and both
    -- were writes. The same is true of the curated-data collision list, which
    -- `/cn provenance` reported only as a count -- so a player told "3 quests
    -- claimed by more than one source" could not find out which three.
    local selftest = CN:GetModule("SelfTest")

    local byName = {}

    for _, check in ipairs(selftest.Run().checks) do
        byName[check.name] = check
    end

    assert(byName["no command name is claimed twice"],
        "the command collision list has a reader")

    assert(byName["no quest is claimed by two data sources"],
        "and so does the curated data one")

    assert(byName["curated quest data"],
        "and a player can see whether a supplier is installed")

    -- AND IT FAILS WHEN THERE IS ONE. A check that reads a list nothing fills
    -- always passes, which is the state this replaced.
    local realCommandCollisions = CN.commandCollisions

    CN.commandCollisions = {
        { name = "zones", kind = "alias", from = "Zones", to = "Loremaster" },
    }

    local reportedCommand

    for _, check in ipairs(selftest.Run().checks) do
        if check.name == "no command name is claimed twice" then
            reportedCommand = check
        end
    end

    CN.commandCollisions = realCommandCollisions

    assert(reportedCommand.status == selftest.results.FAIL,
        "a command claimed twice is a failure, not a pass: "
        .. tostring(reportedCommand.status))

    assert(reportedCommand.detail:find("zones", 1, true),
        "and the name is printed: " .. tostring(reportedCommand.detail))

    -- WITH THE COLLISION NAMED, not just counted.
    local realCollisions = CN.Static.collisions

    CN.Static.collisions = {
        { questID = 970772, kept = "curated", lost = "SomeSupplier" },
    }

    local reported

    for _, check in ipairs(selftest.Run().checks) do
        if check.name == "no quest is claimed by two data sources" then
            reported = check
        end
    end

    CN.Static.collisions = realCollisions

    assert(reported.detail and reported.detail:find("970772", 1, true),
        "the quest is named: " .. tostring(reported.detail))

    assert(reported.detail:find("SomeSupplier", 1, true),
        "and so is the source that lost: " .. tostring(reported.detail))

    print("  a name claimed twice is said out loud")
end)()

;(function()
    ------------------------------------------------------------
    -- A DATA SUPPLIER IS VISIBLE WHERE THE PLAYER LOOKS FOR ONE.
    ------------------------------------------------------------
    -- `/cn providers`' help line is "Show which external data addons were
    -- detected", and it enumerated the two live-query registries only. An
    -- addon that hands over curated rows registers once and stops, so it is
    -- not a `questDataProvider` -- and the one command named for this
    -- question was structurally unable to answer it.
    local landed = CN.Static.RegisterQuests({
        [970780] = { name = "Supplied one" },
        [970781] = { name = "Supplied two" },
    }, "ProbeSupplier")

    assert(landed == 2, "the probe rows registered: " .. tostring(landed))

    assert(CN.Static.Origins().ProbeSupplier == 2,
        "and are counted under their supplier: "
        .. tostring(CN.Static.Origins().ProbeSupplier))

    local spoken = {}

    local realAdd = DEFAULT_CHAT_FRAME.AddMessage

    DEFAULT_CHAT_FRAME.AddMessage = function(self, message)
        table.insert(spoken, tostring(message))
    end

    local ranOk, ranErr = pcall(CN.HandleSlashCommand, "providers")

    DEFAULT_CHAT_FRAME.AddMessage = realAdd

    assert(ranOk, "/cn providers runs: " .. tostring(ranErr))

    local text = table.concat(spoken, "\n")

    assert(#spoken > 0, "and prints something")

    assert(text:find("ProbeSupplier", 1, true),
        "the supplier is named:\n" .. text)

    assert(text:find("2 quest rows", 1, true),
        "with how many rows it supplied:\n" .. text)

    -- AND A SUPPLIER CAN TAKE THEM BACK, which is what makes registering
    -- twice work rather than colliding with itself.
    assert(CN.Static.UnregisterOrigin("ProbeSupplier") == 2,
        "an origin's rows can be withdrawn")

    assert(CN.Static.GetQuest(970780) == nil,
        "and they are gone")

    assert(CN.Static.UnregisterOrigin("curated") == 0,
        "but this addon's own rows are not a supplier's to withdraw")

    -- THE HEADING, NOT ONLY THE ROWS. A supplier line with nothing above it
    -- reads as part of the waypoint list.
    assert(text:find("Curated row suppliers", 1, true),
        "the section is labelled:\n" .. text)

    ------------------------------------------------------------
    -- AND A WITHDRAWN PROVIDER LEAVES BOTH REGISTRIES.
    ------------------------------------------------------------
    -- `CN.questDataProviders` and `CN.questDataOrder` are two views of one
    -- thing, and only registration kept them in step. Clearing one without
    -- the other left the command that reports what is installed indexing a
    -- nil.
    CN.RegisterQuestDataProvider("WithdrawMe", {
        IsAvailable  = function() return true end,
        GetQuestData = function() return nil end,
    })

    local listed = 0

    for _, entry in ipairs(CN.questDataOrder) do
        if entry.name == "WithdrawMe" then listed = listed + 1 end
    end

    assert(listed == 1, "the provider registered into the order")

    assert(CN.UnregisterQuestDataProvider("WithdrawMe") == true,
        "and can be withdrawn")

    assert(CN.questDataProviders["WithdrawMe"] == nil,
        "out of the table")

    for _, entry in ipairs(CN.questDataOrder) do
        assert(entry.name ~= "WithdrawMe",
            "and out of the order, which is the half that was forgotten")
    end

    assert(CN.UnregisterQuestDataProvider("NeverRegistered") == false,
        "and withdrawing something absent says so rather than throwing")

    ------------------------------------------------------------
    -- THE COMMAND SURVIVES A REGISTRY THAT IS OUT OF STEP ANYWAY.
    ------------------------------------------------------------
    -- The withdrawal above keeps them together. This is the belt: a
    -- diagnostic that reports what is installed should be the last thing in
    -- the addon to fall over when something is not.
    table.insert(CN.questDataOrder, { name = "GhostProvider", sequence = 999 })

    spoken = {}

    DEFAULT_CHAT_FRAME.AddMessage = function(self, message)
        table.insert(spoken, tostring(message))
    end

    local survived = pcall(CN.HandleSlashCommand, "providers")

    DEFAULT_CHAT_FRAME.AddMessage = realAdd

    for index = #CN.questDataOrder, 1, -1 do
        if CN.questDataOrder[index].name == "GhostProvider" then
            table.remove(CN.questDataOrder, index)
        end
    end

    assert(survived, "the command does not throw on a half-removed provider")

    assert(not table.concat(spoken, "\n"):find("Error in", 1, true),
        "and does not report an error:\n" .. table.concat(spoken, "\n"))

    print("  a data supplier is visible where the player looks for one")
end)()

;(function()
    ------------------------------------------------------------
    -- A BAD SUPPLIER DOES NOT EVICT EVERY OTHER ERROR.
    ------------------------------------------------------------
    -- `Errors.capacity` is 20 and the dedupe key is context plus message, so
    -- one entry per refused row meant twenty-one bad rows evicted everything
    -- else recorded that session -- including the supplier's own summary --
    -- and `/cn errors` printed twenty near-identical lines with the one real
    -- problem buried underneath.
    local errors = CN:GetModule("Errors")

    errors.Record("a marker", "something that must survive")

    local rows = {}

    for id = 971000, 971040 do
        rows[tostring(id)] = { name = "Bad key " .. id }
    end

    local landedRows, refusedRows = CN.Static.RegisterQuests(rows, "NoisySupplier")

    assert(landedRows == 0 and refusedRows == 41,
        "every row was refused: " .. tostring(landedRows) .. " / "
        .. tostring(refusedRows))

    local kept, mentioned = 0, false

    for _, notice in ipairs(errors.All()) do
        if notice.context == "a marker" then
            kept = kept + 1
        end

        -- This supplier's entry, not an earlier block's. Every refusal shares
        -- one context now, which is the point.
        if tostring(notice.context):find("refused", 1, true)
            and tostring(notice.message):find("NoisySupplier", 1, true) then

            mentioned = true

            assert(tostring(notice.message):find("41", 1, true),
                "the one entry says how many: " .. tostring(notice.message))
        end
    end

    assert(mentioned, "the refusal is recorded")

    assert(kept == 1,
        "and forty-one bad rows do not evict what was already there")

    print("  a bad supplier does not evict every other error")
end)()

;(function()
    ------------------------------------------------------------
    -- /cn sells SAYS WHAT SOMETHING COSTS.
    ------------------------------------------------------------
    -- The price has been on disk since vendors were added, under a comment
    -- justifying the space: the client only reports it while the merchant
    -- window is open, so unlike the item's name it genuinely cannot be
    -- recovered later. Nothing then read it -- `Vendors.PriceOf` had one
    -- caller, filling a field no surface printed, and `record.extendedCost`
    -- had no reader at all.
    local vendorModule = CN:GetModule("Vendors")

    local rows = vendorModule.WhoSells(700)

    assert(rows and #rows > 0, "the fixture records a seller for 700")

    local sawPrice = false

    for _, seller in ipairs(rows) do
        if seller.price ~= nil then
            sawPrice = true
        end

        -- BOTH RETURNS. The second is what distinguishes a gold price from a
        -- currency or token cost, which is the difference that decides
        -- whether the walk is worth it.
        assert(seller.extendedCost ~= nil or seller.price == nil,
            "a seller carries whether its price is gold at all: "
            .. tostring(seller.name))
    end

    assert(sawPrice, "and at least one price survived the lookup")

    local source = CN_TEST_ReadAddonFile("Modules/Vendors.lua")

    assert(source:find("seller.price, seller.extendedCost", 1, true),
        "the lookup binds both returns rather than truncating the second")

    assert(source:find("costs a currency, not gold", 1, true),
        "and the command has a sentence for each")

    -- AND THE PRICE IS PRINTED IN THE CLIENT'S OWN MONEY FORMAT.
    local spoken = {}

    local realAdd = DEFAULT_CHAT_FRAME.AddMessage

    DEFAULT_CHAT_FRAME.AddMessage = function(self, message)
        table.insert(spoken, tostring(message))
    end

    CN.HandleSlashCommand("sells 700")

    DEFAULT_CHAT_FRAME.AddMessage = realAdd

    local text = table.concat(spoken, "\n")

    assert(text:find("g ", 1, true) or text:find("currency", 1, true),
        "what it costs is on the line, not only in the store:\n" .. text)

    print("  /cn sells says what something costs")
end)()

;(function()
    ------------------------------------------------------------
    -- A SUPPLIER CAN TELL WHAT THIS REGISTRAR PROMISES.
    ------------------------------------------------------------
    -- `RegisterQuests` existed before 0.91.0 too, and the old one took
    -- anything, returned nothing and stamped no origin -- so a companion
    -- guarding on `type(RegisterQuests) == "function"` passes on an old build
    -- and gets `nil, nil` back, with all of its rows counted under "each one
    -- checked by hand".
    assert(type(CN.Static.apiVersion) == "number"
        and CN.Static.apiVersion >= 1,
        "the registrar publishes a contract number a supplier can test: "
        .. tostring(CN.Static.apiVersion))

    assert(CN.Static.apiVersion ~= CN.Static.schemaVersion
        or type(CN.Static.schemaVersion) == "number",
        "and it is separate from the record schema version")

    -- Everything the number promises is actually there.
    for _, name in ipairs({ "RegisterQuest", "RegisterQuests", "Origins",
                            "Count", "UnregisterOrigin" }) do
        assert(type(CN.Static[name]) == "function",
            "apiVersion 1 promises " .. name)
    end

    assert(type(CN.Static.collisions) == "table"
        and type(CN.Static.revision) == "number",
        "and a collision list and a revision")

    print("  a supplier can tell what this registrar promises")
end)()

;(function()
    ------------------------------------------------------------
    -- THE WEEKLY RESET IS AN INSTANT, AND IT DOES NOT MOVE.
    ------------------------------------------------------------
    -- 0.91.0 converted the daily reset from a constant to a countdown and
    -- left its sibling in the same table untouched. `Rares.ClearedUntil`
    -- persists `time() + seconds`, so with the real client two rares cleared
    -- two days apart expire at the SAME reset -- and with a constant they
    -- expired two days apart, making the intended behaviour and a wrong
    -- implementation indistinguishable.
    CN_TEST_SetWeeklyReset(3 * 86400)

    local first = C_DateAndTime.GetSecondsUntilWeeklyReset()

    assert(type(first) == "number" and first > 0,
        "the client answers with seconds remaining: " .. tostring(first))

    local realTime = time

    time = function() return realTime() + 3600 end

    local later = C_DateAndTime.GetSecondsUntilWeeklyReset()

    time = realTime

    assert(math.abs((first - later) - 3600) <= 1,
        "and an hour later there is an hour less of it: "
        .. tostring(first - later))

    -- AND IT CAN REFUSE, which the client does during loading and which
    -- `Modules/Rares.lua` has a fallback for that nothing could reach.
    CN_TEST_SetWeeklyReset(nil)

    assert(C_DateAndTime.GetSecondsUntilWeeklyReset() == nil,
        "a client that will not answer answers with nothing")

    assert(CN.Blizzard.GetSecondsUntilWeeklyReset() == nil,
        "and the wrapper passes that through rather than inventing a week")

    CN_TEST_SetWeeklyReset(3 * 86400)

    print("  the weekly reset is an instant, and it does not move")
end)()

;(function()
    ------------------------------------------------------------
    -- NO PRINTED LINE PADS BETWEEN TWO LABELS.
    ------------------------------------------------------------
    -- WoW ships no monospace chat font, so three spaces after a one-digit
    -- count and after a four-digit count are two different widths and the
    -- second label never lines up. The 0.77.0 sweep reached three files;
    -- seven more had it, including two in the window.
    --
    -- Leading indentation is not padding -- a nested line under a heading is
    -- deliberate -- so only runs INSIDE the text are refused.
    local offenders = {}

    for _, file in ipairs(CN_TEST_ADDON_FILES) do
        local text = CN_TEST_ReadAddonFile(file)

        if text then
            for line in string.gmatch(text, "[^\n]+") do
                if not string.find(line, "^%s*%-%-") then
                    for literal in string.gmatch(line, '"([^"]*)"') do
                        -- Strip colour codes first: they are not drawn, so
                        -- they are not spacing.
                        local shown = literal
                            :gsub("|c%x%x%x%x%x%x%x%x", "")
                            :gsub("|r", "")

                        -- THREE SHAPES ARE NOT COLUMN PADDING.
                        --
                        --   * A run around a separator glyph, which is
                        --     symmetric by design: "a  <dot>  b".
                        --   * A run after a list number: "1.  Scan once".
                        --   * A run around an `=`, which is this addon
                        --     GENERATING Lua source for a data file, where
                        --     aligned assignments are the point.
                        local padded = string.find(shown, "%S  +%S")

                        local exempt = string.find(shown, "  " .. CN.DOT)
                            or string.find(shown, CN.DOT .. "  ")
                            or string.find(shown, "%d%.  ")
                            or string.find(shown, "  =")
                            or string.find(shown, "=  ")

                        if padded and not exempt then
                            table.insert(offenders,
                                file .. ': "' .. literal .. '"')
                        end
                    end
                end
            end
        end
    end

    assert(#offenders == 0,
        "a printed line separates with a word or a dot, never with spaces:\n"
        .. table.concat(offenders, "\n"))

    print("  no printed line pads between two labels")
end)()

;(function()
    ------------------------------------------------------------
    -- A TRANSLATION IS IN THE LANGUAGE IT CLAIMS TO BE.
    ------------------------------------------------------------
    -- Three strings added in 0.78.0 were transliterated or stripped of
    -- diacritics in ruRU, frFR and ptBR, while each of those files spelled
    -- the identical word correctly elsewhere in its own table. A Russian
    -- player finishing a route read Latin-script text between two Cyrillic
    -- lines.
    --
    -- Checked structurally rather than by eye: in a file whose values are
    -- mostly non-ASCII, an all-ASCII value is either a proper noun or a
    -- mistake, and this addon has no proper nouns in its locale tables.
    local suspicious = {}

    for _, file in ipairs(CN_TEST_ADDON_FILES) do
        if file:find("^Locales/") and not file:find("enUS") then
            local text = CN_TEST_ReadAddonFile(file)

            local values, ascii = 0, {}

            for value in string.gmatch(text or "", '%]%s*=%s*"([^"]+)"') do
                values = values + 1

                if not string.find(value, "[\128-\255]") then
                    table.insert(ascii, value)
                end
            end

            -- Only files that are MOSTLY non-ASCII, so a Latin-script locale
            -- is not accused of failing to be Cyrillic.
            if values > 20 and (#ascii / values) < 0.35 then
                for _, value in ipairs(ascii) do
                    -- A value that is only format specifiers and punctuation
                    -- has no letters to accent.
                    if string.find(value, "%a%a%a") then
                        table.insert(suspicious, file .. ': "' .. value .. '"')
                    end
                end
            end
        end
    end

    assert(#suspicious == 0,
        "a value with no accented characters, in a file that is otherwise "
        .. "accented, is a stripped translation:\n"
        .. table.concat(suspicious, "\n"))

    print("  a translation is in the language it claims to be")
end)()

;(function()
    ------------------------------------------------------------
    -- THE TRUNCATION ROW LOOKS AS INERT AS IT IS.
    ------------------------------------------------------------
    -- Rows are pooled. The fill loop sets `EnableMouse` and the highlight
    -- alpha per row and the empty branch clears both; the truncation branch
    -- cleared neither. So when that index had last held an actionable row,
    -- "and N more not shown" still took the mouse and still lit on hover,
    -- while its click was a no-op.
    local source = CN_TEST_ReadAddonFile("UI/List.lua")

    -- Anchored on the row's own text, not on `if truncated > 0`: that
    -- appears twice, and the first is the block that makes ROOM for this one.
    local block = source:match(
        '(row%.label:SetText%(CN%.Muted%("and ".-row:Show%(%))')

    assert(block, "the truncation branch is findable")

    assert(block:find("row:EnableMouse(false)", 1, true),
        "the truncation row takes no mouse input")

    assert(block:find("row.highlight:SetAlpha(0)", 1, true),
        "and does not light up under the cursor, which would say it is "
        .. "clickable")

    print("  the truncation row looks as inert as it is")
end)()

;(function()
    ------------------------------------------------------------
    -- THE CROSS-TAB COUNT SEARCHES WHAT THE TAB SEARCHED.
    ------------------------------------------------------------
    -- `SetFilter` trims and lowers; `CountMatching` only lowered, and the
    -- window passes the raw search-box text. So one trailing space made
    -- "Also on: Collections (0)" appear beside a Collections tab showing
    -- twelve matching rows.
    local panel = CN.UI and CN.UI.listPanels and next(CN.UI.listPanels)

    if panel then
        local list = CN.UI.listPanels[panel]

        list:SetEntries({
            { text = "Alpha thing" },
            { text = "Beta thing" },
            { text = "Alpha other" },
        })

        local exact   = list:CountMatching("alpha")
        local spaced  = list:CountMatching("alpha ")
        local padded  = list:CountMatching("  alpha  ")

        assert(exact > 0, "the fixture matches something: " .. tostring(exact))

        assert(spaced == exact and padded == exact,
            "a trailing space is not a different search: " .. tostring(exact)
            .. " vs " .. tostring(spaced) .. " vs " .. tostring(padded))
    end

    print("  the cross-tab count searches what the tab searched")
end)()

;(function()
    ------------------------------------------------------------
    -- AN APPEARANCE SLOT IS NAMED IN THE LANGUAGE THE CLIENT IS IN.
    ------------------------------------------------------------
    -- `Appearances.Scan` wrote `name = category.name` into every stored row
    -- and `Summary`, `Remaining` and the candidate provider all read it back
    -- off disk. Nine other modules in this addon have a live-name accessor
    -- for exactly this reason, and three of them carry a comment saying
    -- `Appearances.lua` made the argument first -- in 0.58.0 -- and was
    -- itself never swept.
    --
    -- A player who changes client language keeps the old language until
    -- something happens to rescan, which is throttled to ten minutes.
    local slotModule = CN:GetModule("Appearances")

    assert(slotModule, "the appearances module must be loaded")

    slotModule.Scan()

    for _, record in pairs(slotModule.Store()) do
        assert(record.name == nil,
            "no appearance row stores a localized name")
    end

    CN_TEST_SetAppearanceCategoryName(1, "Kopf")

    local sawGerman = false

    for _, row in ipairs(slotModule.Remaining()) do
        if row.name == "Kopf" then
            sawGerman = true
        end

        assert(row.name ~= "Head",
            "the old language must not survive a client language change")
    end

    assert(sawGerman,
        "the slot name comes from the client, not from disk")

    -- AND THE CANDIDATE THE PLAYER READS IN `/cn next`, which is the third
    -- read site and the one that was missed when the other two were fixed.
    local slotCandidates = CN.CollectCandidates and CN.CollectCandidates(true) or {}
    local named      = false

    for _, candidate in ipairs(slotCandidates) do
        if candidate.type == CN.objectiveTypes.APPEARANCE then
            assert(not string.find(tostring(candidate.name), "Head", 1, true),
                "and neither does the candidate: " .. tostring(candidate.name))

            named = true
        end
    end

    assert(named, "the appearance provider still produces candidates")

    CN_TEST_SetAppearanceCategoryName(1, "Head")

    -- A CLIENT THAT CANNOT ANSWER STILL NAMES THE ROW.
    local held = C_TransmogCollection.GetCategoryInfo

    C_TransmogCollection.GetCategoryInfo = function() return nil end

    assert(slotModule.NameOf(1) == "Slot 1",
        "with no client answer the row is identified by its id, not by a "
        .. "guess in a language: " .. tostring(slotModule.NameOf(1)))

    C_TransmogCollection.GetCategoryInfo = held

    -- AND MIGRATION 37 TAKES THE FIELD OFF DISK -- ON BOTH SIDES.
    local aged = {
        version = 36,
        account = {
            appearances = { [1] = { categoryID = 1, name = "Head",
                                    collected = 120, total = 400 } },
            reputations = { [2600] = { factionID = 2600, name = "Threads",
                                       reaction = 5 } },
        },
        characters = {
            ["Someone-Realm"] = {
                reputations = { [1090] = { factionID = 1090,
                                           name = "Kirin Tor", reaction = 7 } },
            },
        },
    }

    CN.RunMigrations(aged)

    assert(aged.account.appearances[1].name == nil
        and aged.account.appearances[1].collected == 120,
        "the appearance row loses its name and keeps its counts")

    assert(aged.account.reputations[2600].name == nil
        and aged.account.reputations[2600].reaction == 5,
        "the account faction loses its name and keeps its standing")

    assert(aged.characters["Someone-Realm"].reputations[1090].name == nil,
        "and so does the CHARACTER-side faction, which is the half a "
        .. "one-call-site fix would have left behind")

    print("  an appearance slot is named in the client's language, not disk's")
end)()

;(function()
    ------------------------------------------------------------
    -- AN ACHIEVEMENT CAN ENTER THE SHORTLIST BY APPROACHING IT.
    ------------------------------------------------------------
    -- The five-second criteria sweep read only rows ALREADY on the shortlist
    -- plus pinned goals, so a row at 37 of 40 was never observed and could
    -- never become nearly done -- while `ACHIEVEMENT_EARNED` deletes rows
    -- outright. Between two manual full scans the shortlist could only
    -- shrink, and nothing runs a full scan on its own.
    local achievements = CN:GetModule("Achievements")

    assert(achievements, "the achievements module must be loaded")

    local store = achievements.Store and achievements.Store()
        or CN.Account("achievements")

    local key       = CN.characterKey or CN.GetCharacterKey()
    local threshold = achievements.nearlyDoneThreshold or 2

    -- Outside the shortlist, inside the band: exactly the row the sweep
    -- could not see. `band` is twice the threshold, so threshold + 1 is
    -- approaching without being nearly done.
    local id = 909093

    store[id] = {
        id        = id,
        criteria  = 40,
        completed = false,
        progress  = { [key] = 40 - (threshold + 1) },
    }

    assert(not achievements.IsNearlyDone(store[id]),
        "the fixture row starts off the shortlist")

    local realProgress = CN.Blizzard.GetAchievementProgress

    CN.Blizzard.GetAchievementProgress = function(achievementID)
        if achievementID == id then
            -- One more criterion done: now inside the shortlist.
            return 40 - threshold, 40
        end

        return realProgress(achievementID)
    end

    CN.ForgetDebounces()
    CN.Dispatch("CRITERIA_UPDATE")

    CN.Blizzard.GetAchievementProgress = realProgress

    assert(achievements.DoneFor(store[id]) == 40 - threshold,
        "the sweep must observe a row that was approaching the shortlist, "
        .. "not only rows already on it; got "
        .. tostring(achievements.DoneFor(store[id])))

    assert(achievements.IsNearlyDone(store[id]),
        "and that row is now on the shortlist")

    -- AND A ROW NOWHERE NEAR IT IS STILL NOT POLLED, which is the saving the
    -- watch set exists for: a band, not the whole store.
    local far = 909094

    store[far] = {
        id        = far,
        criteria  = 40,
        completed = false,
        progress  = { [key] = 1 },
    }

    local asked = false

    CN.Blizzard.GetAchievementProgress = function(achievementID)
        if achievementID == far then
            asked = true
        end

        return realProgress(achievementID)
    end

    CN.ForgetDebounces()
    CN.Dispatch("CRITERIA_UPDATE")

    CN.Blizzard.GetAchievementProgress = realProgress

    assert(not asked,
        "a row 39 criteria from done is not polled every five seconds")

    store[id]  = nil
    store[far] = nil

    print("  an achievement enters the shortlist by getting closer to done")
end)()

;(function()
    ------------------------------------------------------------
    -- THE FUNCTION THAT WALKS EVERY CATEGORY STAMPS THE THROTTLE.
    ------------------------------------------------------------
    -- The transmog rescan stamp lived in the `TRANSMOG_COLLECTION_UPDATED`
    -- handler, so only that path advanced it. The login scan and
    -- `/cn appearancescan` both did the whole walk and left the throttle
    -- reading "never scanned" -- so a login followed seconds later by a
    -- looted appearance ran it twice. `Modules/Currencies.lua` records
    -- fixing this shape in 0.65.0 and `Modules/Pets.lua` in 0.92.0.
    local transmogModule = CN:GetModule("Appearances")

    local scans = 0

    local real = CN.Blizzard.GetAppearanceCategories

    CN.Blizzard.GetAppearanceCategories = function(...)
        scans = scans + 1

        return real(...)
    end

    transmogModule.Scan()

    assert(scans == 1, "the scan under test ran once")

    CN.ForgetDebounces()
    CN.Dispatch("TRANSMOG_COLLECTION_UPDATED")

    CN.Blizzard.GetAppearanceCategories = real

    assert(scans == 1,
        "a scan that just walked every category must have stamped its own "
        .. "throttle; the event ran it again after " .. scans .. " scans")

    print("  a transmog scan stamps its own throttle, whoever called it")
end)()

;(function()
    ------------------------------------------------------------
    -- A RECIPE LIST THE CLIENT HAS NOT SENT IS NOT A READ.
    ------------------------------------------------------------
    -- `IsTradeSkillReady` says the FRAME is ready; the recipe list streams
    -- separately. `CaptureOpenProfession` wrote `recipesSeen = true` with a
    -- total of zero anyway -- and that flag is the one thing that stops the
    -- addon asking, so `/cn setup` dropped "open each profession window
    -- once", `/cn professions` printed "(0 of 0 recipes)", and the state
    -- survived every login because `Professions.Scan` preserves the field.
    -- Fifth writer of a shape `Currencies.Scan`'s header names three other
    -- modules for carrying.
    local professions = CN:GetModule("Professions")

    assert(professions, "the professions module must be loaded")

    CN_TEST_OpenTradeSkill()

    -- Start from a character that knows about the profession and has never
    -- had its recipe list read -- which is where a real player is the first
    -- time they open the window, and where an earlier block in this suite
    -- has already been.
    professions.Scan()

    for _, record in pairs(CN.character.professions or {}) do
        if record.skillLineID == 171 then
            record.recipesSeen = false
            record.recipeTotal = nil
            record.recipeKnown = nil
        end
    end

    CN_TEST_RECIPES_COLD = true

    local captured, seen = professions.CaptureOpenProfession()

    CN_TEST_RECIPES_COLD = false

    assert(captured == false and seen == 0,
        "a capture the client answered nothing for reports itself as one")

    -- The open profession -- Alchemy, skill line 171 -- is the one whose
    -- list was refused, and it must still be listed as waiting.
    local function Waiting(name)
        for _, listed in ipairs(professions.AwaitingRecipeCapture()) do
            if listed == name then
                return true
            end
        end

        return false
    end

    assert(Waiting("Profession1"),
        "the profession whose list was refused is still listed as awaiting "
        .. "it, which is the sentence that tells the player what to do; "
        .. "waiting: " .. table.concat(
            professions.AwaitingRecipeCapture(), ", "))

    -- AND THE WARM ONE STILL WORKS, so the guard is a guard and not a wall.
    local warmed, warmSeen, warmKnown = professions.CaptureOpenProfession()

    assert(warmed and warmSeen > 0 and warmKnown > 0,
        "a client that answers is recorded: " .. tostring(warmSeen))

    assert(not Waiting("Profession1"),
        "and it stops being listed once its list was really read")

    print("  a recipe list the client never sent is not recorded as read")
end)()

;(function()
    ------------------------------------------------------------
    -- THE QUEST-LOG SWEEP STAMPS ITS OWN THROTTLE.
    ------------------------------------------------------------
    -- `lastLogScan` was written by the `QUEST_LOG_UPDATE` handler alone, so
    -- the login hook and `/cn discoveractive` left it unarmed -- and that
    -- event fires within the same second in both cases. The sweep walks the
    -- quest log, then every related map's POIs, with a SavedVariables write
    -- and an async title request per pin. It ran twice at every login.
    local quests = CN:GetModule("Quests")

    local sweeps = 0

    local realPOIs = CN.Blizzard.GetQuestPOIsOnMap

    CN.Blizzard.GetQuestPOIsOnMap = function(...)
        sweeps = sweeps + 1

        return realPOIs(...)
    end

    quests.DiscoverActive()

    local afterFirst = sweeps

    assert(afterFirst > 0, "the sweep under test walked some maps")

    CN.Dispatch("QUEST_LOG_UPDATE")

    CN.Blizzard.GetQuestPOIsOnMap = realPOIs

    assert(sweeps == afterFirst,
        "a sweep that just walked every related map must have stamped its "
        .. "own throttle; the event walked " .. (sweeps - afterFirst)
        .. " more maps")

    print("  the quest-log sweep stamps its own throttle, whoever called it")
end)()

;(function()
    ------------------------------------------------------------
    -- FIRST REGISTRATION WINS, AND THE RECORD SAYS SO.
    ------------------------------------------------------------
    -- The collision row was written as `kept = existing.origin` and the next
    -- line then overwrote the row, so the LAST supplier to load won while
    -- `/cn selftest` told the player the first one had -- under a comment
    -- reading "First registration wins, and this says which that was". A
    -- player with two data addons disabled the wrong one.
    local Static = CN.Static

    local questID = 970773

    Static.UnregisterOrigin("SupplierOne")
    Static.UnregisterOrigin("SupplierTwo")

    local collisionsBefore = #Static.collisions

    local firstOK = Static.RegisterQuest(questID,
        { name = "Owned By The First" }, "SupplierOne")

    assert(firstOK, "the first supplier's row lands")

    local secondOK, why = Static.RegisterQuest(questID,
        { name = "Claimed By The Second" }, "SupplierTwo")

    assert(secondOK == false,
        "the second claim on one quest is refused, not applied silently")

    assert(type(why) == "string" and why:find("SupplierOne", 1, true),
        "and the refusal names who holds it: " .. tostring(why))

    local held = Static.quests[questID]

    assert(held and held.origin == "SupplierOne"
        and held.name == "Owned By The First",
        "the row that is kept is the row that stays: "
        .. tostring(held and held.origin))

    local row = Static.collisions[#Static.collisions]

    assert(#Static.collisions == collisionsBefore + 1,
        "one collision was recorded")

    assert(row.kept == "SupplierOne" and row.lost == "SupplierTwo",
        "and the record names the winner correctly: "
        .. tostring(row.kept) .. " over " .. tostring(row.lost))

    -- A SUPPLIER REPLACING ITS OWN ROWS HAS A WAY TO DO IT, which is what
    -- makes first-wins safe rather than merely strict.
    Static.UnregisterOrigin("SupplierOne")

    assert(Static.quests[questID] == nil,
        "withdrawing an origin takes its rows with it")

    assert(Static.RegisterQuest(questID, { name = "Second Time" },
        "SupplierOne"), "and the same supplier can then register again")

    Static.UnregisterOrigin("SupplierOne")

    table.remove(Static.collisions)

    print("  two suppliers claiming one quest: the first one keeps it")
end)()

;(function()
    ------------------------------------------------------------
    -- A CAP ON WHAT YOU HAVE EARNED IS NOT CLEARED BY SPENDING.
    ------------------------------------------------------------
    -- Every capped currency was named "Spend <name>" and reasoned "further
    -- earning is wasted until you spend it". For a cap measured against
    -- `totalEarned` that is advice which cannot be followed: spending moves
    -- the balance, the cap does not move, and the row came back at full
    -- urgency after every weekly reset.
    local currencyModule = CN:GetModule("Currencies")

    -- One currency capped on lifetime earnings and spent down to nothing,
    -- and one capped on the balance it holds.
    CN_TEST_SetTotalEarnedCurrency(4242, 2500, 2500, 0)

    currencyModule.Scan()

    local byID = {}

    for _, candidate in ipairs(CN.CollectCandidates(true) or {}) do
        if candidate.type == CN.objectiveTypes.CURRENCY then
            byID[candidate.id] = candidate
        end
    end

    local earned = byID[4242]

    assert(earned, "the currency capped on lifetime earnings is offered")

    assert(not tostring(earned.name):find("Spend", 1, true),
        "a cap on total earned is not asking to be spent: "
        .. tostring(earned.name))

    local capReasons = table.concat(CN.Reasons(earned) or {}, " ")

    assert(capReasons:find("spending will not raise it", 1, true),
        "and it says why: " .. said)

    -- AND THE ORDINARY CASE IS UNCHANGED, so this is a distinction and not a
    -- blanket rewording.
    local spendable

    for _, row in ipairs(currencyModule.Capped() or {}) do
        if not row.usesTotalEarned then
            spendable = byID[row.currencyID]
        end
    end

    assert(spendable,
        "the fixture also carries a currency capped on its balance")

    assert(tostring(spendable.name):find("Spend", 1, true),
        "a cap on the balance still asks to be spent: "
        .. tostring(spendable.name))

    CN_TEST_SetTotalEarnedCurrency(4242, nil)

    currencyModule.Scan()

    print("  a cap on total earned does not ask you to spend it")
end)()

;(function()
    ------------------------------------------------------------
    -- ONE COMMAND, ONE WALK OF THE NEIGHBOURHOOD.
    ------------------------------------------------------------
    -- `/cn discoveractive` called `DiscoverActive` -- which walks every
