    assert(walks == oneSweep,
        "the command walks the neighbourhood once, not twice: " .. walks
        .. " against " .. oneSweep)

    print("  /cn discoveractive counts the walk it already made")
end)()

;(function()
    ------------------------------------------------------------
    -- A MOUSEOVER RESOLVES AN ITEM ONCE.
    ------------------------------------------------------------
    -- `MountLines` and `PetLines` each turned the item into a collection id,
    -- and the "why you should care" block resolved both a second time --
    -- on what `bench.lua` calls the hottest path in the addon.
    local tooltipModule = CN:GetModule("Tooltips")

    local mountAsks, petAsks = 0, 0

    local realMountLookup = CN.Blizzard.GetMountFromItem
    local realPetLookup   = CN.Blizzard.GetPetSpeciesFromItem

    CN.Blizzard.GetMountFromItem = function(...)
        mountAsks = mountAsks + 1

        return realMountLookup(...)
    end

    CN.Blizzard.GetPetSpeciesFromItem = function(...)
        petAsks = petAsks + 1

        return realPetLookup(...)
    end

    -- 502 is the mount item in this fixture; it takes the collectible branch,
    -- which is the one that asked twice.
    tooltipModule.ItemLines(502, "A Mount In A Box")

    CN.Blizzard.GetMountFromItem      = realMountLookup
    CN.Blizzard.GetPetSpeciesFromItem = realPetLookup

    assert(mountAsks == 1,
        "one mouseover asks the mount journal once: " .. mountAsks)

    assert(petAsks == 1,
        "and the pet journal once: " .. petAsks)

    print("  a mouseover resolves the item once, not twice")
end)()

;(function()
    ------------------------------------------------------------
    -- A REFUSAL BETWEEN THE EXPAND AND THE RESTORE STILL RESTORES.
    ------------------------------------------------------------
    -- The currency sweep expands every collapsed header, reads, and puts them
    -- back. The size check between those two halves returns early when the
    -- client will not answer -- and that path skipped the restore, so a
    -- player whose list refused at that moment had their collapsed groups
    -- silently reopened and never put back, against this function's own
    -- promise that "what this addon changes to read, it changes back".
    local function CollapsedHeaders()
        local shut = 0

        for _, row in ipairs(CN_TEST_CURRENCY_ROWS) do
            if row.isHeader and row.isHeaderExpanded == false then
                shut = shut + 1
            end
        end

        return shut
    end

    local shutBefore = CollapsedHeaders()

    assert(shutBefore > 0, "the fixture has a header the player collapsed")

    local realSize = C_CurrencyInfo.GetCurrencyListSize
    local asks     = 0

    C_CurrencyInfo.GetCurrencyListSize = function(...)
        asks = asks + 1

        -- The first call is the one the expand pass makes; the second is the
        -- one that decides whether there is anything to read.
        if asks == 2 then
            return nil
        end

        return realSize(...)
    end

    local rows = CN.Blizzard.GetCurrencyList()

    C_CurrencyInfo.GetCurrencyListSize = realSize

    assert(#rows == 0,
        "a client that will not report a size reports no currencies")

    assert(CollapsedHeaders() == shutBefore,
        "and the player's collapsed headers are put back anyway: "
        .. CollapsedHeaders() .. " against " .. shutBefore)

    print("  a refused currency list still puts the headers back")
end)()

;(function()
    ------------------------------------------------------------
    -- A CURRENCY READ THE CLIENT REFUSED IS NOT A COMPLETED STEP.
    ------------------------------------------------------------
    -- `Currencies.Scan` documents `0, 0, 0` as its refusal -- "which is what
    -- the client returns while currency data is still streaming at login,
    -- which is exactly when `CN:OnLogin` runs this" -- and setup printed it
    -- in the success colour, counted it as scanned and let `completedAt` be
    -- stamped. `Setup.HasRun` then answers true for the life of the install:
    -- the login reminder never fires again while `/cn currencies` says "No
    -- currency data yet."
    --
    -- Third step to need this guard. 0.73.0 fixed `loremaster` and 0.86.0
    -- fixed `achievements`; neither asked which other step returns a refusal
    -- shaped like a success.
    local setupModule = CN:GetModule("Setup")

    assert(setupModule and setupModule.steps, "the setup module lists its steps")

    local function StepFor(key)
        for _, entry in ipairs(setupModule.steps) do
            if entry.key == key then
                return entry
            end
        end
    end

    for _, key in ipairs({ "currencies", "professions" }) do
        assert(StepFor(key), "setup runs a " .. key .. " step")
    end

    local held = CN_TEST_CURRENCY_ROWS

    CN_TEST_CURRENCY_ROWS = {}

    local ok, why = setupModule.RunStep(StepFor("currencies"))

    CN_TEST_CURRENCY_ROWS = held

    assert(ok == nil,
        "a currency sweep the client answered nothing for is reported as not "
        .. "ready, not as a success: " .. tostring(ok) .. " " .. tostring(why))

    assert(type(why) == "string" and why:find("not ready", 1, true),
        "and says which it was: " .. tostring(why))

    -- AND A REAL READ STILL PASSES, so this is a guard and not a wall.
    local warm, scanned = setupModule.RunStep(StepFor("currencies"))

    assert(warm == true and (scanned or 0) > 0,
        "a client that answers completes the step: " .. tostring(warm)
        .. " " .. tostring(scanned))

    -- THE RIGHT RETURN, WHICH IS THE HALF THAT IS EASY TO GET WRONG.
    --
    -- `Currencies.Scan` returns `seen, atCap, weeklyRemaining`. The guard's
    -- default reads the SECOND value, which is how many currencies are at
    -- their cap -- legitimately zero on a real account with nothing capped.
    -- Reading it here would report a perfectly good sweep as "the game was
    -- not ready yet" for ever, which is the shape 0.86.0 found in the
    -- Achievements step and this release could have reintroduced.
    --
    -- Every capped row removed, and the step must still pass.
    local capped = {}

    for index = #CN_TEST_CURRENCY_ROWS, 1, -1 do
        local row = CN_TEST_CURRENCY_ROWS[index]

        if row.maxQuantity and row.maxQuantity > 0 then
            table.insert(capped, 1, row)

            table.remove(CN_TEST_CURRENCY_ROWS, index)
        end
    end

    local uncapped, stillSeen = setupModule.RunStep(StepFor("currencies"))

    for _, row in ipairs(capped) do
        table.insert(CN_TEST_CURRENCY_ROWS, row)
    end

    assert(uncapped == true and (stillSeen or 0) > 0,
        "an account with nothing at its cap has still had its currencies "
        .. "read: " .. tostring(uncapped) .. " " .. tostring(stillSeen))

    CN:GetModule("Currencies").Scan()

    print("  a currency read the client refused does not complete setup")
end)()

;(function()
    ------------------------------------------------------------
    -- A WARDROBE THAT HAS NOT ANSWERED IS NOT AN EMPTY WARDROBE.
    ------------------------------------------------------------
    -- `Sets.All` cached `readable = true, rows = {}` when `GetAllSets`
    -- returned nothing, and the only invalidator is
    -- `TRANSMOG_COLLECTION_UPDATED` -- which fires when a transmog is
    -- COLLECTED. A player who collects nothing keeps the empty answer for the
    -- whole session: `/cn sets` reports zero and the Sets provider emits
    -- nothing, which is the "3 of 5 pieces" denominator this addon is
    -- otherwise short of.
    --
    -- `Modules/Instances.lua` reasons this out for the Adventure Guide under
    -- the header "A ZERO IS 'NOT YET', NOT 'NOTHING'". The sibling did not
    -- get it.
    local sets = CN:GetModule("Sets")

    assert(sets, "the sets module must be loaded")

    sets.Forget()

    local realAllSets = C_TransmogSets.GetAllSets

    C_TransmogSets.GetAllSets = function() return {} end

    local coldRows, coldReadable = sets.All()

    C_TransmogSets.GetAllSets = realAllSets

    assert(#coldRows == 0, "a cold wardrobe reports no sets")

    -- The very next call, with the client warm, must answer.
    local warmRows = sets.All()

    assert(#warmRows > 0,
        "a refusal must not be cached as an answer for the session; got "
        .. #warmRows .. " sets after the client warmed up")

    assert(coldReadable ~= nil, "the readable flag is still returned")

    -- AND THE WARM ANSWER *IS* CACHED, which is what the cache is for: the
    -- walk is one client call per set plus a piece query each.
    local asks = 0

    C_TransmogSets.GetAllSets = function(...)
        asks = asks + 1

        return realAllSets(...)
    end

    sets.All()
    sets.All()

    C_TransmogSets.GetAllSets = realAllSets

    assert(asks == 0,
        "a wardrobe that answered is read once and held: " .. asks)

    print("  a wardrobe that has not answered is not an empty wardrobe")
end)()

;(function()
    ------------------------------------------------------------
    -- A COLD COLLECTION SCAN IS NOT A SCAN.
    ------------------------------------------------------------
    -- `CN.MarkScanned` routes to `CN.NoteSetupStep`, so stamping it removes
    -- the step from `Setup.NeverScanned` for ever -- the new player is never
    -- told to run the scan, and the Scans tab reads "just now" over a read
    -- that returned nothing. Pets got this guard in 0.92.0, Currencies in
    -- 0.88.0, Achievements in 0.76.0, Exploration in 0.61.0 and Loremaster in
    -- 0.71.0; toys, mounts and titles were the three the sweep never reached,
    -- and all three run from `CN:OnLogin`.
    local scans = CN.Account("collectionScans")

    local cases = {
        {
            key    = "toys",
            module = "Toys",
            cold   = function() CN_TEST_TOYS_COLD = true end,
            warm   = function() CN_TEST_TOYS_COLD = false end,
        },
        {
            key    = "mounts",
            module = "Mounts",
            cold   = function()
                CN_TEST_MOUNTS_COLD = true
            end,
            warm   = function()
                CN_TEST_MOUNTS_COLD = false
            end,
        },
        {
            key    = "titles",
            module = "Titles",
            cold   = function()
                CN_TEST_TITLES_COLD = true
            end,
            warm   = function()
                CN_TEST_TITLES_COLD = false
            end,
        },
    }

    for _, case in ipairs(cases) do
        local module = CN:GetModule(case.module)

        assert(module, case.module .. " must be loaded")

        -- A real read first, so there is a stamp to be wrongly refreshed.
        case.warm()
        module.Scan()

        local stamped = scans[case.key]

        assert(stamped, case.key .. " records a real scan")

        scans[case.key] = 1

        case.cold()

        local seen = module.Scan()

        case.warm()

        assert(seen == 0,
            case.key .. " reports reading nothing when the client answered "
            .. "nothing: " .. tostring(seen))

        assert(scans[case.key] == 1,
            "and a read that returned nothing does not stamp " .. case.key
            .. " as scanned, which is what silences the setup reminder for "
            .. "the life of the install")

        module.Scan()

        assert(scans[case.key] ~= 1,
            "while a real read does stamp " .. case.key)
    end

    print("  a cold toy box, mount journal or title list is not a scan")
end)()

;(function()
    ------------------------------------------------------------
    -- A LOCKOUT YOU ARE NO LONGER SAVED TO IS NOT WORK.
    ------------------------------------------------------------
    -- The client reports a `locked` flag per saved instance, this addon has
    -- read it into the record since the function was written, and nothing
    -- ever looked at it: the filter inferred the same fact from the reset
    -- countdown instead. An expired row is listed with time still on it, so
    -- "six bosses of spent effort, expiring soon" -- the strongest urgency
    -- signal this addon emits -- was raised for an instance the player is not
    -- saved to, sending them to re-clear from zero.
    local instances = CN:GetModule("Instances")

    CN_TEST_SetLockouts({
        { name = "Still Saved", difficulty = "Normal", encounters = 8,
          defeated = 2, resetsIn = 3600, locked = true },
        { name = "Expired Raid", difficulty = "Normal", encounters = 8,
          defeated = 6, resetsIn = 3600, locked = false, id = 2147483101 },
    })

    local named = {}

    for _, lockout in ipairs(instances.Lockouts()) do
        named[lockout.name] = lockout
    end

    assert(named["Still Saved"],
        "a lockout the client says you are saved to is listed")

    assert(not named["Expired Raid"],
        "a lockout the client says you are NOT saved to is not listed, "
        .. "however much time its reset still shows")

    assert(named["Still Saved"].locked == true,
        "and the row carries the fact, so a reader can say why")

    -- AND NOTHING RANKS IT EITHER, which is where the wrong advice reached
    -- the player.
    CN.InvalidateCandidates()

    for _, candidate in ipairs(CN.CollectCandidates(true) or {}) do
        if candidate.type == CN.objectiveTypes.INSTANCE then
            assert(not tostring(candidate.name):find("Expired", 1, true),
                "and it is not offered as a next action: "
                .. tostring(candidate.name))
        end
    end

    CN_TEST_SetLockouts(nil)
    CN.InvalidateCandidates()

    print("  a lockout you are no longer saved to is not offered as work")
end)()

;(function()
    ------------------------------------------------------------
    -- A BAG OF CAGED PETS IS ONE SWEEP, NOT ONE PER PET.
    ------------------------------------------------------------
    -- `NEW_PET_ADDED` called `Pets.Scan` directly. `bench.lua` measures that
    -- at 2.554 ms against 1,800 species -- the most expensive single event in
    -- the benchmark by a factor of forty -- and every sweep also saves,
    -- clears and restores the player's own journal filters. `Routing.lua`
    -- debounces its own handler for this event and names this file as the
    -- reason.
    local sweeps = 0

    local realWith = CN.Blizzard.WithAllPetsShown

    CN.Blizzard.WithAllPetsShown = function(...)
        sweeps = sweeps + 1

        return realWith(...)
    end

    CN.ForgetDebounces()

    for _ = 1, 6 do
        CN.Dispatch("NEW_PET_ADDED")
    end

    CN.Blizzard.WithAllPetsShown = realWith

    assert(sweeps == 1,
        "six pets in one burst cost one journal sweep, not six: " .. sweeps)

    print("  a bag of caged pets costs one journal sweep")
end)()

;(function()
    ------------------------------------------------------------
    -- A PUBLISHED FUNCTION EXISTS BEFORE ANYTHING CALLS THE OTHER ONE.
    ------------------------------------------------------------
    -- `CN.UnregisterQuestDataProvider` was defined INSIDE the body of
    -- `CN.RegisterQuestDataProvider`, below four early returns -- so it came
    -- into existence only as a side effect of a successful registration. It
    -- happened to exist in game only because three provider files register
    -- unconditionally at load. Both tests for it registered first, so the
    -- ordering was invisible.
    assert(type(CN.UnregisterQuestDataProvider) == "function",
        "the withdrawal half of the published provider API is a function "
        .. "from load, not from the first successful registration")

    assert(CN.UnregisterQuestDataProvider("nothing registered under this name")
        == false,
        "and it answers for a name that was never registered rather than "
        .. "throwing")

    print("  the published provider API exists before anything registers")
end)()

;(function()
    ------------------------------------------------------------
    -- EVERY COMMAND THIS ADDON NAMES IN ITS OWN OUTPUT EXISTS.
    ------------------------------------------------------------
    -- `/cn find` with no matches told the player "Collections and goals are
    -- searched from what has been scanned; /cn scan fills them" -- and there
    -- is no `scan` command or alias anywhere in the tree, so the recovery
    -- instruction shown at the exact moment a player has failed to find
    -- something answered "Unknown command: scan". The command is `/cn setup`.
    --
    -- This is the rule about a comment naming a mechanism, applied to the
    -- half the player can see: a string naming a command is a claim, and this
    -- addon prints 126 commands' worth of them.
    local known = {}

    for name in pairs(CN.commands) do
        known[name] = true
    end

    -- A BARE `/cn` IS ITSELF A COMMAND, so the word after it in a sentence
    -- is ordinary prose. Listed rather than pattern-matched: an allowance
    -- written down is one the next reader can argue with, and a heuristic for
    -- "is this an English word" is one nobody can.
    local prose = {
        ["to"] = true,
    }

    local offenders = {}

    for _, relative in ipairs(CN_TEST_ADDON_FILES or {}) do
        local text = CN_TEST_ReadAddonFile(relative)

        if text then
            for line in (text .. "\n"):gmatch("([^\n]*)\n") do
                -- Comment lines are skipped: this file's own prose quotes
                -- commands that were removed, precisely to record that they
                -- were, and a lint that fires on its own history is a lint
                -- somebody deletes.
                if not line:match("^%s*%-%-") then
                    for quoted in line:gmatch('"([^"]*)"') do
                        for word in quoted:gmatch("/cn%s+([%a]+)") do
                            local lowered = string.lower(word)

                            if not known[lowered] and not prose[lowered] then
                                offenders[lowered] =
                                    offenders[lowered] or relative
                            end
                        end
                    end
                end
            end
        end
    end

    local named = {}

    for word, where in pairs(offenders) do
        table.insert(named, "/cn " .. word .. " (" .. where .. ")")
    end

    table.sort(named)

    assert(#named == 0,
        "every command this addon names in its own output must exist; these "
        .. "do not: " .. table.concat(named, ", "))

    -- AND THE CHECK ITSELF IS NOT VACUOUS, which is the failure mode of a
    -- lint that scans for a pattern: one that matches nothing passes.
    local sawOne = false

    for _, relative in ipairs(CN_TEST_ADDON_FILES or {}) do
        local text = CN_TEST_ReadAddonFile(relative)

        if text and text:find("/cn setup", 1, true) then
            sawOne = true
        end
    end

    assert(sawOne, "the scan found command references to check")

    print("  every command this addon names in its own output exists")
end)()

;(function()
    ------------------------------------------------------------
    -- A RELOAD ON THE SAME DAY DOES NOT MOVE TODAY INTO YESTERDAY.
    ------------------------------------------------------------
    -- `CurrentDayKey` invents a provisional key -- now plus twelve hours --
    -- until the client answers `GetQuestResetTime`, and that is exactly the
    -- state at `PLAYER_LOGIN`, where `BeginSession` calls `RollDay`. The
    -- estimate lands on a different day index from the true reset for roughly
    -- half of all login times, so the rollover fired against a perfectly good
    -- stored key: `/cn progress` read "Today: 0, Previous day: 12" after a
    -- reload on the same game day.
    --
    -- The guard that existed covered the ESTIMATE-to-REAL transition. This is
    -- the mirror -- REAL on disk, ESTIMATE in hand -- and it is the one that
    -- happens every login.
    local progress = CN:GetModule("Progress")

    assert(progress, "the progress module must be loaded")

    local store = CN.character and CN.character.progress

    assert(store, "the character has a progress store")

    -- A day's work, recorded against the client's real reset.
    progress.knownResetAt    = nil
    progress.resetIsEstimate = false

    local realReset = GetQuestResetTime

    -- THE FIXTURE MUST FORCE THE DISAGREEMENT, NOT HOPE FOR IT. 0.98.0.
    --
    -- The defect is that the twelve-hour ESTIMATE lands on a different day
    -- index from the real reset -- which it does for about half of all clock
    -- values. A fixed `3600` therefore reproduced it only when the suite
    -- happened to run in the right half of the day: the mutation covering
    -- this was killed in 0.96.0 and survived in 0.98.0 with no code change
    -- between, because the clock had moved. A test that is right half the
    -- time is the same shape as the bug it is testing.
    --
    -- The reset is chosen so the two keys always differ: one second away when
    -- the estimate has already crossed midnight, and just past the next
    -- midnight when it has not.
    local now      = time()
    local estimate = math.floor((now + 43200) / 86400)

    local resetIn = (math.floor((now + 1) / 86400) ~= estimate)
        and 1
        or (86400 - (now % 86400) + 100)

    assert(math.floor((now + resetIn) / 86400) ~= estimate,
        "the fixture's real reset and its estimate fall on different days, "
        .. "which is the whole scenario")

    GetQuestResetTime = function() return resetIn end

    local dayKey = progress.RollDay(store)

    store.dayKey      = dayKey
    store.today       = 12
    store.previousDay = 0

    -- Now log in again: same game day, and the client has not answered yet.
    progress.knownResetAt    = nil
    progress.resetIsEstimate = false

    GetQuestResetTime = function() return nil end

    progress.RollDay(store)

    assert(store.today == 12 and store.previousDay == 0,
        "a login before the client has said when the reset is must not move "
        .. "today into yesterday; today=" .. tostring(store.today)
        .. " previousDay=" .. tostring(store.previousDay))

    -- And when the client speaks, the key is still the right one.
    GetQuestResetTime = function() return resetIn end

    progress.knownResetAt    = nil
    progress.resetIsEstimate = false

    progress.RollDay(store)

    assert(store.today == 12,
        "and the count survives the client answering: "
        .. tostring(store.today))

    -- A GENUINE NEW DAY STILL ROLLS, so this is a guard and not a wall.
    store.dayKey = (store.dayKey or 0) - 1

    progress.RollDay(store)

    assert(store.today == 0 and store.previousDay == 12,
        "a real day boundary still rolls over: today="
        .. tostring(store.today) .. " previousDay="
        .. tostring(store.previousDay))

    -- AND A CORRUPT KEY IS NOT HELD FOREVER by the new guard, which is why it
    -- tests the type rather than merely the presence.
    store.dayKey      = "not-a-day"
    store.today       = 5
    store.previousDay = 0

    progress.knownResetAt    = nil
    progress.resetIsEstimate = false

    GetQuestResetTime = function() return nil end

    progress.RollDay(store)

    assert(type(store.dayKey) == "number" and store.today == 0,
        "a key that is not a number is rolled over rather than preserved: "
        .. tostring(store.dayKey))

    GetQuestResetTime = realReset

    progress.knownResetAt    = nil
    progress.resetIsEstimate = false

    store.today       = 0
    store.previousDay = 0
    store.dayKey      = progress.RollDay(store)

    print("  a reload on the same day does not move today into yesterday")
end)()

;(function()
    ------------------------------------------------------------
    -- A BANK THE CLIENT WOULD NOT DESCRIBE IS NOT A BANK THAT WAS READ.
    ------------------------------------------------------------
    -- `Fill` stamped `scannedAt = oldest or now`, and `oldest` is nil exactly
    -- when the client described no container at all -- which is the permanent
    -- state for a player who has bought no Warband bank tab. `/cn bags` then
    -- announced "Warband bank: 0 kinds of item, seen just now", for ever,
    -- about a bank this addon has never read.
    local inventory = CN:GetModule("Inventory")

    assert(inventory, "the inventory module must be loaded")

    local warband = CN.Account("warbandBank")

    for key in pairs(warband) do
        warband[key] = nil
    end

    local realSlots = C_Container.GetContainerNumSlots

    C_Container.GetContainerNumSlots = function() return 0 end

    inventory.ScanBank("warband")

    C_Container.GetContainerNumSlots = realSlots

    assert(warband.scannedAt == nil,
        "a bank the client would not describe carries no reading time: "
        .. tostring(warband.scannedAt))

    -- AND A REAL READ DOES STAMP ONE.
    --
    -- The container is set here rather than relied on from the fixture: an
    -- earlier block in this file deletes the account-bank tabs on its way
    -- out, and a test that depends on another test's leftovers is a test that
    -- passes for the wrong reason.
    local tab = inventory.accountBankIDs[1]

    CN_TEST_BAGS[tab] = { { itemID = 60004, stackCount = 5 } }

    inventory.ScanBank("warband")

    assert(type(warband.scannedAt) == "number",
        "a bank the client did describe carries one")

    -- AND A LATER REFUSAL DOES NOT ERASE THE EARLIER READING.
    --
    -- Not by a fallback -- the first draft of the fix added one and the
    -- mutation suite showed it changed nothing. `seenAt` is one of the two
    -- keys the wipe preserves, so a store that has ever been read keeps its
    -- per-container times and the stamp is recomputed from them. This asserts
    -- the property, not the mechanism.
    local stamped = warband.scannedAt

    C_Container.GetContainerNumSlots = function() return 0 end

    inventory.ScanBank("warband")

    C_Container.GetContainerNumSlots = realSlots

    assert(warband.scannedAt == stamped,
        "a refusal keeps whatever the last real read recorded: "
        .. tostring(warband.scannedAt) .. " against " .. tostring(stamped))

    CN_TEST_BAGS[tab] = nil

    for key in pairs(warband) do
        warband[key] = nil
    end

    print("  a bank the client would not describe is not a bank that was read")
end)()

;(function()
    ------------------------------------------------------------
    -- THE VALUE COLUMN GROWS WITH THE TEXT IN IT.
    ------------------------------------------------------------
    -- `Pitch()` and `CaptionHeight()` were both taught to follow
    -- `CN.TextScale()` in 0.90.0; `UI.VALUE_WIDTH` was not, and the width is
    -- applied unconditionally. FontStrings word-wrap by default and nothing
    -- in `UI/List.lua` turns that off, so at `/cn textsize 150` the widest
    -- thing any tab puts there needed about 285 pixels in a 210-pixel box,
    -- wrapped, and overflowed its row onto the one below -- on Collections
    -- and Warband, the two tabs that use the column most.
    --
    -- The same defect `UI/List.lua` records fixing for `ROW_HEIGHT`, one
    -- constant along, in the accessibility feature it calls "rebuilt
    -- precisely for the players least likely to go hunting for a command".
    local panel = CN.UI and CN.UI.listPanels and next(CN.UI.listPanels)

    assert(panel, "the window has a list to measure")

    local list = CN.UI.listPanels[panel]

    -- NO FILTER IN FORCE. An earlier block in this file types into the search
    -- box and does not clear it, and a filtered list renders its "nothing
    -- matches" row -- which has no value column at all, so the measurement
    -- below would be of the empty branch. A test that depends on what another
    -- test left behind is a test that passes for the wrong reason.
    if list.SetFilter then
        list:SetFilter("")
    end

    -- The row the constant was measured against, in its own comment.
    list:SetEntries({
        { text = "The Severed Threads",
          value = "412 account-wide, 96 this character" },
    })

    local row = list.rows and list.rows[1]

    assert(row and row.value, "the row has a value column")

    local normalWidth = row.value:GetWidth()

    assert(normalWidth and normalWidth > 1,
        "which has a width at normal size: " .. tostring(normalWidth))

    assert(CN.SetTextScale(1.5), "the text size can be raised")

    list:SetEntries({
        { text = "The Severed Threads",
          value = "412 account-wide, 96 this character" },
    })

    local biggerWidth = list.rows[1].value:GetWidth()

    CN.SetTextScale(1.0)

    assert(biggerWidth > normalWidth,
        "and the column grows with it: " .. tostring(biggerWidth)
        .. " against " .. tostring(normalWidth))

    -- THE TEST THAT MATTERS: what is drawn still fits in what it is drawn
    -- into. A column that merely got bigger could still be too small.
    local measured = row.value.GetStringWidth and row.value:GetStringWidth()

    if measured then
        assert(biggerWidth >= measured,
            "the enlarged string fits the enlarged column: " .. measured
            .. " into " .. biggerWidth)
    end

    -- AND A ROW WITH NO VALUE STILL GIVES ITS WHOLE WIDTH TO THE LABEL,
    -- which is what the zero-width branch is for and is most of the window.
    list:SetEntries({ { text = "No value here" } })

    assert(list.rows[1].value:GetWidth() < 1,
        "a row with no value keeps no column: "
        .. tostring(list.rows[1].value:GetWidth()))

    print("  the value column grows with the text in it")
end)()

;(function()
    ------------------------------------------------------------
    -- A COLD CRITERIA API DOES NOT ZERO WHAT WAS ALREADY MEASURED.
    ------------------------------------------------------------
    -- `Exploration.Scan` wrote `criteria = 0` over a good stored count and
    -- `done = 0` over this character's real progress, then stamped itself as
    -- a completed scan -- and `Exploration.Closest` and the candidate
    -- provider both filter on `criteria > 0`, so one `/cn setup` run in the
    -- first seconds after logging in emptied the "closest to finishing" list
    -- and silenced the provider. Permanently: nothing runs this scan on its
    -- own, and the setup reminder that would have sent the player back had
    -- just been switched off.
    --
    -- `Exploration.RefreshCurrentZone` has carried this guard since 0.61.0,
    -- thirty lines away in the same file, and FIVE other modules cite
    -- "Exploration in 0.61.0" as the precedent for the guard they carry. It
    -- landed at one call site and not at the other one beside it.
    local explorationModule = CN:GetModule("Exploration")

    assert(explorationModule, "the exploration module must be loaded")

    local scanned = explorationModule.Scan()

    assert(scanned > 0, "the warm client answers about some zones")

    local store = explorationModule.Store and explorationModule.Store()
        or CN.Account("exploration")

    local sampleID, sample

    for achievementID, record in pairs(store) do
        if (record.criteria or 0) > 0 then
            sampleID, sample = achievementID, record
            break
        end
    end

    assert(sample, "and at least one row has a criteria count")

    local heldCriteria = sample.criteria
    local heldDone     = explorationModule.DoneFor and explorationModule.DoneFor(sample)

    local scans = CN.Account("collectionScans")

    scans.exploration = 1

    -- THE CRITERIA API ALONE. The client still names every exploration
    -- achievement, and answers "0 criteria" for each -- so the scan has rows
    -- to walk and a zero to write into all of them. Silencing the category
    -- list as well would empty the loop, which is the harmless half.
    CN_TEST_CRITERIA_COLD = true

    local cold = explorationModule.Scan()

    CN_TEST_CRITERIA_COLD = false

    assert(cold == 0,
        "a sweep the criteria API refused reports reading nothing: " .. cold)

    assert(store[sampleID].criteria == heldCriteria,
        "and it does not write its refusal over a measured count: "
        .. tostring(store[sampleID].criteria) .. " was " .. tostring(heldCriteria))

    if heldDone then
        assert(explorationModule.DoneFor(store[sampleID]) == heldDone,
            "nor over this character's progress: "
            .. tostring(explorationModule.DoneFor(store[sampleID]))
            .. " was " .. tostring(heldDone))
    end

    assert(scans.exploration == 1,
        "and it does not record itself as a scan, which is what silences the "
        .. "setup reminder for the life of the install")

    explorationModule.Scan()

    assert(scans.exploration ~= 1, "while a real sweep does")

    print("  a cold criteria API does not zero what was already measured")
end)()

;(function()
    ------------------------------------------------------------
    -- ONE RENOWN LEVEL-UP IS ONE FACTION SWEEP.
    ------------------------------------------------------------
    -- `lastScan` was advanced by the `UPDATE_FACTION` handler alone, so the
    -- login hook, both renown handlers, `/cn repscan` and the candidate
    -- provider all ran the full sweep and left it unarmed -- and
    -- `UPDATE_FACTION` fires constantly, so the next tick swept again. A
    -- sweep walks every faction row three times and holds the player's
    -- collapsed headers open while it does.
    local reputations = CN:GetModule("Reputations")

    local sweeps = 0

    local realWith = CN.Blizzard.WithAllFactionsExpanded

    CN.Blizzard.WithAllFactionsExpanded = function(...)
        sweeps = sweeps + 1

        return realWith(...)
    end

    reputations.ForgetThrottle()

    reputations.Scan()

    local afterFirst = sweeps

    assert(afterFirst == 1, "the sweep under test ran once")

    CN.Dispatch("UPDATE_FACTION")

    assert(sweeps == afterFirst,
        "a sweep that just walked every faction must have stamped its own "
        .. "throttle; the event swept again")

    -- AND THE PLAYER ACTING IS STILL ANSWERED AT ONCE, which is what the
    -- handlers that clear the throttle are for.
    CN.Dispatch("MAJOR_FACTION_RENOWN_LEVEL_CHANGED", 2600, 13)

    assert(sweeps == afterFirst + 1,
        "a renown level-up is swept immediately: " .. sweeps)

    -- ...and exactly once. The scan re-stamps on its way out, so the
    -- `UPDATE_FACTION` that follows a renown gain finds the throttle fresh.
    CN.Dispatch("UPDATE_FACTION")

    CN.Blizzard.WithAllFactionsExpanded = realWith

    assert(sweeps == afterFirst + 1,
        "and not twice: " .. sweeps)

    print("  one renown level-up is one faction sweep")
end)()

;(function()
    ------------------------------------------------------------
    -- A FACTION LIST THE CLIENT HAS NOT SENT IS NOT AN EMPTY ONE.
    ------------------------------------------------------------
    local reputations = CN:GetModule("Reputations")

    local scans = CN.Account("collectionScans")

    scans.reputations = 1

    local realNum = C_Reputation.GetNumFactions

    C_Reputation.GetNumFactions = function() return 0 end

    local total = reputations.Scan()

    C_Reputation.GetNumFactions = realNum

    assert(total == 0, "a cold faction sweep reports reading nothing")

    assert(scans.reputations == 1,
        "and does not record itself as a scan; this is the FIRST step "
        .. "/cn setup runs, so it is the one most exposed to a cold client")

    reputations.ForgetThrottle()
    reputations.Scan()

    assert(scans.reputations ~= 1, "while a real sweep does")

    print("  a faction list the client has not sent is not an empty one")
end)()

;(function()
    ------------------------------------------------------------
    -- A LOCKOUT IS MATCHED ON THE JOURNAL'S ID, NOT ON A TRANSLATED NAME.
    ------------------------------------------------------------
    -- Both sides carry the Encounter Journal's instance id and the addon
    -- compared two localized display strings from two different APIs. When
    -- they differ by anything -- punctuation, a subtitle, a rename applied to
    -- one API and not the other -- `/cn drops` silently loses its "locked,
    -- resets in 2d 3h" clause and tells the player to go and kill a boss they
    -- are already saved to.
    local instances = CN:GetModule("Instances")

    CN_TEST_SetLockouts({
        { name = "Nerub-ar Palace", difficulty = "Normal", encounters = 8,
          defeated = 8, resetsIn = 7200, locked = true, instanceID = 1273 },
    })

    -- The journal's name for the same instance, spelled differently. This is
    -- the whole scenario: one id, two strings.
    local byID = instances.LockoutFor("Nerub-ar Palace (Raid)", nil, 1273)

    assert(byID and byID.instanceID == 1273,
        "the lockout is found through the id even when the names differ")

    local byName = instances.LockoutFor("Nerub-ar Palace (Raid)")

    assert(byName == nil,
        "and matching on the name alone is what used to fail silently")

    -- THE NAME STILL WORKS where a caller has no id, which is the fallback.
    local fallback = instances.LockoutFor("Nerub-ar Palace")

    assert(fallback and fallback.instanceID == 1273,
        "a caller with only a name still gets an answer")

    CN_TEST_SetLockouts(nil)
    CN.InvalidateCandidates()

    print("  a lockout is matched on the journal's id, not a translated name")
end)()

;(function()
    ------------------------------------------------------------
    -- THE PUBLISHED API SURFACE IS THE ADDON'S, NOT THE HARNESS'S.
    ------------------------------------------------------------
    -- `Data/ApiSurface.lua` is generated by walking the toolkit's file list,
    -- and that list includes `harness.lua` and `bench.lua` -- so every client
    -- API the offline STUBS mention was harvested into the list of names the
    -- ADDON references. `/cn capture` asks the live client which of these
    -- exist and the fixture audit fails on any it refused, so a name the
    -- addon never calls could report a client as missing something it does
    -- not need.
    assert(type(CN.apiSurface) == "table" and #CN.apiSurface > 0,
        "the addon publishes an API surface")

    local missing = {}

    for _, name in ipairs(CN.apiSurface) do
        local namespace, method = name:match("^(C_[%a]+)%.([%w_]+)$")

        if namespace then
            local found = false

            for _, relative in ipairs(CN_TEST_ADDON_FILES or {}) do
                local text = CN_TEST_ReadAddonFile(relative)

                if text and relative ~= "Data/ApiSurface.lua"
                    and text:find(namespace .. "." .. method, 1, true) then

                    found = true
                    break
                end
            end

            if not found then
                table.insert(missing, name)
            end
        end
    end

    assert(#missing == 0,
        "every name in the published surface is one the addon's own files "
        .. "reference; these are not: " .. table.concat(missing, ", "))

    print("  the published API surface is the addon's, not the harness's")
end)()

;(function()
    ------------------------------------------------------------
    -- A CALENDAR THAT HAS NOT ARRIVED IS NOT AN EVENT-FREE DAY.
    ------------------------------------------------------------
    -- `C_Calendar.OpenCalendar` is asynchronous, so the client answers "no
    -- events" until the month comes back -- and `CN:OnLogin` warms the cache
    -- by calling this with `force`, which skips the cache READ and still
    -- performs the cache WRITE. The empty answer was then held for the full
    -- half hour.
    --
    -- So for thirty minutes after every login the Darkmoon Faire, a
    -- Timewalking week and every holiday were absent from the ranking
    -- entirely: no row in `/cn next`, no map pin, no heads-up line, no
    -- "Active events" in `/cn now`. Only `/cn events` repaired it, because it
    -- passes `force` -- and nothing told the player to run it. The addon
    -- subscribes to no calendar event, so there was no other invalidator.
    local opportunities = CN:GetModule("Opportunities")

    assert(opportunities, "the opportunities module must be loaded")

    CN_TEST_CALENDAR_COLD = true

    -- Exactly what the login hook does.
    local cold = opportunities.GetActiveEvents(true)

    CN_TEST_CALENDAR_COLD = false

    assert(#cold == 0, "a cold calendar reports no events")

    -- And now the month arrives. Without `force`, which is what every reader
    -- in the addon uses.
    local warm = opportunities.GetActiveEvents()

    assert(#warm > 0,
        "an empty answer must not be cached for half an hour over a client "
        .. "that had simply not replied yet; got " .. #warm)

    -- AND A REAL ANSWER IS STILL HELD, which is what the cache is for: the
    -- calendar walk is a client call per event per day.
    local asks = 0

    local realNum = C_Calendar.GetNumDayEvents

    C_Calendar.GetNumDayEvents = function(...)
        asks = asks + 1

        return realNum(...)
    end

    opportunities.GetActiveEvents()
    opportunities.GetActiveEvents()

    C_Calendar.GetNumDayEvents = realNum

    assert(asks == 0,
        "a calendar that answered is read once and held: " .. asks)

    print("  a calendar that has not arrived is not an event-free day")
end)()

;(function()
    ------------------------------------------------------------
    -- "NOT NOW" SILENCES THE ALERT, NOT JUST THE LIST.
    ------------------------------------------------------------
    -- The heads-up alert checked `CN.IsIgnored` and not `CN.IsDeferred` --
    -- the only live call site in the addon missing its sibling. So deferring
    -- a rare removed it from every list and then let the addon make the one
    -- unsolicited noise it is capable of, a sound and a chat line, about that
    -- exact rare the next time it drifted into range.
    local brokerModule = CN:GetModule("Broker")

    assert(brokerModule and brokerModule.PendingAlerts,
        "the broker module must be loaded")

    local raresModule = CN:GetModule("Rares")

    local sighted = nil

    for _, vignette in ipairs(raresModule.GetActive() or {}) do
        if vignette.kind == "RARE" and vignette.vignetteID then
            sighted = vignette.vignetteID
            break
        end
    end

    assert(sighted, "the fixture has a rare in sight")

    CN.SetIgnored(CN.objectiveTypes.RARE, sighted, false)
    CN.SetDeferred(CN.objectiveTypes.RARE, sighted, nil)

    brokerModule.ResetAnnounced()

    assert(#brokerModule.PendingAlerts() > 0, "which would be announced")

    -- "Not now."
    CN.SetDeferred(CN.objectiveTypes.RARE, sighted, 3600)

    brokerModule.ResetAnnounced()

    assert(#brokerModule.PendingAlerts() == 0,
        "a rare put off is not announced; deferring hides it from every "
        .. "list, and the alert is the loudest thing this addon does")

    CN.SetDeferred(CN.objectiveTypes.RARE, sighted, nil)

    brokerModule.ResetAnnounced()

    assert(#brokerModule.PendingAlerts() > 0,
        "and it comes back when the deferral is lifted")

    print("  a rare put off is not announced either")
end)()

;(function()
    ------------------------------------------------------------
    -- PINNING A REPUTATION DOES NOT MAKE IT ACCOUNT-WIDE.
    ------------------------------------------------------------
    -- The Goals provider stamped `accountWide = true` on every goal whatever
    -- the type, and `Warband.Decorate` reads that as "the progress carries
    -- across the Warband" -- so it withdrew the suitability score and its
    -- sentence. Goals load before Reputations and the aggregate keeps the
    -- first provider, so the pinned row is the one that reached the scorer.
    --
    -- Declaring a faction a goal therefore switched off the "Bob is better
    -- suited" advice for it, while `/cn goals` went on printing "Best
    -- character: Bob" -- two surfaces contradicting each other about one row.
    local goalsModule = CN:GetModule("Goals")

    assert(goalsModule, "the goals module must be loaded")

    local factionID = 1090

    local pinned = false

    for _, candidate in ipairs(CN.candidateProviders["Goals"].fn() or {}) do
        if candidate.type == CN.objectiveTypes.REPUTATION then
            pinned = true

            assert(candidate.accountWide ~= true,
                "a pinned character-specific reputation is not claimed to "
                .. "be account-wide")
        end
    end

    if not pinned and goalsModule.Add then
        goalsModule.Add(CN.objectiveTypes.REPUTATION, factionID)

        for _, candidate in ipairs(CN.candidateProviders["Goals"].fn() or {}) do
            if candidate.type == CN.objectiveTypes.REPUTATION then
                pinned = true

                assert(candidate.accountWide ~= true,
                    "a pinned character-specific reputation is not claimed "
                    .. "to be account-wide")
            end
        end

        if goalsModule.Remove then
            goalsModule.Remove(CN.objectiveTypes.REPUTATION, factionID)
        end
    end

    assert(pinned, "the fixture could pin a reputation to check it")

    print("  pinning a reputation does not make it account-wide")
end)()

;(function()
    ------------------------------------------------------------
    -- TWO IDS WITH NO READER LEAVE THE LARGEST TWO STORES.
    ------------------------------------------------------------
    local aged = {
        version = 38,
        account = {
            mounts = { [1] = { mountID = 1, spellID = 555, collected = true } },
            pets   = { [2] = { speciesID = 2, petType = 3, collected = true } },
        },
        characters = {},
    }

    CN.RunMigrations(aged)

    assert(aged.account.mounts[1].spellID == nil
        and aged.account.mounts[1].collected == true,
        "the mount loses an id nothing reads and keeps what it is for")

    assert(aged.account.pets[2].petType == nil
        and aged.account.pets[2].collected == true,
        "and so does the pet")

    -- AND THE SCANS DO NOT PUT THEM BACK, which is what made every earlier
    -- sweep of these two stores temporary.
    CN:GetModule("Mounts").Scan()
    CN:GetModule("Pets").Scan()

    for _, record in pairs(CN.Account("mounts")) do
        assert(record.spellID == nil,
            "a rescan does not write the id back")
    end

    for _, record in pairs(CN.Account("pets")) do
        assert(record.petType == nil,
            "nor the pet type")
    end

    print("  two ids with no reader leave the largest two stores")
end)()

;(function()
    ------------------------------------------------------------
    -- THE ADDON'S OWN CURATED ROWS ACTUALLY REGISTER.
    ------------------------------------------------------------
    -- `Data/Quests.lua` shipped a row carrying `expansion`, which 0.91.0
    -- removed from the fields the registrar accepts -- so the addon's own
    -- curated table was refused at load. And the refusal was invisible:
    -- `RegisterQuests` reports to `Modules/Errors.lua`, which loads long
    -- after `Data/Quests.lua`, so the complaint reached a nil module and was
    -- dropped. `/cn provenance` reported zero curated rows and read as though
    -- the table had simply never been filled in.
    --
    -- Asserted from the file rather than from a count, because the count is
    -- also what a table nobody has written to looks like.
    local source = CN_TEST_ReadAddonFile("Data/Quests.lua")

    assert(source, "the curated data file is readable")

    local shipped, missing = 0, {}

    for questID in source:gmatch("%[%s*(%d+)%s*%]%s*=%s*{") do
        shipped = shipped + 1

        if not CN.Static.quests[tonumber(questID)] then
            table.insert(missing, questID)
        end
    end

    assert(shipped > 0, "the file ships at least one curated row")

    assert(#missing == 0,
        "every row this addon ships is registered; these were refused at "
        .. "load and nothing said so: " .. table.concat(missing, ", "))

    -- EVERY FIELD THE FILE USES IS ONE THE REGISTRAR ACCEPTS, which is the
    -- check that would have caught it before the row went missing.
    for _, field in ipairs({ "expansion" }) do
        assert(not CN.Static.validFields[field],
            "this list names fields the registrar has REMOVED; " .. field
            .. " is accepted again, so the check below is inverted")

        assert(not source:find("%f[%w]" .. field .. "%s*="),
            "the curated file still carries `" .. field .. "`, which the "
            .. "registrar refuses -- the whole row goes with it")
    end

    print("  the addon's own curated rows actually register")
end)()

;(function()
    ------------------------------------------------------------
    -- A COMPLAINT WITH NOWHERE TO GO WAITS RATHER THAN EVAPORATING.
    ------------------------------------------------------------
    -- The data layer loads before the error collector, so anything it
    -- refused at file-load time reported into nil. That is how the defect
    -- above stayed invisible for seven releases.
    local Static = CN.Static

    local errors = CN:GetModule("Errors")

    local heldModule = CN.modules.Errors

    -- The load-order state: the collector does not exist yet.
    CN.modules.Errors = nil

    Static.pendingComplaints = {}

    -- THROUGH THE REGISTRAR, NOT THROUGH THE HELPER. 0.98.0.
    --
    -- The first version of this called `Static.Complain` directly, so a
    -- mutation that put the old unconditional Errors lookup back into
    -- `RegisterQuests` changed nothing it could see. A test for "the reporter
    -- reports" has to go in at the door the reporting happens behind.
    local landed, rejected = Static.RegisterQuests({
        [970901] = { name = "Fine" },
        [970902] = { thisFieldDoesNotExist = true },
    }, "LoadOrderSupplier")

    assert(landed == 1 and rejected == 1,
        "one row landed and one was refused: " .. landed .. ", " .. rejected)

    assert(#Static.pendingComplaints == 1,
        "and the refusal is held rather than reported into a module that "
        .. "does not exist yet: " .. #Static.pendingComplaints)

    Static.UnregisterOrigin("LoadOrderSupplier")

    CN.modules.Errors = heldModule

    local ringBefore = #errors.All()

    local sent = Static.FlushComplaints()

    assert(sent == 1, "and delivered once the collector arrives: " .. sent)

    assert(#errors.All() > ringBefore,
        "into the ring the player reads with /cn errors")

    assert(#Static.pendingComplaints == 0,
        "and not delivered twice")

    print("  a complaint with nowhere to go waits rather than evaporating")
end)()

;(function()
    ------------------------------------------------------------
    -- THE STORE PAGE'S NUMBERS ARE THE ADDON'S NUMBERS.
    ------------------------------------------------------------
    -- The page said "Eighteen checks" against twenty, "the two tabs that have
    -- no list" against one, and `/cn textsize <100-150>` against a real
    -- ceiling of 200 -- the accessibility control, on the page where somebody
    -- decides whether this addon can be made readable at all, quoting a limit
    -- `Modules/Hud.lua` records correcting in the addon itself in 0.88.0.
    --
    -- A page is the one artefact a player reads before installing, and every
    -- number on it is a claim. These are the ones a machine can check.
    local page = CN_TEST_ReadAddonFile("_curseforge/DESCRIPTION.md")

    assert(page, "the store description ships in the tree and is readable")

    -- 1. The self-test count.
    local words = {
        ["Ten"] = 10, ["Eleven"] = 11, ["Twelve"] = 12, ["Thirteen"] = 13,
        ["Fourteen"] = 14, ["Fifteen"] = 15, ["Sixteen"] = 16,
        ["Seventeen"] = 17, ["Eighteen"] = 18, ["Nineteen"] = 19,
        ["Twenty"] = 20, ["Twenty-one"] = 21, ["Twenty-two"] = 22,
        ["Twenty-three"] = 23, ["Twenty-four"] = 24, ["Twenty-five"] = 25,
    }

    local claimed = page:match("([%a%-]+) checks that run against your own client")

    assert(claimed, "the page says how many self-tests there are")

    assert(words[claimed] == #CN.selfTests,
        "and the number is the number: the page says " .. tostring(claimed)
        .. " (" .. tostring(words[claimed]) .. ") and the addon registers "
        .. #CN.selfTests)

    -- 2. The text-size ceiling, which is the accessibility control.
    local low, high = page:match("/cn textsize <(%d+)%-(%d+)>")

    assert(low and high, "the page documents the text size range")

    local realLow, realHigh = 100, 100

    while CN.SetTextScale((realHigh + 10) / 100) do
        realHigh = realHigh + 10

        if realHigh > 400 then
            break
        end
    end

    CN.SetTextScale(1.0)

    assert(tonumber(low) == realLow and tonumber(high) == realHigh,
        "and its bounds are the ones the command accepts: the page says "
        .. low .. "-" .. high .. ", the addon takes " .. realLow .. "-"
        .. realHigh)

    -- 3. Every command the page names exists. 0.96.0 checks the addon's own
    --    output; the page is the other half, and it names fifty of them.
    local named, missing = 0, {}

    for command in page:gmatch("/cn%s+([%a]+)") do
        named = named + 1

        if not CN.commands[string.lower(command)] then
            missing[command] = true
        end
    end

    assert(named > 20, "the page names commands to check: " .. named)

    local names = {}

    for command in pairs(missing) do
        table.insert(names, "/cn " .. command)
    end

    table.sort(names)

    assert(#names == 0,
        "every command the store page names exists; these do not: "
        .. table.concat(names, ", "))

    print("  the store page's numbers are the addon's numbers")
end)()

;(function()
    ------------------------------------------------------------
    -- THE EMPTY-LIST EXPLANATION POINTS AT A COMMAND ABOUT DEADLINES.
    ------------------------------------------------------------
    -- It said "`/cn waiting` for what is on a timer". That resolves -- as an
    -- alias of `/cn unpicked`, "quests you have walked past and never picked
    -- up" -- so the addon's single explanation for "I have nothing to tell
    -- you" sent the player to the wrong list, and on a fresh account that
    -- list answers "Nothing remembered yet".
    --
    -- 0.96.0's lint checks that every command the addon names EXISTS. This
    -- one did. Existence is not meaning, and this is the assertion that
    -- covers the difference.
    local lines = CN.ExplainEmptyList()

    local text = table.concat(lines or {}, " ")

    assert(text ~= "", "the addon explains an empty list")

    if text:find("on a timer", 1, true) then
        assert(text:find("/cn clock", 1, true),
            "what is on a timer is `/cn clock`: " .. text)

        assert(not text:find("/cn waiting", 1, true),
            "and not `/cn waiting`, which lists quests you walked past")
    end

    print("  the empty-list explanation points at a command about deadlines")
end)()

;(function()
    ------------------------------------------------------------
    -- A COLD JOURNAL DOES NOT COMPLETE SETUP.
    ------------------------------------------------------------
    -- Five of the twelve steps carried no `measured` flag, so `RunStep`
    -- returned success for a scan that read nothing, `notReady` stayed zero
    -- and `Setup.Run` stamped `completedAt`. `Setup.HasRun` short-circuits on
    -- that stamp BEFORE it consults `NeverScanned`, so the module-side guards
    -- 0.92.0 and 0.95.0 added were defeated by the one thing they exist to
    -- protect -- on the first-hour path, with no command that gets the prompt
    -- back.
    local setupSteps = CN:GetModule("Setup")

    local function StepFor(key)
        for _, entry in ipairs(setupSteps.steps) do
            if entry.key == key then
                return entry
            end
        end
    end

    local cold = {
        toys        = function(on) CN_TEST_TOYS_COLD     = on end,
        mounts      = function(on) CN_TEST_MOUNTS_COLD   = on end,
        titles      = function(on) CN_TEST_TITLES_COLD   = on end,
        appearances = function(on) CN_TEST_WARDROBE_COLD = on end,
    }

    for key, setCold in pairs(cold) do
        local step = StepFor(key)

        assert(step, "setup runs a " .. key .. " step")

        assert(step.retry and CN.commands[step.retry],
            key .. " names a real command to try again with: "
            .. tostring(step.retry))

        setCold(true)

        local ok, why = setupSteps.RunStep(step)

        setCold(false)

        assert(ok == nil,
            "a cold " .. key .. " read is reported as not ready, not as a "
            .. "success: " .. tostring(ok) .. " " .. tostring(why))

        local warm = setupSteps.RunStep(step)

        assert(warm == true,
            "and a client that answers completes the step: " .. tostring(warm))
    end

    print("  a cold journal does not complete setup")
end)()

;(function()
    ------------------------------------------------------------
    -- "SCAN EVERYTHING" COUNTS WHAT IT READ.
    ------------------------------------------------------------
    -- The button treated `pcall` returning true as "the scan worked", so a
    -- cold journal -- which returns zero without throwing -- was stamped as a
    -- completed setup step, undoing the modules' own refusal. This is the
    -- button the Collections tab's empty text points a new player at, pressed
    -- at the moment the journals are coldest.
    local panel = nil

    for _, tab in ipairs(CN.UI.tabs or {}) do
        if tab.name == "Collections" and tab.panel and tab.panel.scanAll then
            panel = tab.panel
            break
        end
    end

    assert(panel, "the Collections tab has its Scan everything button")

    local steps = CN:GetModule("Setup").Steps()

    for _, key in ipairs({ "toys", "mounts", "titles", "appearances" }) do
        steps[key] = nil
    end

    CN_TEST_TOYS_COLD     = true
    CN_TEST_MOUNTS_COLD   = true
    CN_TEST_TITLES_COLD   = true
    CN_TEST_WARDROBE_COLD = true

    -- THROUGH THE SCRIPT, because the offline button has no `Click`: the
    -- client's method is what a player's mouse reaches, and the harness
    -- models the handler rather than the input stack.
    local press = panel.scanAll:GetScript("OnClick")

    assert(type(press) == "function", "the button has a click handler")

    local answered = nil

    local realAnswer = CN.UI.Answer

    CN.UI.Answer = function(text)
        answered = tostring(text)

        return realAnswer(text)
    end

    press(panel.scanAll)

    -- The button defers its work by one frame so the client can repaint the
    -- "Working..." caption first.
    CN_TEST_DrainDeferred()

    CN_TEST_TOYS_COLD     = false
    CN_TEST_MOUNTS_COLD   = false
    CN_TEST_TITLES_COLD   = false
    CN_TEST_WARDROBE_COLD = false

    local stamped = {}

    for _, key in ipairs({ "toys", "mounts", "titles", "appearances" }) do
        if steps[key] then
            table.insert(stamped, key)
        end
    end

    assert(#stamped == 0,
        "a button press that read nothing stamps nothing; these were "
        .. "recorded as scanned: " .. table.concat(stamped, ", "))

    -- AND IT SAYS SO. The count in that sentence is the other half of the
    -- same claim: "Read 6 collections" over six refusals is the addon
    -- telling the player it did something it did not, on the tab it points
    -- them at.
    assert(answered and answered ~= "",
        "the button answers in the window")

    assert(not answered:find("Read 6", 1, true),
        "and does not claim to have read six collections it could not read: "
        .. answered)

    -- Two of the six -- pets and professions -- are not cold in this
    -- scenario, so "Read 2 collections" is the honest sentence and the
    -- assertion is that the count is what was READ, not what was tried.
    local claimed = tonumber(answered:match("Read (%d+) collections"))

    assert(claimed and claimed < 6,
        "the sentence counts what answered, not what was attempted: " .. answered)

    -- AND A REAL PRESS DOES STAMP THEM, so this is a guard and not a wall.
    press(panel.scanAll)

    CN_TEST_DrainDeferred()

    local read = 0

    for _, key in ipairs({ "toys", "mounts", "titles", "appearances" }) do
        if steps[key] then
            read = read + 1
        end
    end

    CN.UI.Answer = realAnswer

    assert(read > 0,
        "and a press against a client that answers records what it read: "
        .. read)

    -- AND A PROFESSION SCAN ON A CHARACTER WITH NONE IS A SCAN THAT WORKED.
    -- 1.0.0.
    --
    -- Five of the six modules behind this button count the length of the
    -- client's own list, so `> 0` is the right test for them.
    -- `Professions.Scan` counts what this CHARACTER has learned, and a
    -- character who has learned none reads zero on a scan that answered
    -- perfectly -- so the count has to consult whether it ANSWERED, or a new
    -- player who also owns no pets, mounts, toys or titles is told the game
    -- would not answer about any of them.
    local warmAnswer = nil

    CN.UI.Answer = function(text)
        warmAnswer = tostring(text)

        return realAnswer(text)
    end

    CN_TEST_NO_PROFESSIONS = true

    press(panel.scanAll)

    CN_TEST_DrainDeferred()

    CN_TEST_NO_PROFESSIONS = false

    CN.UI.Answer = realAnswer

    local withNone = tonumber(tostring(warmAnswer):match("Read (%d+) collections"))

    assert(withNone == 6,
        "a character with no professions still had six collections read: "
        .. tostring(warmAnswer))

    print("  Scan everything counts what it read")
end)()

;(function()
    ------------------------------------------------------------
    -- THE SENTENCE ITSELF NAMES THE COMMAND ABOUT DEADLINES.
    ------------------------------------------------------------
    -- The behavioural check beside this one only fires when the fixture
    -- reaches that branch of the explanation, and a conditional assertion is
    -- an assertion that can be skipped -- which is exactly how the mutant
    -- covering this survived. The sentence is a fixed string in the source;
    -- assert it there, where it cannot be routed around.
    local source = CN_TEST_ReadAddonFile("Scoring.lua")

    assert(source, "the scoring file is readable")

    local line = source:match("([^\n]*for what is on a timer[^\n]*)")

    assert(line, "the explanation still offers something on a timer")

    assert(line:find("/cn clock", 1, true),
        "and names the command about deadlines: " .. line)

    -- Deliberately not "the file never mentions `/cn waiting`": the comment
    -- explaining why it must not be offered here says the name out loud, and
    -- a check that forbids its own explanation is a check somebody deletes.
    assert(not line:find("/cn waiting", 1, true),
        "and not `/cn waiting`, which lists quests you walked past: " .. line)

    print("  the sentence itself names the command about deadlines")
end)()

;(function()
    ------------------------------------------------------------
    -- A CHARACTER WITH NO PROFESSIONS CAN FINISH SETUP.
    --
    -- 0.99.0 gave the professions step `measured = true, measuredAt = 1` --
    -- the number of profession LINES -- alongside eight steps whose count is
    -- the length of the client's own list. Professions count what this
    -- CHARACTER has learned, so zero is a person rather than a refusal, and a
    -- measured zero returns not-ready, and `Setup.Run` refuses to stamp
    -- `completedAt` while any step is not ready. Setup became impossible to
    -- complete for every character in its first hours, which is when it is
    -- run.
    --
    -- Two assertions, because two things were wrong at once: the step's
    -- verdict, and the fact that the module had already called `MarkScanned`
    -- on the same run -- so `Setup.NeverScanned` called the step done in the
    -- same second the report called it not ready.
    ------------------------------------------------------------
    local setupModule  = CN:GetModule("Setup")
    local professions  = CN:GetModule("Professions")

    assert(setupModule and professions, "both modules are loaded")

    local step

    for _, entry in ipairs(setupModule.steps) do
        if entry.key == "professions" then
            step = entry
        end
    end

    assert(step, "the professions step is in the table")

    CN_TEST_NO_PROFESSIONS = true

    local record = CN.Account("setup")

    record.completedAt = nil
    record.steps       = {}

    local ok, lines = setupModule.RunStep(step)

    assert(ok == true,
        "a character with no professions completed the step, got "
        .. tostring(ok))

    assert(lines == 0, "and read no lines: " .. tostring(lines))

    assert(setupModule.StepDone("professions"),
        "and the module and the step agree that it was read")

    -- AND A CLIENT WITH NO PROFESSION API AT ALL IS STILL A REFUSAL.
    local realProfessions = GetProfessions

    GetProfessions = nil

    local noApi = setupModule.RunStep(step)

    GetProfessions        = realProfessions
    CN_TEST_NO_PROFESSIONS = false

    assert(noApi == nil,
        "a client with no profession API is reported as not ready, got "
        .. tostring(noApi))

    -- AND THE WHOLE RUN COMPLETES, which is the thing the player sees. The
    -- account stamp is the one value that silences the login reminder.
    record.completedAt = nil
    record.steps       = {}

    CN_TEST_NO_PROFESSIONS = true

    setupModule.Run()

    for _ = 1, #setupModule.steps + 4 do
        CN_TEST_DrainDeferred()
    end

    CN_TEST_NO_PROFESSIONS = false

    assert(CN.Account("setup").completedAt,
        "setup completes for a character with no professions")

    print("  a character with no professions can finish setup")
end)()

;(function()
    ------------------------------------------------------------
    -- "REFRESH WHAT IS STALE" COUNTS WHAT MOVED.
    --
    -- It counted every command that did not throw, and a cold client refuses
    -- without throwing -- so the button answered "Read 12 stale sources" over
    -- twelve sources that were still exactly as stale, and could never reach
    -- "Nothing is stale". Same defect 0.99.0 removed from the "Scan
    -- everything" button, in the same file, in the release whose comment on
    -- that fix reads "the fix landed at one call site and not at its sibling
    -- in the same file".
    ------------------------------------------------------------
    local record = CN.Account("setup")

    record.steps = {}

    CN_TEST_TOYS_COLD      = true
    CN_TEST_MOUNTS_COLD    = true
    CN_TEST_TITLES_COLD    = true
    CN_TEST_WARDROBE_COLD  = true
    CN_TEST_CRITERIA_COLD  = true
    CN_TEST_RECIPES_COLD   = true
    CN_TEST_NO_PROFESSIONS = true

    local refreshed, tried = CN.UI.RefreshStaleSources()

    CN_TEST_TOYS_COLD      = false
    CN_TEST_MOUNTS_COLD    = false
    CN_TEST_TITLES_COLD    = false
    CN_TEST_WARDROBE_COLD  = false
    CN_TEST_CRITERIA_COLD  = false
    CN_TEST_RECIPES_COLD   = false
    CN_TEST_NO_PROFESSIONS = false

    assert(tried and tried > 0,
        "the cold run had stale sources to try: " .. tostring(tried))

    assert(refreshed < tried,
        "and did not claim to have read every one of them: "
        .. tostring(refreshed) .. " of " .. tostring(tried))

    -- The four journals in the list above cannot have been read, whatever
    -- else answered.
    for _, key in ipairs({ "toys", "mounts", "titles", "appearances" }) do
        assert(not record.steps[key],
            "a refused scan stamps nothing: " .. key)
    end

    -- AND A WARM RUN DOES COUNT, so this is a guard rather than a wall.
    record.steps = {}

    local warm = CN.UI.RefreshStaleSources()

    assert(warm > 0,
        "a client that answers records what was read: " .. tostring(warm))

    print("  refreshing stale sources counts what actually moved")
end)()

;(function()
    ------------------------------------------------------------
    -- THE AGE OF A PER-CHARACTER STORE IS A PER-CHARACTER AGE.
    --
    -- The Sources tab read the account-wide stamp for all twelve rows. Two of
    -- them are read per character -- which is why `Setup.steps` marks them
    -- `perCharacter`, and why 0.76.0 wrote `StepDoneHere` for the login
    -- reminder. A fresh alt was shown its main's timestamps on the tab whose
    -- header is "Where every number in this addon comes from", and "Refresh
    -- what is stale" could not run either source because both looked fresh.
    ------------------------------------------------------------
    local setupModule = CN:GetModule("Setup")

    -- Every step read, right now, by SOMEBODY.
    local record = CN.Account("setup")

    record.steps = {}

    for _, step in ipairs(setupModule.steps) do
        record.steps[step.key] = time()
    end

    -- And this character has never read either per-character store.
    CN.Account("achievementScans")[CN.characterKey or CN.GetCharacterKey()] = nil
    CN.Account("loremasterScans")[CN.characterKey or CN.GetCharacterKey()] = nil

    local byLabel = {}

    for _, source in ipairs(CN.UI.Sources("stored")) do
        byLabel[source.label] = source
    end

    assert(byLabel["Achievements"] and byLabel["Zone achievements"],
        "both per-character rows are on the tab")

    assert(byLabel["Achievements"].at == nil,
        "an alt that never scanned achievements is not shown the main's time")

    assert(byLabel["Zone achievements"].at == nil,
        "nor the main's Loremaster time")

    -- AND AN ACCOUNT-WIDE ROW STILL READS THE ACCOUNT STAMP.
    assert(type(byLabel["Mounts"].at) == "number",
        "an account-wide source keeps its account-wide stamp")

    -- AND ONCE THIS CHARACTER SCANS, THE ROW CARRIES ITS OWN TIME.
    CN.Account("achievementScans")[CN.characterKey or CN.GetCharacterKey()] =
        time() - 60

    local after

    for _, source in ipairs(CN.UI.Sources("stored")) do
        if source.label == "Achievements" then
            after = source
        end
    end

    assert(type(after.at) == "number",
        "and a character that has scanned is dated by its own scan")

    print("  a per-character source is dated per character")
end)()

;(function()
    ------------------------------------------------------------
    -- `/cn setup again` PUTS THE PROMPT BACK.
    --
    -- `completedAt` was written once and read for the life of the install,
    -- with nothing in the addon able to clear it -- so a setup that completed
    -- against a warming-up client could never be redone, and `/cn setup
    -- check` answered for the whole account for ever.
    ------------------------------------------------------------
    local setupModule = CN:GetModule("Setup")

    CN.Account("setup").completedAt = time()

    CN.HandleSlashCommand("setup again")

    for _ = 1, #setupModule.steps + 4 do
        CN_TEST_DrainDeferred()
    end

    -- The command re-runs setup, so what is asserted is that the stamps were
    -- forgotten first: every step's record is from THIS run.
    local steps = setupModule.Steps()

    assert(next(steps) ~= nil, "and it scanned again rather than only clearing")

    -- The per-character markers go with them, or an alt's reset silently
    -- keeps its main's per-character verdict.
    CN.Account("setup").completedAt = time()
    CN.Account("achievementScans")[CN.characterKey or CN.GetCharacterKey()] =
        time()

    CN_TEST_CRITERIA_COLD = true

    CN.HandleSlashCommand("setup again")

    for _ = 1, #setupModule.steps + 4 do
        CN_TEST_DrainDeferred()
    end

    CN_TEST_CRITERIA_COLD = false

    assert(CN.Account("achievementScans")[CN.characterKey
        or CN.GetCharacterKey()] == nil,
        "a reset against a cold client forgets the per-character marker too")

    print("  /cn setup again forgets what setup recorded")
end)()

;(function()
    ------------------------------------------------------------
    -- AN EMPTY ITEM CACHE NAMES EVERYTHING ANYWAY.
    --
    -- The client answers `nil` for any item it has not seen this session.
    -- Eleven call sites take a name from it and the rule they rely on --
    -- "unknown names are skipped rather than guessed" -- had never been
    -- exercised. A regression guard rather than a fix: nothing was found
    -- wrong, and the state that would have shown it was unreachable.
    ------------------------------------------------------------
    CN_TEST_ITEM_CACHE_COLD = true

    local checked = 0

    for name, provider in pairs(CN.candidateProviders) do
        local ok, rows = pcall(provider.fn)

        assert(ok, "provider " .. name .. " survives an empty item cache: "
            .. tostring(rows))

        if type(rows) == "table" then
            for _, objective in ipairs(rows) do
                assert(type(objective.name) == "string"
                    and objective.name ~= ""
                    and not objective.name:find("nil", 1, true),
                    "provider " .. name .. " named an objective from an empty "
                    .. "item cache: " .. tostring(objective.name))

                checked = checked + 1
            end
        end
    end

    CN.UI.Show()

    for _, tab in ipairs(CN.UI.tabs) do
        if tab.refresh and tab.panel then
            local ok, err = pcall(tab.refresh, tab.panel)

            assert(ok, "the " .. tab.name
                .. " tab draws with an empty item cache: " .. tostring(err))
        end
    end

    CN_TEST_ITEM_CACHE_COLD = false

    assert(checked > 0, "and there were objectives to check")

    print("  " .. checked .. " objectives named with an empty item cache")
end)()

;(function()
    ------------------------------------------------------------
    -- WHERE A QUEST WAS HANDED IN IS RECORDED WHERE IT DIFFERS.
    --
    -- `turnInMapID/X/Y` has been a documented field in `Data/Quests.lua`
    -- since the three-phase quest model, `Static.GetQuestTurnIn` reads it and
    -- `Quests.WaypointFor` prefers it over the client's own moving waypoint
    -- -- and nothing in the addon had ever written one. The backlog carries
    -- it as item 7, "Turn-in NPC database", filed under *Later* on the
    -- grounds that an independent table was needed. What was needed was the
    -- `QUEST_TURNED_IN` handler, which already routed to `Harvest.Capture`
    -- and lost the waypoint to a setter that only writes nil fields.
    ------------------------------------------------------------
    local turnInHarvest = CN:GetModule("Harvest")

    assert(turnInHarvest, "the harvest module is loaded")

    local store = CN.Account("questHarvest")

    store[9001] = nil

    -- Accepted at the giver.
    CN_TEST_WAYPOINT_MOVED = { 84, 0.20, 0.80 }

    turnInHarvest.Capture(9001, "accepted")

    assert(store[9001], "the quest was captured on acceptance")

    assert(store[9001].turnInMapID == nil,
        "and acceptance records no turn-in location")

    -- Handed in somewhere else. The client points at the hand-in once the
    -- quest is ready, which is the one moment this coordinate exists.
    CN_TEST_WAYPOINT_MOVED = { 84, 0.55, 0.31 }

    turnInHarvest.Capture(9001, "turnedin")

    CN_TEST_WAYPOINT_MOVED = nil

    assert(store[9001].turnInMapID == 84,
        "the turn-in map is recorded: " .. tostring(store[9001].turnInMapID))

    assert(store[9001].turnInX == 0.55 and store[9001].turnInY == 0.31,
        "with the point the client gave at hand-in: "
        .. tostring(store[9001].turnInX) .. ", "
        .. tostring(store[9001].turnInY))

    -- AND THE PICK-UP LOCATION IS NOT OVERWRITTEN, which is the field every
    -- map pin and travel cost in the addon is drawn from.
    assert(store[9001].x == 0.20 and store[9001].y == 0.80,
        "and where it was picked up is untouched")

    -- AND A QUEST HANDED IN WHERE IT WAS TAKEN CARRIES NOTHING, because a row
    -- saying "handed in where you got it" is the ordinary case and the store
    -- is capped at two thousand rows.
    store[9002] = nil

    CN_TEST_WAYPOINT_MOVED = { 84, 0.20, 0.80 }

    turnInHarvest.Capture(9001, "turnedin")

    assert(store[9001].turnInX == 0.55,
        "a later identical turn-in does not overwrite the first")

    -- AND A ROW THAT HAS NEVER BEEN ANYWHERE ELSE CARRIES NOTHING.
    --
    -- "Handed in where you got it" is the ordinary case; recording it would
    -- put three numbers on nearly every row of a store capped at two
    -- thousand, and say nothing the pick-up coordinates do not already say.
    store[9001] = nil

    CN_TEST_WAYPOINT_MOVED = { 84, 0.20, 0.80 }

    turnInHarvest.Capture(9001, "accepted")
    turnInHarvest.Capture(9001, "turnedin")

    assert(store[9001].turnInMapID == nil
        and store[9001].turnInX == nil
        and store[9001].turnInY == nil,
        "a quest handed in where it was taken records no turn-in: "
        .. tostring(store[9001].turnInMapID) .. " "
        .. tostring(store[9001].turnInX))

    -- Put the differing pair back for the export and resolver checks below.
    store[9001] = nil

    turnInHarvest.Capture(9001, "accepted")

    CN_TEST_WAYPOINT_MOVED = { 84, 0.55, 0.31 }

    turnInHarvest.Capture(9001, "turnedin")

    CN_TEST_WAYPOINT_MOVED = nil

    -- AND THE EXPORT CARRIES IT, or the field is recorded for nobody: the
    -- export is how a harvested row reaches curation and Navigator Data.
    local text = turnInHarvest.BuildExport(true)

    assert(text:find("turnInMapID = 84", 1, true),
        "the export emits the turn-in map")

    assert(text:find("turnInX   = 0.55", 1, true)
        and text:find("turnInY   = 0.31", 1, true),
        "and the point with it")

    -- AND IT IS A FIELD THE DATA LAYER ACCEPTS, so a curated row built from
    -- this export is not silently refused.
    for _, field in ipairs({ "turnInMapID", "turnInX", "turnInY" }) do
        assert(CN.Static.validFields[field],
            "the data layer accepts " .. field)
    end

    -- AND THE WAYPOINT RESOLVER PREFERS IT, which is what the field is for.
    local added = CN.Static.RegisterQuest(770001, {
        name        = "Handed In Elsewhere",
        mapID       = 84,
        x           = 0.20,
        y           = 0.80,
        turnInMapID = 84,
        turnInX     = 0.55,
        turnInY     = 0.31,
    }, "harness")

    assert(added ~= false, "the curated row registers")

    local map, x, y = CN.Static.GetQuestTurnIn(770001)

    assert(map == 84 and x == 0.55 and y == 0.31,
        "and the data layer reads the turn-in back")

    CN.Static.UnregisterOrigin("harness")

    -- AND THE RESOLVER FALLS BACK TO WHAT THIS ACCOUNT WATCHED, when nothing
    -- curated exists and the client will not answer -- which is every quest
    -- but two, since `Data/Quests.lua` holds one curated row and Navigator
    -- Data ships two.
    local quests = CN:GetModule("Quests")

    local realReady = CN.Blizzard.IsQuestReadyForTurnIn
    local realPoint = CN.Blizzard.GetQuestWaypoint

    CN.Blizzard.IsQuestReadyForTurnIn = function(id) return id == 9001 end
    CN.Blizzard.GetQuestWaypoint      = function() return nil, nil, nil end

    local seenMap, px, py, source = quests.GetLocation(9001)

    CN.Blizzard.IsQuestReadyForTurnIn = realReady
    CN.Blizzard.GetQuestWaypoint      = realPoint

    assert(seenMap == 84 and px == 0.55 and py == 0.31,
        "a client that will not answer falls back to what was watched: "
        .. tostring(seenMap) .. " " .. tostring(px) .. " " .. tostring(py))

    assert(source == "harvested turn-in",
        "and says the answer is an observation: " .. tostring(source))

    print("  a quest handed in elsewhere records where")
end)()

;(function()
    ------------------------------------------------------------
    -- A QUEST THIS ADDON FIRST MEETS AT ITS HAND-IN HAS NO PICK-UP.
    --
    -- `set` writes a field only while it is nil, so the first capture of a
    -- quest wrote the hand-in point into `x` and `y` -- and a player who
    -- installs the addon halfway through a quest had that quest recorded as
    -- being OFFERED at the turn-in NPC. The row goes into `/cn export`, into
    -- Navigator Data's staging, and from there into a curated file whose
    -- header reads "every row in this file was checked by a person". The
    -- coordinate is real, the map is real, and the claim about it is wrong,
    -- which is the one kind of defect the curation pipeline cannot catch.
    ------------------------------------------------------------
    local firstSeen = CN:GetModule("Harvest")

    local store = CN.Account("questHarvest")

    store[9001] = nil

    CN_TEST_WAYPOINT_MOVED = { 84, 0.55, 0.31 }

    firstSeen.Capture(9001, "turnedin")

    CN_TEST_WAYPOINT_MOVED = nil

    local row = store[9001]

    assert(row, "the quest was captured")

    assert(row.turnInMapID == 84 and row.turnInX == 0.55
        and row.turnInY == 0.31,
        "the point is recorded as the hand-in: "
        .. tostring(row.turnInMapID) .. " " .. tostring(row.turnInX))

    assert(row.x == nil and row.y == nil,
        "and NOT as where the quest is offered: "
        .. tostring(row.x) .. ", " .. tostring(row.y))

    assert(row.mapID == 84,
        "the map is kept, because it is right either way")

    -- AND IT IS STILL A LOCATED ROW, or the one coordinate the client can
    -- never re-supply is dropped by the export that exists to carry it.
    assert(firstSeen.Located(row),
        "a turn-in with no pick-up is a location")

    local counts = firstSeen.Summary()

    assert(counts.turnInOnly > 0,
        "and `/cn harvest` counts it separately: " .. tostring(counts.turnInOnly))

    local text = firstSeen.BuildExport(true)

    assert(text:find("%[9001%]"),
        "the export carries a row located only by its hand-in")

    assert(not text:find("x         = 0.55", 1, true),
        "and does not call the hand-in point a pick-up")

    assert(text:find("picked up: NOT SEEN", 1, true),
        "and says which half it never saw")

    store[9001] = nil

    print("  a quest first met at its hand-in claims no pick-up")
end)()

;(function()
    ------------------------------------------------------------
    -- THE ITEM CACHE FILLING IS A CHANGE THE PROVIDERS HEAR ABOUT.
    --
    -- The client answers `nil` for any item it has not seen this session and
    -- fills in asynchronously. Two providers name their rows from it, with
    -- `or ("item " .. itemID)` behind them, and neither declared the event --
    -- so `/cn next` in the first seconds after a login read "Start: item
    -- 71715" and nothing ever re-asked. `Vendors` was worse: it joins vendor
    -- stock to recipes BY NAME and emitted nothing at all.
    ------------------------------------------------------------
    for _, name in ipairs({ "Inventory", "Vendors" }) do
        local provider = CN.candidateProviders[name]

        assert(provider and provider.events
            and provider.events["GET_ITEM_INFO_RECEIVED"],
            "the " .. name .. " provider declares the item cache's event")
    end

    -- SUBSCRIBED, or a declared event nobody registered is a comment.
    assert(CN.subscribedInvalidationEvents["GET_ITEM_INFO_RECEIVED"],
        "and the addon is listening for it")

    assert(CN.eventTable["GET_ITEM_INFO_RECEIVED"],
        "with a handler on the client's own event table")

    -- AND THE ROW IS RENAMED WHEN THE NAME ARRIVES.
    CN_TEST_ITEM_CACHE_COLD = true

    CN.InvalidateCandidates()

    local cold

    for _, objective in ipairs(CN.candidateProviders["Inventory"].fn()) do
        if tostring(objective.name):find("item %d") then
            cold = objective.name
        end
    end

    assert(cold, "a cold item cache names a row by its id")

    CN_TEST_ITEM_CACHE_COLD = false

    CN.FireEvent("GET_ITEM_INFO_RECEIVED", 60001)

    CN_TEST_DrainDeferred()

    local warm

    for _, objective in ipairs(CN.candidateProviders["Inventory"].fn()) do
        if objective.name == cold then
            warm = objective.name
        end
    end

    assert(warm == nil,
        "and the row is not still called " .. tostring(cold)
        .. " once the client has answered")

    -- AND A BURST OF THEM COSTS ONE PASS, NOT FOUR HUNDRED.
    --
    -- The client resolves a bagful, a bank, a merchant's stock and every
    -- quest reward in the seconds after a login, one event each. Every fire
    -- walked all twenty-odd providers to set a flag that was already set.
    assert(CN.burstInvalidationEvents["GET_ITEM_INFO_RECEIVED"],
        "the event is declared as one that arrives in bursts")

    local passes = 0

    local realInvalidate = CN.InvalidateCandidates

    CN.InvalidateCandidates = function(...)
        passes = passes + 1

        return realInvalidate(...)
    end

    -- Well inside the gathering window, so only the leading call runs.
    for _ = 1, 200 do
        CN.FireEvent("GET_ITEM_INFO_RECEIVED", 60001)
    end

    CN.InvalidateCandidates = realInvalidate

    assert(passes <= 2,
        "two hundred item arrivals cost at most two invalidation passes, "
        .. "not two hundred: " .. passes)

    -- AND THE GATHERED ONE STILL RUNS, or the debounce is a mute button.
    CN_TEST_DrainDeferred()

    print("  the item cache filling reaches the providers that read it")
end)()

;(function()
    ------------------------------------------------------------
    -- THE LOCKOUT LIST IS ASKED FOR, NOT WAITED FOR.
    --
    -- `GetNumSavedInstances` reads a table the client does not populate on its
    -- own: `RequestRaidInfo()` asks the server and `UPDATE_INSTANCE_INFO` is
    -- the answer. Without the request the count is zero for the whole session
    -- unless the player opens the Raid Info frame, which sends it for them --
    -- so every lockout-shaped answer this addon gives was silently empty for
    -- somebody who logged in and asked what to do next: `/cn lockouts`, the
    -- part-finished-raid candidate, the vault's dungeon row, and the
    -- "Dungeons and raids" section of the addon's own store page.
    --
    -- The addon was already LISTENING for the answer: the Instances provider
    -- declares `UPDATE_INSTANCE_INFO` with a comment reading "the client
    -- saying so". It had the handler and not the question. The same pattern
    -- is handled correctly for the calendar two hundred lines away in the
    -- same file -- `C_Calendar.OpenCalendar()` before reading day events --
    -- which is backlog rule 30 on two asynchronous systems.
    ------------------------------------------------------------
    CN_TEST_LOCKOUTS_UNREQUESTED = true
    CN_TEST_RAID_INFO_REQUESTS   = 0

    -- A LOADING SCREEN, which is what re-arms it. The latch inside
    -- `RequestSavedInstances` has been closed since this session's own login,
    -- forty thousand lines ago.
    CN.FireEvent("PLAYER_ENTERING_WORLD")

    assert(CN_TEST_RAID_INFO_REQUESTS >= 1,
        "entering the world asks the server for the lockout list: "
        .. CN_TEST_RAID_INFO_REQUESTS)

    assert(not CN_TEST_LOCKOUTS_UNREQUESTED,
        "and the server answers once it has been asked")

    -- AND A READ SENDS IT TOO, so no caller has to remember. This is the
    -- path a cold `/cn next` takes before any loading screen handler has run.
    CN.Blizzard.ForgetSavedInstanceRequest()

    CN_TEST_LOCKOUTS_UNREQUESTED = true
    CN_TEST_RAID_INFO_REQUESTS   = 0

    local cold = CN.Blizzard.GetSavedInstances()

    assert(CN_TEST_RAID_INFO_REQUESTS == 1,
        "reading a lockout asks for the list: " .. CN_TEST_RAID_INFO_REQUESTS)

    assert(#cold >= 0, "and the read answers")

    -- AND ONCE PER SESSION, because it is a server round trip and every read
    -- of a lockout goes through the function that sends it.
    local sentSoFar = CN_TEST_RAID_INFO_REQUESTS

    for _ = 1, 50 do
        CN.Blizzard.GetSavedInstances()
    end

    assert(CN_TEST_RAID_INFO_REQUESTS == sentSoFar,
        "fifty reads do not send fifty requests: "
        .. CN_TEST_RAID_INFO_REQUESTS)

    local rows = CN.Blizzard.GetSavedInstances()

    assert(#rows > 0,
        "the lockouts arrive after the request: " .. #rows)

    -- AND THE PROVIDER IS TOLD WHEN THEY DO, or the request buys nothing: the
    -- first read of the session comes back empty by construction.
    local provider = CN.candidateProviders["Instances"]

    assert(provider and provider.events
        and provider.events["UPDATE_INSTANCE_INFO"],
        "the instances provider declares the event that answers the request")

    assert(CN.subscribedInvalidationEvents["UPDATE_INSTANCE_INFO"],
        "and the addon is listening for it")

    print("  the lockout list is asked for, once, and heard when it arrives")
end)()

;(function()
    ------------------------------------------------------------
    -- A QUEST TITLE ARRIVING IS NOT AN ANNOUNCEMENT.
    --
    -- The handler printed a chat line per quest, and every path that reaches
    -- it is a background one: `CN.pendingQuestLoads` is written in exactly one
    -- place -- `Blizzard.GetQuestTitle(questID, true)` -- whose callers are
    -- the candidate provider walking this map's quest pins, the same provider
    -- walking up to twenty offers in three neighbouring zones, the map-pin
    -- sweep and `Chase`. There is no player-facing path into it at all:
    -- `/cn lookup` asks external providers and never requests a title.
    --
    -- So crossing into a zone whose pins the client has not cached printed a
    -- line for each of them, announcing titles for rows the player had not
    -- looked at. `Modules/Harvest.lua` states the rule: "nothing spams the
    -- chat frame at login".
    ------------------------------------------------------------
    -- CAPTURED AT THE CHAT FRAME, NOT AT `CN.Print`. Every module binds
    -- `local Print = CN.Print` in its header, so replacing the field at test
    -- time intercepts nothing -- which is how the first draft of this check
    -- passed against the very line it was written for.
    local spoke = {}

    local realAddMessage = DEFAULT_CHAT_FRAME.AddMessage

    DEFAULT_CHAT_FRAME.AddMessage = function(chatFrame, message)
        table.insert(spoke, tostring(message))
    end

    -- A background request, exactly as the provider makes it.
    CN.Blizzard.GetQuestTitle(4242, true)

    assert(CN.pendingQuestLoads[4242],
        "the request is recorded as pending")

    CN.FireEvent("QUEST_DATA_LOAD_RESULT", 4242, true)

    DEFAULT_CHAT_FRAME.AddMessage = realAddMessage

    assert(#spoke >= 0, "the chat frame was reachable")

    for _, line in ipairs(spoke) do
        assert(not line:find("4242", 1, true),
            "a title arriving in the background says nothing in chat: " .. line)
    end

    -- AND THE TITLE IS STILL RECORDED, or the quiet is bought by doing less.
    local quests = CN:GetModule("Quests")

    assert(quests.GetName(4242),
        "the title that arrived is stored")

    -- AND THE PROVIDER THAT ASKED IS TOLD.
    local provider = CN.candidateProviders["Quests"]

    assert(provider and provider.events
        and provider.events["QUEST_DATA_LOAD_RESULT"],
        "the provider that requests titles declares the event that answers it")

    assert(CN.burstInvalidationEvents["QUEST_DATA_LOAD_RESULT"],
        "and it is gathered, because up to forty arrive at once")

    print("  a quest title arriving is recorded, not announced")
end)()

;(function()
    ------------------------------------------------------------
    -- THE INBOX IS ASKED FOR, NOT WAITED FOR.
    --
    -- `GetInboxNumItems()` answers zero until the client has been handed the
    -- inbox, and `CheckInbox()` asks the server for it. `/cn waiting` carried
    -- a sentence apologising for the limitation -- "the client only hands the
    -- addon the inbox once you have looked at it" -- so it was understood and
    -- worked around in prose rather than removed. The candidate provider had
    -- no such sentence and simply emitted nothing, which means the most
    -- time-critical thing this addon tracks, mail whose attachments are about
    -- to be destroyed, was silently absent for the whole session.
    --
    -- Fourth instance of the request-shaped defect in three releases, and the
    -- second in `Modules/Waiting.lua` alone.
    ------------------------------------------------------------
    local waiting = CN:GetModule("Waiting")

    assert(waiting, "the waiting module is loaded")

    CN_TEST_INBOX_UNREQUESTED = true
    CN_TEST_INBOX_REQUESTS    = 0

    waiting.inboxAnswered = false

    CN.Blizzard.ForgetMailRequest()

    local mail, readable, answered = waiting.Mail()

    assert(CN_TEST_INBOX_REQUESTS >= 1,
        "reading the mailbox asks the server for it: "
        .. CN_TEST_INBOX_REQUESTS)

    assert(readable, "and the client can be read at all")

    assert(answered, "and the answer arrived")

    assert(#mail > 0,
        "the inbox arrives once it has been asked for: " .. #mail)

    -- AND ONCE PER SEGMENT, because `CheckInbox` is a server round trip and
    -- every read of the mailbox goes through the function that sends it.
    local sentSoFar = CN_TEST_INBOX_REQUESTS

    for _ = 1, 30 do
        waiting.Mail()
    end

    assert(CN_TEST_INBOX_REQUESTS == sentSoFar,
        "thirty reads do not send thirty requests: "
        .. CN_TEST_INBOX_REQUESTS)

    -- AND A LOADING SCREEN ASKS AGAIN: mail arrives while you play and
    -- expires on a clock, so an answer from before a loading screen is not an
    -- answer after it.
    CN_TEST_INBOX_REQUESTS = 0

    CN.FireEvent("PLAYER_ENTERING_WORLD")

    assert(CN_TEST_INBOX_REQUESTS >= 1,
        "entering the world asks for the mailbox again: "
        .. CN_TEST_INBOX_REQUESTS)

    -- AND "NOT ANSWERED YET" IS NOT "NO MAIL".
    --
    -- Both read as zero from the client, and this reported both as "the
    -- client answered, there is nothing there" -- a guard whose empty branch
    -- is also its failure branch, which is backlog rule 169.
    CN_TEST_INBOX_UNREQUESTED = true

    waiting.inboxAnswered = false

    local held = CheckInbox

    CheckInbox = function() end

    local none, canRead, gotAnswer = waiting.Mail()

    CheckInbox = held

    assert(canRead and #none == 0,
        "an unanswered request reads as an empty inbox from the client")

    assert(gotAnswer == false,
        "and the addon says it has not been answered rather than that there "
        .. "is no mail")

    CN_TEST_INBOX_UNREQUESTED = false

    waiting.inboxAnswered = true

    print("  the inbox is asked for, once, and an unanswered ask is not "
        .. "an empty mailbox")
end)()

;(function()
    ------------------------------------------------------------
    -- AN ITEM NAME THE CLIENT HAS NOT CACHED IS ASKED FOR.
    --
    -- 1.1.0 taught two providers to listen for `GET_ITEM_INFO_RECEIVED`,
    -- because a row named "Start: item 71715" never became a name. That was
    -- half of it: the event answers a request, and the branch this addon
    -- PREFERS does not make one. `C_Item.GetItemNameByID` reads the cache;
    -- `GetItemInfo` is the call that queues a load, and it is the fallback --
    -- so on any modern client the addon took the path that never asks and
    -- then waited for an answer that could not come.
    --
    -- The release that wrote backlog rule 168's ancestor committed the defect
    -- the rule describes: it asked who handles the event and not who sends
    -- the request.
    ------------------------------------------------------------
    CN_TEST_ITEM_LOADS     = 0
    CN_TEST_LAST_ITEM_LOAD = nil

    -- The session has already asked about several items by this point, and
    -- 1.5.0 asks once per item per session. Cleared so this measures the
    -- request rather than the latch.
    CN.Blizzard.ForgetItemRequests()

    -- A name the client HAS, which must not send a request.
    local known = CN.Blizzard.GetItemName(500)

    assert(known == "Test Toy", "a cached name is answered from the cache: "
        .. tostring(known))

    assert(CN_TEST_ITEM_LOADS == 0,
        "and asks the server for nothing: " .. CN_TEST_ITEM_LOADS)

    -- A name the client does not have.
    CN_TEST_ITEM_CACHE_COLD = true

    local missing = CN.Blizzard.GetItemName(60001)

    CN_TEST_ITEM_CACHE_COLD = false

    assert(missing == nil, "an uncached name is nil, not a guess")

    assert(CN_TEST_ITEM_LOADS == 1,
        "and the client is asked to load it: " .. CN_TEST_ITEM_LOADS)

    assert(CN_TEST_LAST_ITEM_LOAD == 60001,
        "for the item that was wanted: " .. tostring(CN_TEST_LAST_ITEM_LOAD))

    -- AND ONCE, NOT ONCE PER LOOK. 1.5.0.
    --
    -- 1.4.0 shipped this unlatched, with a comment arguing that the client
    -- de-duplicates a load already in flight. It does -- and that says
    -- nothing about the same miss happening again on the next rebuild.
    -- `Modules/Vendors.lua` measures its own loop at 2,503 lookups per
    -- rebuild, and the vendor provider rebuilds every five seconds, so a cold
    -- cache meant thousands of client calls a second for items the server may
    -- never answer about. No benchmark could see it: every benchmark runs
    -- with a warm cache, so the branch that makes the call is never taken.
    CN_TEST_ITEM_CACHE_COLD = true

    local askedAgain = CN_TEST_ITEM_LOADS

    for _ = 1, 500 do
        CN.Blizzard.GetItemName(60001)
    end

    CN_TEST_ITEM_CACHE_COLD = false

    assert(CN_TEST_ITEM_LOADS == askedAgain,
        "five hundred more looks at the same uncached item send no further "
        .. "requests: " .. (CN_TEST_ITEM_LOADS - askedAgain))

    -- AND A DIFFERENT ITEM IS STILL ASKED FOR, so the latch is a latch and
    -- not a mute.
    CN_TEST_ITEM_CACHE_COLD = true

    CN.Blizzard.GetItemName(60002)

    CN_TEST_ITEM_CACHE_COLD = false

    assert(CN_TEST_ITEM_LOADS == askedAgain + 1,
        "an item not asked about before is asked about: "
        .. CN_TEST_ITEM_LOADS)

    -- AND THE OLD PATH STILL WORKS, because a client without
    -- `GetItemNameByID` gets its load from `GetItemInfo` as a side effect and
    -- must not be made to ask twice.
    local heldItem = C_Item

    C_Item = nil

    local viaFlat = CN.Blizzard.GetItemName(500)

    C_Item = heldItem

    assert(viaFlat ~= nil,
        "a client with only the flat API still answers: " .. tostring(viaFlat))

    print("  an item name the client has not cached is asked for")
end)()

;(function()
    ------------------------------------------------------------
    -- AN UNANSWERED LOCKOUT REQUEST IS NOT AN EMPTY WEEK.
    --
    -- 1.2.0 found that the addon read the lockout list and never asked for
    -- it, and sent the request. It did not touch the other half: "the server
    -- has not answered yet" and "you are saved to nothing" both arrive as a
    -- count of zero, and `/cn instances` printed "You are not saved to
    -- anything" for both -- worst in the first seconds after a login, which
    -- is the moment the request was added for and the moment somebody types
    -- the command.
    --
    -- 1.4.0 fixed exactly this shape for the inbox and did not sweep for its
    -- siblings, which is backlog rule 30 inside two releases.
    ------------------------------------------------------------
    local instances = CN:GetModule("Instances")

    assert(instances, "the instances module is loaded")

    CN_TEST_LOCKOUTS_UNREQUESTED = true

    instances.answered = false

    CN.Blizzard.ForgetSavedInstanceRequest()

    local held = RequestRaidInfo

    -- A request that goes out and is not answered: the state between the
    -- login and the server's reply.
    RequestRaidInfo = function() end

    local rows, answered = instances.Lockouts()

    RequestRaidInfo = held

    assert(#rows == 0,
        "an unanswered request reads as an empty list from the client")

    assert(answered == false,
        "and the addon says it has not been answered rather than that the "
        .. "week is clear")

    -- AND THE COMMAND SAYS SO, rather than reporting a clear week.
    local spoke = {}

    local realAddMessage = DEFAULT_CHAT_FRAME.AddMessage

    DEFAULT_CHAT_FRAME.AddMessage = function(chatFrame, message)
        table.insert(spoke, tostring(message))
    end

    RequestRaidInfo = function() end

    CN.HandleSlashCommand("instances")

    RequestRaidInfo = held

    DEFAULT_CHAT_FRAME.AddMessage = realAddMessage

    local reported = table.concat(spoke, "\n")

    assert(not reported:find("not saved to anything", 1, true),
        "the command does not claim a clear week before the server has "
        .. "answered: " .. reported)

    assert(reported:find("Asking the server", 1, true),
        "and says what it is waiting for: " .. reported)

    -- AND ONCE THE ANSWER ARRIVES, the ordinary path is unchanged.
    CN_TEST_LOCKOUTS_UNREQUESTED = false

    instances.answered = false

    local warm, warmAnswered = instances.Lockouts()

    assert(#warm > 0 and warmAnswered,
        "the answered list is reported normally: " .. #warm)

    -- AND A GENUINELY CLEAR WEEK IS STILL A CLEAR WEEK, or the third state
    -- has replaced the second rather than joined it.
    local savedRows = CN_TEST_SAVED_INSTANCES

    CN_TEST_SAVED_INSTANCES = {}

    instances.answered = true

    local none, stillAnswered = instances.Lockouts()

    CN_TEST_SAVED_INSTANCES = savedRows

    assert(#none == 0 and stillAnswered,
        "an answered empty list is answered and empty")

    -- AND THE EVENT IS WHAT SAYS SO WHEN THE LIST IS EMPTY.
    --
    -- The count cannot: an empty answer and no answer are the same number.
    -- `UPDATE_INSTANCE_INFO` is the only signal that separates them, which is
    -- why both paths exist and why a test that only ever answers with rows
    -- cannot tell whether the handler is wired.
    local emptied = CN_TEST_SAVED_INSTANCES

    CN_TEST_SAVED_INSTANCES = {}

    instances.answered = false

    local beforeEvent = select(2, instances.Lockouts())

    assert(beforeEvent == false,
        "an empty list with no event is not an answer")

    CN.FireEvent("UPDATE_INSTANCE_INFO")

    local after = select(2, instances.Lockouts())

    CN_TEST_SAVED_INSTANCES = emptied

    assert(after == true,
        "and the client saying the list is in hand is what makes it one")

    print("  an unanswered lockout request is not an empty week")
end)()

print("\nALL HARNESS CHECKS PASSED")
